  brand:    {bg1:'#eef0ff', bg2:'#f2ecfb', bg3:'#e9eefe', card:'#fdfcff', card2:'#f3eefc', accent:'#4338ca', accent2:'#bf26d3', text:'#241f3d', muted:'#8a84ab', line:'#ddd6f5'},
