const LB_SVG_FEMALE = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="8" r="4.6"/><path d="M12 12.6v8M8.4 17.2h7.2"/></svg>';
