/* ---------------- Pinch-to-zoom message size ----------------
   Two-finger pinch over the chat scales every bubble's text/padding/avatar/media size via the
   --chat-zoom CSS custom property (see the calc(...* var(--chat-zoom,1)) rules on .chat-msg,
   .cm-name, .cm-time, .cm-action, .cm-avatar, .cm-media and .cm-voice) — it only touches those
   specific sizes, never the scrollable #chatMessages container's own box, so scrolling/height
   stay exactly as before. Each person's chosen size is saved locally (window.storage, per
   device/user, not shared) and restored automatically next time they open the chat. */
(function(){
  const CHAT_ZOOM_MIN = 0.7, CHAT_ZOOM_MAX = 2.0;
  const CHAT_ZOOM_STORAGE_KEY = 'chatMsgZoom';
  const wrap = document.getElementById('chatMessages');
  if(!wrap) return;
  let pinchStartDist = 0;
  let pinchStartZoom = 1;
  let currentZoom = 1;
  let pinchActive = false;
  let hintHideTimer = null;

  function applyZoom(z){
    currentZoom = Math.min(CHAT_ZOOM_MAX, Math.max(CHAT_ZOOM_MIN, z));
    wrap.style.setProperty('--chat-zoom', currentZoom);
  }
  async function persistZoom(){
    try{ if(window.storage) await window.storage.set(CHAT_ZOOM_STORAGE_KEY, String(currentZoom), false); }catch(err){}
  }
  function showZoomHint(){
    let hint = document.getElementById('chatZoomHint');
    if(!hint){
      hint = document.createElement('div');
      hint.id = 'chatZoomHint';
      hint.className = 'chat-zoom-hint';
      wrap.appendChild(hint);
    }
    hint.textContent = toFa(Math.round(currentZoom * 100)) + '٪';
    hint.classList.add('show');
    clearTimeout(hintHideTimer);
    hintHideTimer = setTimeout(()=> hint.classList.remove('show'), 700);
  }
  function touchDist(t1, t2){
    return Math.hypot(t1.clientX - t2.clientX, t1.clientY - t2.clientY);
  }
  wrap.addEventListener('touchstart', (e)=>{
    if(e.touches.length === 2){
      pinchActive = true;
      pinchStartDist = touchDist(e.touches[0], e.touches[1]);
      pinchStartZoom = currentZoom;
    }
  }, { passive:true });
  wrap.addEventListener('touchmove', (e)=>{
    if(!pinchActive || e.touches.length !== 2) return;
    e.preventDefault(); // stop the browser's own page-zoom from fighting our gesture
    if(pinchStartDist <= 0) return;
    const ratio = touchDist(e.touches[0], e.touches[1]) / pinchStartDist;
    applyZoom(pinchStartZoom * ratio);
    showZoomHint();
  }, { passive:false });
  function endPinch(){
    if(!pinchActive) return;
    pinchActive = false;
    pinchStartDist = 0;
    persistZoom();
  }
  wrap.addEventListener('touchend', endPinch);
  wrap.addEventListener('touchcancel', endPinch);

  // Restore this person's saved size as soon as the chat opens.
  (async function(){
    try{
      const res = window.storage ? await window.storage.get(CHAT_ZOOM_STORAGE_KEY, false) : null;
      const saved = res && res.value ? parseFloat(res.value) : NaN;
      if(!isNaN(saved)) applyZoom(saved);
    }catch(err){}
  })();
})();

(function(){
  const SWIPE_TRIGGER = 46;
  const SWIPE_MAX = 60;
  const wrap = document.getElementById('chatMessages');
  let cur = null;
  function findMsgEl(target){
    const el = target.closest ? target.closest('.chat-msg') : null;
    if(!el || el.dataset.bot === '1') return null;
    return el;
  }
  function ensureHint(el){
    let hint = el.querySelector('.cm-reply-hint');
    if(!hint){
      hint = document.createElement('span');
      hint.className = 'cm-reply-hint';
      hint.textContent = '↩';
      el.appendChild(hint);
    }
    return hint;
  }
  function resetEl(){
    if(!cur) return;
    cur.el.classList.remove('swiping');
    cur.el.style.transform = '';
    cur.hint.style.opacity = 0;
    cur.hint.style.transform = 'translateY(-50%) scale(.5)';
    cur.hint.classList.remove('ready');
  }
  function onStart(x, y, target){
    if(target.closest && target.closest('.cm-action, .cm-reply-quote')) return;
    const el = findMsgEl(target);
    if(!el) return;
    cur = { el, hint: ensureHint(el), startX: x, startY: y, dx: 0, active: false };
  }
  function onMove(x, y){
    if(!cur) return false;
    const dx = x - cur.startX, dy = y - cur.startY;
    if(!cur.active){
      if(Math.abs(dx) < 8 && Math.abs(dy) < 8) return false;
      if(Math.abs(dy) > Math.abs(dx)){ cur = null; return false; }
      cur.active = true;
      cur.el.classList.add('swiping');
    }
    if(dx <= 0){
      cur.dx = 0; cur.el.style.transform = ''; cur.hint.style.opacity = 0; cur.hint.classList.remove('ready');
      return true;
    }
    const capped = Math.min(dx, SWIPE_MAX);
    cur.dx = dx;
    cur.el.style.transform = `translateX(${capped}px)`;
    const p = Math.min(1, capped / SWIPE_TRIGGER);
    cur.hint.style.opacity = p;
    cur.hint.style.transform = `translateY(-50%) scale(${0.5 + p*0.5})`;
    cur.hint.classList.toggle('ready', dx >= SWIPE_TRIGGER);
    return true;
  }
  function onEnd(){
    if(!cur) return;
    const { el, dx, active } = cur;
    resetEl();
    if(active && dx >= SWIPE_TRIGGER) startReplyTo(el);
    cur = null;
  }
  wrap.addEventListener('touchstart', e=>{
    const t = e.touches[0];
    onStart(t.clientX, t.clientY, e.target);
  }, {passive:true});
  wrap.addEventListener('touchmove', e=>{
    if(!cur) return;
    const t = e.touches[0];
    if(onMove(t.clientX, t.clientY) && cur && cur.active) e.preventDefault();
  }, {passive:false});
  wrap.addEventListener('touchend', onEnd);
  wrap.addEventListener('touchcancel', onEnd);
  // Mouse support so the gesture also works when previewing on desktop.
  let mouseDown = false;
  wrap.addEventListener('mousedown', e=>{ mouseDown = true; onStart(e.clientX, e.clientY, e.target); });
  window.addEventListener('mousemove', e=>{ if(mouseDown) onMove(e.clientX, e.clientY); });
  window.addEventListener('mouseup', ()=>{ if(mouseDown){ mouseDown = false; onEnd(); } });
})();

/* ---------------- Long-press a message (or its name) → small action menu ----------------
   Telegram-style: hold on a bubble to open a menu with actions for that message/sender. */
let chatFilterUserId = null;
let chatFilterUsername = '';
function applyChatUserFilter(){
  const wrap = document.getElementById('chatMessages');
  if(!wrap) return;
  wrap.querySelectorAll('.chat-msg').forEach(el=>{
    const match = !chatFilterUserId || el.dataset.userId === chatFilterUserId;
    el.classList.toggle('cm-filtered-out', !match);
  });
  // Every bubble inside one .cm-group shares the same sender, so a group is only ever
  // fully shown or fully hidden — never a partial mix.
  wrap.querySelectorAll('.cm-group').forEach(g=>{
    g.classList.toggle('cm-filtered-out', !g.querySelector('.chat-msg:not(.cm-filtered-out)'));
  });
}
function setChatUserFilter(userId, username){
  if(!userId) return;
  chatFilterUserId = userId;
  chatFilterUsername = username || 'کاربر';
  const banner = document.getElementById('chatUserFilterBanner');
  const nameEl = document.getElementById('chatUserFilterName');
  if(nameEl) nameEl.textContent = chatFilterUsername;
  if(banner) banner.classList.add('show');
  applyChatUserFilter();
}
function clearChatUserFilter(){
  chatFilterUserId = null;
  chatFilterUsername = '';
  const banner = document.getElementById('chatUserFilterBanner');
  if(banner) banner.classList.remove('show');
  applyChatUserFilter();
}
const chatUserFilterClearBtn = document.getElementById('chatUserFilterClearBtn');
if(chatUserFilterClearBtn) chatUserFilterClearBtn.addEventListener('click', clearChatUserFilter);

/* ---------------- فیلترِ جنسیتِ چت (فقط دختر / فقط پسر / هردو) ----------------
   قاعده: کسی که فیلترش رو «هردو» گذاشته، پیامش هم تو دسته‌ی «هردو» دیده می‌شه هم تو
   دسته‌ی هم‌جنسِ خودش (چون هنوز خودش رو محدود نکرده)؛ ولی کسی که فیلترش رو رویِ «فقط
   دختر»/«فقط پسر» گذاشته، پیامش دیگه اصلاً تو دسته‌ی «هردو» دیده نمی‌شه — فقط برایِ
   بیننده‌هایِ هم‌جنسِ خودش. یعنی:
     • بیننده‌یِ «فقط دختر»/«فقط پسر»: پیامِ هر فرستنده‌ای با همون جنسیت رو می‌بینه، فرقی
       نداره خودِ فرستنده فیلترش «هردو» بوده یا هم‌جنسِ محدود.
     • بیننده‌یِ «هردو»: فقط پیامِ فرستنده‌هایی که خودشون هنوز رویِ «هردو» موندن رو می‌بینه —
       نه فرستنده‌ای که خودش رو به یه جنسیتِ خاص محدود کرده.
   sender_gender/sender_audience رویِ خودِ ردیفِ پیام (data-gender/data-audience، بالاتر
   تویِ publicChatMsgHtml) از تریگرِ سمتِ سرور میان (chat-gender-filter-supabase-schema.sql)،
   نه از کلاینت — پس اینجا فقط مقایسه‌ست، نه تصمیم‌گیریِ اعتمادی.
   لیدربورد و بازی‌ها (حکم/اسم‌فامیل/دابل) عمداً به این فیلتر کاری ندارن — فقط خودِ چت. */
function chatMsgMatchesGenderFilter(msgGender, msgAudience){
  if(chatGenderFilter === 'both') return msgAudience === 'both';
  return msgGender === chatGenderFilter;
}
function applyChatGenderFilter(){
  const wrap = document.getElementById('chatMessages');
  if(!wrap) return;
  wrap.querySelectorAll('.chat-msg').forEach(el=>{
    const match = chatMsgMatchesGenderFilter(el.dataset.gender || '', el.dataset.audience || 'both');
    el.classList.toggle('cm-gender-filtered-out', !match);
  });
  // عیناً هم‌الگو با applyChatUserFilter: هر .cm-group یه فرستنده‌ی ثابت داره، پس یا کامل
  // دیده می‌شه یا کامل مخفی — هیچ‌وقت نصفه‌نیمه.
  wrap.querySelectorAll('.cm-group').forEach(g=>{
    g.classList.toggle('cm-gender-filtered-out', !g.querySelector('.chat-msg:not(.cm-gender-filtered-out)'));
  });
}
// برچسبِ دکمه‌ی هدرِ چت رو با مقدارِ فعلیِ chatGenderFilter هماهنگ نگه می‌داره — هم موقعِ
// لاگین (بعدِ خوندنِ profile.chat_gender_filter)، هم بعدِ هر تغییرِ دستیِ کاربر.
function renderChatGenderFilterBtn(){
  const btn = document.getElementById('chatGenderFilterBtn');
  if(!btn) return;
  const label = chatGenderFilter === 'female' ? 'فقط دختر' : chatGenderFilter === 'male' ? 'فقط پسر' : 'هردو';
  const labelEl = btn.querySelector('.cpb-label');
  if(labelEl) labelEl.textContent = label;
  btn.classList.toggle('chat-gender-filter-active', chatGenderFilter !== 'both');
  document.querySelectorAll('#chatGenderFilterMenu .cgf-option').forEach(opt=>{
    opt.classList.toggle('active', opt.dataset.value === chatGenderFilter);
  });
}
// انتخابِ کاربر رو هم رویِ profiles.chat_gender_filter ذخیره می‌کنه (چون همین یه ستون هم
// رویِ خودِ من (چی می‌بینم) هم رویِ پیام‌هایِ آینده‌ی من (کدوم دسته می‌رن، از طریقِ تریگر)
// اثر می‌ذاره) و هم بلافاصله رویِ پیام‌هایِ همین صفحه اعمالش می‌کنه — نیازی به رفچِ دوباره‌ی
// پیام‌ها نیست چون sender_gender/sender_audienceِ همه‌شون از قبل رویِ DOM هست.
async function setChatGenderFilter(value){
  try{
    if(!['female','male','both'].includes(value) || !sb || !publicChatUser) return;
    if(chatGenderFilter === value){ closeChatGenderFilterMenu(); return; }
    chatGenderFilter = value; // optimistic — اگه ذخیره‌ی سرور شکست بخوره، لاگینِ بعدی خودش درستش می‌کنه
    renderChatGenderFilterBtn();
    applyChatGenderFilter();
    closeChatGenderFilterMenu();
    const { error } = await sb.from('profiles').update({ chat_gender_filter: value }).eq('id', publicChatUser.id);
    if(error) console.warn('setChatGenderFilter save failed', error);
  }catch(e){ console.warn('setChatGenderFilter failed', e); }
}
function openChatGenderFilterMenu(){
  const menu = document.getElementById('chatGenderFilterMenu');
  const backdrop = document.getElementById('chatGenderFilterBackdrop');
  if(menu) menu.classList.add('show');
  if(backdrop) backdrop.classList.add('show');
}
function closeChatGenderFilterMenu(){
  const menu = document.getElementById('chatGenderFilterMenu');
  const backdrop = document.getElementById('chatGenderFilterBackdrop');
  if(menu) menu.classList.remove('show');
  if(backdrop) backdrop.classList.remove('show');
}
(function(){
  const btn = document.getElementById('chatGenderFilterBtn');
  const backdrop = document.getElementById('chatGenderFilterBackdrop');
  const menu = document.getElementById('chatGenderFilterMenu');
  if(btn) btn.addEventListener('click', openChatGenderFilterMenu);
  if(backdrop) backdrop.addEventListener('click', closeChatGenderFilterMenu);
  if(menu) menu.addEventListener('click', e=>{
    const opt = e.target.closest('.cgf-option');
    if(opt) setChatGenderFilter(opt.dataset.value);
  });
})();

/* ---- floating action menu shown after a long-press ---- */
let cmActionMenuTargetEl = null;
function closeChatMsgMenu(){
  const menu = document.getElementById('cmActionMenu');
  const backdrop = document.getElementById('cmActionMenuBackdrop');
  if(menu) menu.classList.remove('show');
  if(backdrop) backdrop.classList.remove('show');
  cmActionMenuTargetEl = null;
}
function openChatMsgMenu(el){
  const menu = document.getElementById('cmActionMenu');
  const backdrop = document.getElementById('cmActionMenuBackdrop');
  if(!menu || !backdrop || !el) return;
  cmActionMenuTargetEl = el;
  const username = el.dataset.username || 'کاربر';
  const msgId = el.dataset.msgId;
  const isPinned = chatPinnedMsgs.some(m => m.id === String(msgId));
  const own = publicChatUser && el.dataset.userId === publicChatUser.id;
  // Editing is only offered for the sender's own plain messages — not daily-report cards,
  // which are structured/generated content rather than free text.
  const canEdit = own && el.dataset.report !== '1';
  let html = `<button type="button" data-act="copy">${ci('copy')} کپی متن پیام${(storeData.premium || isInTrial()) ? '' : ' '+ci('lock')}</button>`;
  html += `<button type="button" data-act="filter">${ci('search')} فقط پیام‌های ${escapeHtml(username)}</button>`;
  if(canEdit) html += `<button type="button" data-act="edit">${ci('edit')} ویرایش پیام</button>`;
  if(isChatAdmin){
    html += isPinned
      ? `<button type="button" data-act="unpin">${ci('pin')} برداشتن پین</button>`
      : `<button type="button" data-act="pin">${ci('pin')} پین کردن این پیام</button>`;
  }
  // Delete/report/block/suspend — moved here from the always-visible bottom row of the
  // bubble, so the bubble itself stays clean. Same permission rules as before:
  // sender can delete their own message; the app owner can delete/block/suspend anyone;
  // everyone else can report + block.
  if(own){
    html += `<button type="button" class="cm-menu-danger" data-act="delete">${ci('trash')} حذف پیام</button>`;
  } else if(isChatAdmin){
    html += `<button type="button" class="cm-menu-danger" data-act="delete">${ci('trash')} حذف پیام (مدیریت)</button>`;
    html += `<button type="button" class="cm-menu-danger" data-act="block">${ci('block')} مسدود کردن ${escapeHtml(username)}</button>`;
    // Suspend/mute still go through the separate secret-token worker flow, so they stay
    // owner-only even for chat-admins (see suspendChatUser/muteChatUser notes above).
    if(isAppOwner){
      html += `<button type="button" class="cm-menu-danger" data-act="mute">${ci('mute')} سکوت ${escapeHtml(username)}</button>`;
      html += `<button type="button" class="cm-menu-danger" data-act="suspend">${ci('hourglass')} تعلیق ${escapeHtml(username)}</button>`;
      html += `<button type="button" class="cm-menu-danger" data-act="ban">${ci('ban')} بن دائم ${escapeHtml(username)}</button>`;
    }
  } else {
    html += `<button type="button" data-act="report">${ci('flag')} گزارش پیام</button>`;
    html += `<button type="button" class="cm-menu-danger" data-act="block">${ci('block')} مسدود کردن ${escapeHtml(username)}</button>`;
  }
  menu.innerHTML = html;
  const rect = el.getBoundingClientRect();
  backdrop.classList.add('show');
  menu.classList.add('show');
  menu.style.top = '-9999px';
  menu.style.left = '10px';
  requestAnimationFrame(()=>{
    const menuRect = menu.getBoundingClientRect();
    let left = rect.left + rect.width/2 - menuRect.width/2;
    left = Math.max(10, Math.min(left, window.innerWidth - menuRect.width - 10));
    let top = rect.top - menuRect.height - 8;
    if(top < 8) top = Math.min(rect.bottom + 8, window.innerHeight - menuRect.height - 8);
    menu.style.left = left + 'px';
    menu.style.top = top + 'px';
  });
}
const cmActionMenu = document.getElementById('cmActionMenu');
if(cmActionMenu) cmActionMenu.addEventListener('click', e=>{
  const btn = e.target.closest('button[data-act]');
  if(!btn || !cmActionMenuTargetEl) { closeChatMsgMenu(); return; }
  const el = cmActionMenuTargetEl;
  const msgId = el.dataset.msgId;
  const userId = el.dataset.userId;
  const username = el.dataset.username;
  if(btn.dataset.act === 'copy'){ if(requirePremium()) copyChatMessageText(el); }
  else if(btn.dataset.act === 'edit') startEditChatMessage(el);
  else if(btn.dataset.act === 'filter') setChatUserFilter(userId, username);
  else if(btn.dataset.act === 'pin') pinChatMessage(el);
  else if(btn.dataset.act === 'unpin') unpinChatMessage(msgId);
  else if(btn.dataset.act === 'delete') deletePublicChatMessage(msgId);
  else if(btn.dataset.act === 'report') reportPublicChatMessage(msgId);
  else if(btn.dataset.act === 'block') blockChatUser(userId, username);
  else if(btn.dataset.act === 'suspend') suspendChatUser(userId, username);
  else if(btn.dataset.act === 'mute') muteChatUser(userId, username);
  else if(btn.dataset.act === 'ban') banChatUserForever(userId, username);
  closeChatMsgMenu();
});

/* ---- Copy message text: plain clipboard copy of the bubble's visible text ---- */
async function copyChatMessageText(el){
  const textEl = el && el.querySelector('.cm-text');
  const text = textEl ? textEl.innerText : '';
  if(!text){ showToast('متنی برای کپی نیست', 'error'); return; }
  try{
    await navigator.clipboard.writeText(text);
    showToast('متن پیام کپی شد');
  }catch(err){
    // Fallback for embedded webviews / older browsers without Clipboard API permission.
    try{
      const ta = document.createElement('textarea');
      ta.value = text; ta.style.position = 'fixed'; ta.style.opacity = '0';
      document.body.appendChild(ta); ta.focus(); ta.select();
      document.execCommand('copy');
      document.body.removeChild(ta);
      showToast('متن پیام کپی شد');
    }catch(err2){ showToast('کپی انجام نشد', 'error'); }
  }
}

/* ---- Edit own message: swaps the bubble's text for an inline textarea ---- */
function chatMsgEditableText(rawContent){
  // Strips the reply-marker prefix (if any) down to just the free text a person actually
  // typed, so editing only touches their words and keeps the reply context intact.
  if(typeof rawContent === 'string' && rawContent.startsWith(REPLY_MARKER)){
    const parsed = parseReplyMsg(rawContent);
    if(parsed) return { prefix: rawContent.slice(0, rawContent.length - parsed.text.length), text: parsed.text };
  }
  return { prefix: '', text: rawContent || '' };
}
function startEditChatMessage(el){
  if(!el || el.dataset.editing === '1') return;
  const textEl = el.querySelector('.cm-text');
  if(!textEl) return;
  const { prefix, text } = chatMsgEditableText(el.dataset.raw || '');
  el.dataset.editing = '1';
  el.dataset.editPrefix = prefix;
  textEl.outerHTML = `<div class="cm-edit-box">
      <textarea class="cm-edit-textarea">${escapeHtml(text)}</textarea>
      <div class="cm-edit-actions">
        <button type="button" class="cm-edit-cancel">انصراف</button>
        <button type="button" class="cm-edit-save">ذخیره</button>
      </div>
    </div>`;
  const ta = el.querySelector('.cm-edit-textarea');
  if(ta){ ta.focus(); ta.setSelectionRange(ta.value.length, ta.value.length); }
}
function cancelEditChatMessage(el){
  const editBox = el && el.querySelector('.cm-edit-box');
  if(!editBox) return;
  const { text } = chatMsgEditableText(el.dataset.raw || '');
  editBox.outerHTML = `<div class="cm-text">${escapeHtml(text)}</div>`;
  delete el.dataset.editing;
  delete el.dataset.editPrefix;
}
async function saveEditChatMessage(el){
  if(!sb || !publicChatUser || !el) return;
  const ta = el.querySelector('.cm-edit-textarea');
  if(!ta) return;
  const newText = ta.value.trim();
  if(!newText){ showToast('متن نمی‌تونه خالی باشه', 'error'); return; }
  const finalContent = (el.dataset.editPrefix || '') + newText;
  if(finalContent === el.dataset.raw){ cancelEditChatMessage(el); return; }
  const msgId = el.dataset.msgId;
  try{
    // RLS on `messages` restricts updates to the row's own user_id — the .eq below is
    // just the client-side mirror of that, same pattern as deletePublicChatMessage.
    const { error } = await sb.from('messages').update({ content: finalContent }).eq('id', msgId).eq('user_id', publicChatUser.id);
    if(error){ showToast('ویرایش ذخیره نشد', 'error'); return; }
    el.dataset.raw = finalContent;
    const editBox = el.querySelector('.cm-edit-box');
    if(editBox) editBox.outerHTML = `<div class="cm-text">${escapeHtml(newText)}</div>`;
    delete el.dataset.editing;
    delete el.dataset.editPrefix;
    showToast('پیام ویرایش شد');
  }catch(err){ showToast('ویرایش ذخیره نشد', 'error'); }
}
const cmActionMenuBackdrop = document.getElementById('cmActionMenuBackdrop');
if(cmActionMenuBackdrop){
  cmActionMenuBackdrop.addEventListener('click', closeChatMsgMenu);
  cmActionMenuBackdrop.addEventListener('touchstart', closeChatMsgMenu, {passive:true});
}

(function(){
  const LONG_PRESS_MS = 480;
  const MOVE_CANCEL = 10;
  const wrap = document.getElementById('chatMessages');
  let timer = null, startX = 0, startY = 0, pressEl = null, fired = false;

  function clearTimer(){ if(timer){ clearTimeout(timer); timer = null; } }
  function cancel(){
    clearTimer();
    pressEl = null;
  }
  function begin(x, y, rawTarget){
    if(rawTarget.closest && rawTarget.closest('.cm-action, .cm-reply-quote, .cm-edit-box, .cm-reaction-pill, .cm-reaction-bar')) return;
    const el = rawTarget.closest ? rawTarget.closest('.chat-msg') : null;
    if(!el || el.dataset.bot === '1' || !el.dataset.userId || el.dataset.editing === '1') return;
    pressEl = el; startX = x; startY = y; fired = false;
    clearTimer();
    timer = setTimeout(()=>{
      fired = true;
      el.classList.add('long-press-active');
      if(navigator.vibrate) navigator.vibrate(15);
      openChatMsgMenu(el);
      setTimeout(()=> el.classList.remove('long-press-active'), 260);
    }, LONG_PRESS_MS);
  }
  function move(x, y){
    if(!pressEl || fired) return;
    if(Math.abs(x-startX) > MOVE_CANCEL || Math.abs(y-startY) > MOVE_CANCEL) cancel();
  }
  // A tap that releases before the long-press timer fires (and didn't move enough to be
  // cancelled) is a plain tap on the bubble — that's what opens the reaction picker,
  // Telegram-style, distinct from the hold-to-open action menu above.
  function end(){
    clearTimer();
    if(pressEl && !fired) openChatReactionBar(pressEl);
    pressEl = null;
  }

  wrap.addEventListener('touchstart', e=>{
    const t = e.touches[0];
    begin(t.clientX, t.clientY, e.target);
  }, {passive:true});
  wrap.addEventListener('touchmove', e=>{
    const t = e.touches[0];
    move(t.clientX, t.clientY);
  }, {passive:true});
  wrap.addEventListener('touchend', end);
  wrap.addEventListener('touchcancel', cancel);
  // Mouse support so the gesture also works when previewing on desktop.
  let mouseDown2 = false;
  wrap.addEventListener('mousedown', e=>{ mouseDown2 = true; begin(e.clientX, e.clientY, e.target); });
  window.addEventListener('mousemove', e=>{ if(mouseDown2) move(e.clientX, e.clientY); });
  window.addEventListener('mouseup', ()=>{ if(mouseDown2){ mouseDown2 = false; end(); } });
})();

/* ---------------- Nightly "work report" window (20:00–24:00) ---------------- */
// From 8pm to midnight, the public chat switches into a dedicated task-report
// mode: only the app owner can send regular messages, everyone else can only
// send their daily task report. Outside that window it's normal chat for
// everyone and the report button is fully disabled.
// Exception (from 22:00 onward): anyone who has already sent today's report
// gets normal chat back too — reportSentDates[todayKey()] is the same flag
// sendTaskReport() sets when the report goes through.
const REPORT_MODE_START_HOUR = 20; // 8pm
const REPORT_MODE_END_HOUR = 24;   // midnight
const CHAT_REOPEN_AFTER_REPORT_HOUR = 22; // 10pm
function isReportModeActive(){
  const h = new Date().getHours();
  return h >= REPORT_MODE_START_HOUR && h < REPORT_MODE_END_HOUR;
}
function hasSentReportToday(){
  return !!(storeData.reportSentDates && storeData.reportSentDates[todayKey()]);
}
// True only during the late slice of report mode (22:00–24:00) for a user
// who already reported today — this is what lifts the chat restriction early.
function isChatReopenedForReport(){
  const h = new Date().getHours();
  return h >= CHAT_REOPEN_AFTER_REPORT_HOUR && h < REPORT_MODE_END_HOUR && hasSentReportToday();
}
function isChatLockedForMe(){
  // Owner is always exempt — same convention as the report-mode window above
  // (reportRestricted = active && !isAppOwner): the owner can still post while
  // the group is "closed", e.g. to announce why or when it'll reopen.
  return !!(chatSettings.locked && !isAppOwner);
}
function updateChatModeUI(){
  const panel = document.getElementById('chatPanelSection');
  const banner = document.getElementById('chatReportModeBanner');
  const muteBanner = document.getElementById('chatMuteBanner');
  const lockBanner = document.getElementById('chatLockBanner');
  const input = document.getElementById('chatInput');
  const sendBtn = document.getElementById('chatSendBtn');
  const attachBtn = document.getElementById('chatAttachBtn');
  const active = isReportModeActive();
  const reopenedForReport = isChatReopenedForReport();
  const muted = isCurrentlyMuted(); // sees the whole chat fine — only the composer locks
  const locked = isChatLockedForMe();
  if(panel) panel.classList.toggle('report-mode-active', active && !reopenedForReport);
  const reportRestricted = active && !isAppOwner && !reopenedForReport;
  const restricted = reportRestricted || muted || locked;
  if(input){
    input.disabled = restricted;
    input.placeholder = muted ? 'فعلاً ساکتی، نمی‌تونی پیام بفرستی...'
      : locked ? 'چت عمومی فعلاً توسط مالک بسته شده...'
      : (reportRestricted ? 'الان فقط گزارش کار قابل ارساله...' : 'پیامتو بنویس...');
  }
  if(sendBtn) sendBtn.disabled = restricted;
  if(attachBtn) attachBtn.disabled = muted || locked;
  if(banner){
    if(active && !reopenedForReport){
      banner.textContent = isAppOwner
        ? '⏰ حالت گزارش کار فعاله — فقط تو می‌تونی همچنان پیام عادی بفرستی، بقیه فقط گزارش کار می‌فرستن.'
        : '⏰ از الان تا نیمه‌شب فقط می‌تونی گزارش تسک‌های امروزتو بفرستی؛ ارسال پیام عادی موقتاً بسته‌ست.';
      banner.classList.add('show');
    } else if(active && reopenedForReport){
      banner.textContent = '✅ گزارش امروزتو فرستادی، پس می‌تونی از الان تا نیمه‌شب هم چت عادی کنی.';
      banner.classList.add('show');
    } else {
      banner.classList.remove('show');
    }
  }
  if(muteBanner){
    if(muted){
      muteBanner.textContent = muteRemainingText();
      muteBanner.classList.add('show');
    } else {
      muteBanner.classList.remove('show');
    }
  }
  if(lockBanner){
    if(locked){
      lockBanner.textContent = '🔒 چت عمومی الان توسط مالک بسته‌ست — پیام‌های قبلی رو می‌تونی بخونی، ولی فرستادن پیام/مدیا/گزارش موقتاً غیرفعاله.';
      lockBanner.classList.add('show');
    } else {
      lockBanner.classList.remove('show');
    }
  }
  const lockBtn = document.getElementById('chatLockBtn');
  if(lockBtn){
    const lbl = document.getElementById('chatLockBtnLabel');
    if(lbl) lbl.textContent = chatSettings.locked ? 'باز کردن چت' : 'بستن چت';
    lockBtn.title = chatSettings.locked ? 'باز کردن چت عمومی' : 'بستن چت عمومی';
    lockBtn.classList.toggle('chat-pill-btn-danger', chatSettings.locked);
  }
  const cooldownBtn = document.getElementById('chatCooldownBtn');
  if(cooldownBtn){
    cooldownBtn.title = chatSettings.cooldown_seconds > 0
      ? `کول‌داون فعلی: هر ${toFa(chatSettings.cooldown_seconds)} ثانیه یه پیام (برای تغییر بزن)`
      : 'تنظیم کول‌داون بین پیام‌ها';
  }
  updateReportBtnState();
  updateChatCooldownUI(); // in case a lock/mute/report-mode change just now should override a stale countdown
}
setInterval(updateChatModeUI, 30000);

/* ================= Chat lock ("close/open the group") + slow-mode cooldown =================
   Read the shared row from `chat_settings` (id=1) and keep it in sync in realtime, so every
   open client reacts instantly when the owner flips the lock or changes the cooldown — same
   pattern as chatPinnedChannel above. If chat-lock-cooldown-supabase-schema.sql hasn't been
   run on this Supabase project yet, the select/RPC calls below just fail quietly and the chat
   behaves exactly like before (no lock, no cooldown) — same graceful-fallback style used for
   the other optional chat schema pieces (admin badges, media, weekly purge) elsewhere in this
   file. ============================================================================== */
async function loadChatSettings(){
  if(!sb) return;
  try{
    const { data, error } = await sb.from('chat_settings').select('locked,cooldown_seconds').eq('id', 1).maybeSingle();
    if(!error && data){
      chatSettings.locked = !!data.locked;
      chatSettings.cooldown_seconds = Number(data.cooldown_seconds) || 0;
    }
  }catch(err){ console.error('chat settings load error', err); }
  updateChatModeUI();
  if(!chatSettingsChannel){
    chatSettingsChannel = sb.channel('public:chat_settings')
      .on('postgres_changes', {event:'UPDATE', schema:'public', table:'chat_settings'}, payload=>{
        chatSettings.locked = !!payload.new.locked;
        chatSettings.cooldown_seconds = Number(payload.new.cooldown_seconds) || 0;
        updateChatModeUI();
      }).subscribe();
  }
}
/* ---- Owner-only: flip the whole public chat open/closed ---- */
async function toggleChatLock(){
  if(!sb || !isAppOwner) return;
  const next = !chatSettings.locked;
  if(!confirm(next
    ? 'چت عمومی برای همه (به‌جز خودت) بسته بشه؟ همه می‌تونن پیام‌های قبلی رو بخونن ولی نمی‌تونن پیام/مدیا/گزارش جدید بفرستن.'
    : 'چت عمومی دوباره برای همه باز بشه؟')) return;
  try{
    const { error } = await sb.rpc('set_chat_settings', { p_locked: next, p_cooldown_seconds: chatSettings.cooldown_seconds });
    if(error){ showToast('خطا در تغییر وضعیت چت', 'error'); return; }
    chatSettings.locked = next; // optimistic — realtime UPDATE above will confirm/correct it
    updateChatModeUI();
    showToast(next ? 'چت عمومی بسته شد 🔒' : 'چت عمومی باز شد 🔓');
  }catch(err){ showToast('مشکل در اتصال به سرور', 'error'); }
}
/* ---- Owner-only: set (or clear) the slow-mode cooldown between messages, in seconds or minutes ---- */
async function promptChatCooldown(){
  if(!sb || !isAppOwner) return;
  const choice = prompt('کول‌داون بین پیام‌ها روی چی تنظیم بشه؟\n۱) بر حسب ثانیه\n۲) بر حسب دقیقه\n۳) غیرفعال کردن کول‌داون\n\nعدد ۱، ۲ یا ۳ رو وارد کن:', chatSettings.cooldown_seconds > 0 ? '1' : '3');
  if(!choice) return;
  const c = choice.trim();
  let seconds = 0;
  if(c === '3' || c === '۳'){
    seconds = 0;
  } else if(c === '1' || c === '۱' || c === '2' || c === '۲'){
    const isMinute = (c === '2' || c === '۲');
    const valStr = prompt(`چند ${isMinute ? 'دقیقه' : 'ثانیه'} بین هر دو پیام فاصله باشه؟`, '10');
    if(!valStr) return;
    const val = parseInt(valStr.trim(), 10);
    if(!val || val <= 0){ showToast('عدد معتبر وارد نکردی', 'error'); return; }
    seconds = isMinute ? val * 60 : val;
  } else {
    return;
  }
  try{
    const { error } = await sb.rpc('set_chat_settings', { p_locked: chatSettings.locked, p_cooldown_seconds: seconds });
    if(error){ showToast('خطا در تنظیم کول‌داون', 'error'); return; }
    chatSettings.cooldown_seconds = seconds; // optimistic — realtime UPDATE above will confirm/correct it
    updateChatModeUI();
    showToast(seconds > 0 ? `کول‌داون فعال شد: هر ${toFa(seconds)} ثانیه یه پیام ✅` : 'کول‌داون غیرفعال شد ✅');
  }catch(err){ showToast('مشکل در اتصال به سرور', 'error'); }
}
const chatLockBtnEl = document.getElementById('chatLockBtn');
if(chatLockBtnEl) chatLockBtnEl.addEventListener('click', toggleChatLock);
const chatCooldownBtnEl = document.getElementById('chatCooldownBtn');
if(chatCooldownBtnEl) chatCooldownBtnEl.addEventListener('click', promptChatCooldown);
/* ---- Per-device slow-mode countdown: after a successful send, locks the composer for
   cooldown_seconds and counts down in the placeholder. Ticks every second (separate from the
   30s updateChatModeUI interval) but only acts when nothing else already owns the lock, so it
   never fights the mute/group-lock/report-mode states above. ---- */
function chatCooldownSecondsLeft(){
  if(isAppOwner) return 0;
  return Math.max(0, Math.ceil((chatCooldownUntil - Date.now()) / 1000));
}
function startChatCooldownIfNeeded(){
  if(isAppOwner || !chatSettings.cooldown_seconds) return;
  chatCooldownUntil = Date.now() + chatSettings.cooldown_seconds * 1000;
  updateChatCooldownUI();
}
function updateChatCooldownUI(){
  const input = document.getElementById('chatInput');
  const sendBtn = document.getElementById('chatSendBtn');
  if(!input || !sendBtn) return;
  if(isCurrentlyMuted() || isChatLockedForMe() || (isReportModeActive() && !isAppOwner && !isChatReopenedForReport())) return; // another lock already owns the composer
  const secondsLeft = chatCooldownSecondsLeft();
  if(secondsLeft > 0){
    input.disabled = true;
    sendBtn.disabled = true;
    input.placeholder = `${toFa(secondsLeft)} ثانیه دیگه می‌تونی پیام بعدی رو بفرستی...`;
  } else if(input.disabled && input.placeholder.indexOf('ثانیه دیگه') !== -1){
    input.disabled = false;
    sendBtn.disabled = false;
    input.placeholder = 'پیامتو بنویس...';
  }
}
setInterval(updateChatCooldownUI, 1000);

/* ================= Chat-rules suspensions (public chat + مشاور شخصی) =================
   Applied by the owner (see suspendChatUser below) and enforced for real, server-side, by
   a Supabase RLS policy on the `messages` table (a suspended/banned user's INSERT is
   rejected regardless of what this client does) — see the SQL notes shipped alongside
   this file. This client-side layer is what actually LOCKS the UI for the affected user:
   it hides the public-chat composer and the مشاور شخصی feature sections and shows a
   countdown instead, on whichever stage of the ladder they're currently on:
     مرحله ۱: ۱ روز | مرحله ۲: ۳ روز | مرحله ۳: ۷ روز | مرحله ۴: ۳۰ روز | مرحله ۵: دائم
========================================================================================= */
function isCurrentlySuspended(){
  if(mySuspendedPermanently) return true;
  if(mySuspendedUntil && mySuspendedUntil.getTime() > Date.now()) return true;
  return false;
}
function suspensionRemainingText(){
  if(mySuspendedPermanently){
    return 'به‌خاطر رعایت‌نشدن مکرر قوانین چت، حساب تو به‌طور دائم از بخش عمومی و مشاور شخصی محروم شده.';
  }
  if(!mySuspendedUntil) return '';
  const ms = mySuspendedUntil.getTime() - Date.now();
  if(ms <= 0) return '';
  const totalMinutes = Math.ceil(ms/60000);
  const days = Math.floor(totalMinutes/1440);
  const hours = Math.floor((totalMinutes%1440)/60);
  const minutes = totalMinutes%60;
  const parts = [];
  if(days>0) parts.push(toFa(days)+' روز');
  if(hours>0) parts.push(toFa(hours)+' ساعت');
  if(days===0 && minutes>0) parts.push(toFa(minutes)+' دقیقه');
  const left = parts.join(' و ') || 'کمتر از یک دقیقه';
  const stageTxt = mySuspensionStage>0 ? ` (مرحله ${toFa(mySuspensionStage)} از قوانین چت)` : '';
  return `به‌خاطر رعایت‌نشدن قوانین چت، دسترسیت به بخش عمومی و مشاور شخصی موقتاً بسته شده${stageTxt}. ${left} دیگه تا باز شدن مونده.`;
}
function renderSuspensionLocks(){
  const active = !!(publicChatUser && isCurrentlySuspended());
  const msg = suspensionRemainingText();
  const chatSuspBox = document.getElementById('chatSuspendedBox');
  const chatInBox = document.getElementById('chatLoggedInBox');
  const chatText = document.getElementById('chatSuspendedText');
  const aiTab = document.getElementById('tab-ai');
  const aiSuspBox = document.getElementById('aiSuspendedBox');
  const aiText = document.getElementById('aiSuspendedText');
  if(chatText) chatText.textContent = msg;
  if(aiText) aiText.textContent = msg;
  if(chatSuspBox) chatSuspBox.style.display = active ? 'block' : 'none';
  if(chatInBox && publicChatUser) chatInBox.style.display = active ? 'none' : 'block';
  if(aiSuspBox) aiSuspBox.style.display = active ? 'block' : 'none';
  if(aiTab) aiTab.classList.toggle('ai-suspended', active);
}
// Re-checks every 30s so a suspension that just expired unlocks the UI on its own,
// without needing the person to log out/in or reload the app.
setInterval(renderSuspensionLocks, 30000);

/* ================= Chat mute (public chat + مشاور شخصی composer only) =================
   Lighter than a suspension: applied by the owner for any custom number of minutes (see
   muteChatUser below) instead of the fixed suspension ladder. The muted person keeps full
   read access — they still see every message come in — only sendPublicChatMessage /
   sendPublicChatMedia / voice notes / task reports are blocked while it's active, both by
   this client-side UI lock and, for real, by a Supabase RLS policy on `messages` INSERT
   (see the SQL notes shipped alongside this file). ========================================= */
function isCurrentlyMuted(){
  return !!(myMutedUntil && myMutedUntil.getTime() > Date.now());
}
function muteRemainingText(){
  if(!myMutedUntil) return '';
  const ms = myMutedUntil.getTime() - Date.now();
  if(ms <= 0) return '';
  const totalMinutes = Math.ceil(ms/60000);
  const hours = Math.floor(totalMinutes/60);
  const minutes = totalMinutes%60;
  const parts = [];
  if(hours>0) parts.push(toFa(hours)+' ساعت');
  if(minutes>0) parts.push(toFa(minutes)+' دقیقه');
  const left = parts.join(' و ') || 'کمتر از یک دقیقه';
  return `🔇 فعلاً ساکتت کرده‌ن — چت رو می‌بینی ولی نمی‌تونی پیام یا مدیا بفرستی. ${left} دیگه تا باز شدن مونده.`;
}

/* ---- Owner-only: designate (or remove) a chat-admin, with a custom displayed title ----
   Only mahdihd648@gmail.com can do this — enforced again server-side inside the
   set_chat_admin_by_email() RPC itself (see chat-admin-supabase-schema.sql), so this
   client-side isAppOwner check is just what shows/hides the button, not the real gate.
   A granted admin gets the same delete/pin moderation power as the owner (see isChatAdmin
   above) and a badge with the title given here instead of "مالک" — but only on messages
   they send AFTER being granted; it's stamped at insert time, not backfilled onto old ones. */
async function grantOrRevokeChatAdmin(email, makeAdmin, title){
  if(!sb || !isAppOwner) return;
  try{
    const { error } = await sb.rpc('set_chat_admin_by_email', { target_email: email, make_admin: makeAdmin, title: title || null });
    if(error){ alert('خطا: ' + translateAuthError(error.message)); return; }
    showToast(makeAdmin ? `${email} ادمین چت شد ✅ (از پیام بعدیش لقبش نشون داده می‌شه)` : `ادمین‌بودن ${email} حذف شد ✅`);
  }catch(err){ alert('مشکل در اتصال به سرور'); }
}
function openChatAdminManager(){
  if(!isAppOwner) return;
  const choice = prompt('چیکار می‌خوای بکنی؟\n۱) ادمین کردن یه کاربر (با لقب دلخواه)\n۲) حذف ادمین از یه کاربر\n\nعدد ۱ یا ۲ رو وارد کن:', '1');
  if(!choice) return;
  const c = choice.trim();
  if(c === '1' || c === '۱'){
    const email = prompt('ایمیل کاربری که می‌خوای ادمین چت کنی:');
    if(!email || !email.trim()) return;
    const title = prompt('لقبی که به‌جای «مالک» کنار پیام‌هاش نمایش داده بشه (مثلاً: مدیر، ناظر):');
    if(!title || !title.trim()){ showToast('لقب رو وارد نکردی', 'error'); return; }
    grantOrRevokeChatAdmin(email.trim(), true, title.trim());
  } else if(c === '2' || c === '۲'){
    const email = prompt('ایمیل کاربری که می‌خوای ادمین‌بودنش رو حذف کنی:');
    if(!email || !email.trim()) return;
    grantOrRevokeChatAdmin(email.trim(), false, null);
  }
}
const chatAdminManageBtn = document.getElementById('chatAdminManageBtn');
if(chatAdminManageBtn) chatAdminManageBtn.addEventListener('click', openChatAdminManager);

/* ---- Owner-only: apply the next suspension stage to a user, and lift one manually ---- */
function promptAdminToken(){ return prompt('رمز مدیریت:'); }
async function suspendChatUser(userId, username){
  if(!isAppOwner) return;
  if(publicChatUser && userId === publicChatUser.id){ showToast('نمی‌تونی خودتو تعلیق کنی', 'error'); return; }
  if(!confirm(`${username} به‌خاطر رعایت‌نشدن قوانین چت تعلیق بشه؟\nمدتش خودکار محاسبه می‌شه: هر تخلف جدید یه پله رو نردبان قوانین چت جلو می‌ره (۱ روز ← ۳ روز ← ۷ روز ← ۳۰ روز ← محرومیت دائم).`)) return;
  const token = promptAdminToken();
  if(!token) return;
  try{
    const res = await fetch(WORKER_BASE + '/admin/suspend', {
      method:'POST', headers:{'Content-Type':'application/json'},
      body: JSON.stringify({ token, user_id: userId })
    });
    const data = await res.json();
    if(data.ok){
      const durText = data.permanent
        ? 'به‌طور دائم از بخش عمومی و مشاور شخصی محروم شد'
        : `به مدت ${toFa(data.days)} روز از بخش عمومی و مشاور شخصی تعلیق شد (مرحله ${toFa(data.stage)})`;
      alert(`${username} ${durText} ✅`);
      showToast('تعلیق ثبت شد');
    } else {
      alert('خطا: ' + (data.error || 'نامشخص'));
    }
  }catch(err){ alert('مشکل در اتصال به سرور'); }
}
async function unsuspendChatUserByEmail(){
  if(!isAppOwner) return;
  const email = prompt('ایمیل کاربری که می‌خوای تعلیقش رو لغو کنی:');
  if(!email) return;
  const token = promptAdminToken();
  if(!token) return;
  try{
    const res = await fetch(WORKER_BASE + '/admin/unsuspend', {
      method:'POST', headers:{'Content-Type':'application/json'},
      body: JSON.stringify({ token, email: email.trim() })
    });
    const data = await res.json();
    if(data.ok) alert('تعلیق ' + email + ' لغو شد ✅');
    else alert('خطا: ' + (data.error || 'نامشخص'));
  }catch(err){ alert('مشکل در اتصال به سرور'); }
}

/* ---- Owner-only: mute a user for however many minutes you type in, and lift a mute early.
   Unlike suspend there's no fixed ladder/stage — every mute is a fresh custom duration, and
   the person keeps full read access to the chat the whole time (see isCurrentlyMuted above). */
async function muteChatUser(userId, username){
  if(!isAppOwner) return;
  if(publicChatUser && userId === publicChatUser.id){ showToast('نمی‌تونی خودتو ساکت کنی', 'error'); return; }
  const minutesStr = prompt(`${username} رو چند دقیقه ساکت کنیم؟\n(فقط ارسال پیام/مدیا/گزارش کار بسته می‌شه؛ خودش هنوز چت رو می‌بینه)`, '10');
  if(!minutesStr) return;
  const minutes = parseInt(minutesStr.trim(), 10);
  if(!minutes || minutes <= 0){ showToast('عدد دقیقه‌ی معتبر وارد نکردی', 'error'); return; }
  const token = promptAdminToken();
  if(!token) return;
  try{
    const res = await fetch(WORKER_BASE + '/admin/mute', {
      method:'POST', headers:{'Content-Type':'application/json'},
      body: JSON.stringify({ token, user_id: userId, minutes })
    });
    const data = await res.json();
    if(data.ok){
      alert(`${username} به مدت ${toFa(minutes)} دقیقه ساکت شد ✅`);
      showToast('سکوت ثبت شد');
    } else {
      alert('خطا: ' + (data.error || 'نامشخص'));
    }
  }catch(err){ alert('مشکل در اتصال به سرور'); }
}
async function unmuteChatUserByEmail(){
  if(!isAppOwner) return;
  const email = prompt('ایمیل کاربری که می‌خوای سکوتش رو زودتر لغو کنی:');
  if(!email) return;
  const token = promptAdminToken();
  if(!token) return;
  try{
    const res = await fetch(WORKER_BASE + '/admin/unmute', {
      method:'POST', headers:{'Content-Type':'application/json'},
      body: JSON.stringify({ token, email: email.trim() })
    });
    const data = await res.json();
    if(data.ok) alert('سکوت ' + email + ' لغو شد ✅');
    else alert('خطا: ' + (data.error || 'نامشخص'));
  }catch(err){ alert('مشکل در اتصال به سرور'); }
}

/* ---- Owner-only: ban a user forever, in one step — unlike suspendChatUser above این از
   نردبان مراحل (۱ روز ← ۳ روز ← ...) رد نمی‌شه و مستقیم suspended_permanently رو true
   می‌کنه، پس همون قفلِ isCurrentlySuspended/renderSuspensionLocks که چت + مشاور شخصی رو
   می‌بنده فوراً و برای همیشه فعال می‌شه. لیدربورد هم جدا این فلگ رو چک می‌کنه (loadLeaderboard)
   و کسی که suspended_permanently=true باشه اصلاً تو نتیجه‌ها نمیاد. برخلاف suspend/mute که از
   طریق ورکر با توکن مخفی انجام می‌شن، این دو تابع مستقیم یه RPC امن تو Supabase صدا می‌زنن
   که خودش سمت سرور چک می‌کنه ایمیلِ کاربرِ لاگین‌شده دقیقاً OWNER_EMAIL باشه — یعنی even اگه
   یکی isAppOwner رو تو کد کلاینت دستکاری کنه، باز نمی‌تونه کسی رو بن کنه. باید یه‌بار
   ban-forever-supabase-schema.sql رو تو SQL editor پروژه‌ی Supabase اجرا کنی تا این دو RPC
   (ban_chat_user_forever / unban_chat_user_forever) ساخته بشن، وگرنه با یه خطای واضح fail
   می‌کنن نه اینکه بی‌سروصدا کاری نکنن. */
async function banChatUserForever(userId, username){
  if(!isAppOwner) return;
  if(publicChatUser && userId === publicChatUser.id){ showToast('نمی‌تونی خودتو بن کنی', 'error'); return; }
  if(!confirm(`${username} برای همیشه از چت عمومی، مشاور شخصی و لیدربورد بن بشه؟\nبرخلاف تعلیق، این فوریه و نیاز به تکرار تخلف نداره — ولی هر وقت خواستی از پنل مخفی مدیریت قابل لغوه.`)) return;
  if(!sb){ showToast('اتصال برقرار نیست', 'error'); return; }
  try{
    const { error } = await sb.rpc('ban_chat_user_forever', { target_user_id: userId });
    if(error){ alert('خطا: ' + translateAuthError(error.message)); return; }
    alert(`${username} برای همیشه بن شد ✅`);
    showToast('بن دائم ثبت شد');
  }catch(err){ alert('مشکل در اتصال به سرور'); }
}
async function unbanChatUserForeverByEmail(){
  if(!isAppOwner) return;
  const email = prompt('ایمیل کاربری که می‌خوای بنِ دائمش رو لغو کنی:');
  if(!email || !email.trim()) return;
  if(!sb){ showToast('اتصال برقرار نیست', 'error'); return; }
  try{
    const { error } = await sb.rpc('unban_chat_user_forever', { target_email: email.trim() });
    if(error){ alert('خطا: ' + translateAuthError(error.message)); return; }
    alert('بنِ ' + email + ' لغو شد ✅');
  }catch(err){ alert('مشکل در اتصال به سرور'); }
}
document.getElementById('chatSuspendedLogoutBtn').addEventListener('click', async ()=>{
  if(!sb) return;
  intentionalSignOut = true;
  await sb.auth.signOut();
  showToast('خارج شدی');
});

/* ---------------- Chat media (GIF/image/video uploads) ----------------
   Files live in the 'chat-media' Storage bucket, one subfolder per user id (so RLS can
   restrict uploads to "your own folder" without a lookup). Only the *path* is stored on
   the messages row (media_path/media_type) — the public URL is rebuilt on render via
   getPublicUrl(), so nothing breaks if the project URL ever changes. Requires
   chat-media-supabase-schema.sql to have been run (adds the columns + bucket + daily
   purge cron); if it hasn't, sends fail with a clear toast instead of silently no-oping.
   Videos are capped higher than images/gifs since clips are naturally heavier — make sure
   the bucket's file_size_limit and allowed_mime_types in that same SQL migration are raised
   to match CHAT_MEDIA_MAX_BYTES_VIDEO / CHAT_MEDIA_ALLOWED_TYPES, or uploads will pass this
   client check and still get rejected by Storage. */
const CHAT_MEDIA_BUCKET = 'chat-media';
const CHAT_MEDIA_MAX_BYTES_IMAGE = 5 * 1024 * 1024;  // keep in sync with the bucket's file_size_limit in the SQL migration
const CHAT_MEDIA_MAX_BYTES_VIDEO = 25 * 1024 * 1024; // ditto — videos need more headroom than a still image/gif
const CHAT_MEDIA_ALLOWED_TYPES = ['image/gif','image/png','image/jpeg','image/webp','video/mp4','video/webm','video/quicktime'];
function isVideoFile(file){ return file.type.indexOf('video/') === 0; }
/* ---------------- Silent-video → "GIF" detection (مثل تلگرام) ----------------
   Telegram sends a video with no audio track as a looping, muted, control-less clip that
   behaves like a GIF instead of a normal video player. There's no reliable, synchronous way
   to check "does this file have an audio track" from the File object alone — it has to be
   loaded into a real <video> element first. None of the signals below (mozHasAudio,
   webkitAudioDecodedByteCount, the standard audioTracks list) are supported in every browser,
   so this checks all three and quietly falls back to treating the clip as a normal video
   (safer than silently muting something that did have sound) if none of them are available
   or loading fails. */
function detectVideoHasAudio(file){
  return new Promise((resolve)=>{
    const video = document.createElement('video');
    video.muted = true;
    video.preload = 'auto';
    video.playsInline = true;
    const objUrl = URL.createObjectURL(file);
    let settled = false;
    const finish = (hasAudio)=>{
      if(settled) return;
      settled = true;
      video.pause();
      video.removeAttribute('src');
      video.load();
      URL.revokeObjectURL(objUrl);
      resolve(hasAudio);
    };
    const checkSignals = ()=>{
      if(typeof video.mozHasAudio === 'boolean') return video.mozHasAudio;
      if(typeof video.webkitAudioDecodedByteCount === 'number') return video.webkitAudioDecodedByteCount > 0;
      if(video.audioTracks) return video.audioTracks.length > 0;
      return null; // no signal supported in this browser — caller decides the fallback
    };
    video.addEventListener('loadedmetadata', ()=>{
      // webkitAudioDecodedByteCount only populates once some audio has actually been
      // decoded, so give it a brief muted play before reading the signals.
      video.play().catch(()=>{});
      setTimeout(()=>{
        const signal = checkSignals();
        finish(signal === null ? true : signal); // unknown → assume it has audio (safer default)
      }, 250);
    }, { once:true });
    video.addEventListener('error', ()=> finish(true), { once:true }); // can't inspect it → don't guess
    video.src = objUrl;
  });
}
function chatMediaMaxBytesFor(file){ return isVideoFile(file) ? CHAT_MEDIA_MAX_BYTES_VIDEO : CHAT_MEDIA_MAX_BYTES_IMAGE; }
function chatMediaPublicUrl(path){
  if(!path || !sb) return '';
  try{ return sb.storage.from(CHAT_MEDIA_BUCKET).getPublicUrl(path).data.publicUrl; }catch(err){ return ''; }
}
const FREE_CHAT_DAILY_LIMIT = 50;
function getFreeChatMsgCountToday(){
  const rec = storeData.chatDailyCount;
  if(!rec || rec.date !== todayKeyLocal()) return 0;
  return rec.count || 0;
}
function registerFreeChatMsgSent(){
  storeData.chatDailyCount = { date: todayKeyLocal(), count: getFreeChatMsgCountToday() + 1 };
  saveData();
}
async function sendPublicChatMessage(){
  const input = document.getElementById('chatInput');
  const text = input.value.trim();
  if(!text || !publicChatUser) return;
  if(isCurrentlySuspended()){
    showToast('دسترسیت به چت عمومی موقتاً بسته‌ست', 'error');
    renderSuspensionLocks();
    return;
  }
  if(isCurrentlyMuted()){
    showToast('فعلاً ساکتت کرده‌ن — نمی‌تونی پیام بفرستی', 'error');
    updateChatModeUI();
    return;
  }
  if(isChatLockedForMe()){
    showToast('چت عمومی فعلاً توسط مالک بسته شده', 'error');
    updateChatModeUI();
    return;
  }
  if(chatCooldownSecondsLeft() > 0){
    showToast(`${toFa(chatCooldownSecondsLeft())} ثانیه دیگه می‌تونی پیام بعدی رو بفرستی`, 'error');
    updateChatCooldownUI();
    return;
  }
  if(!(storeData.premium || isInTrial()) && getFreeChatMsgCountToday() >= FREE_CHAT_DAILY_LIMIT){
    showToast(`تو نسخه‌ی رایگان روزی فقط ${toFa(FREE_CHAT_DAILY_LIMIT)} پیام می‌تونی بفرستی`, 'error');
    openPremiumOverlay();
    return;
  }
  if(isReportModeActive() && !isAppOwner && !isChatReopenedForReport()){
    showToast('الان فقط ارسال گزارش کار امکان‌پذیره 📋', 'error');
    updateChatModeUI();
    return;
  }
  if(checkCrisisText(text)){
    input.value = '';
    autoGrowChatBox(input);
    renderCrisisBanner('publicChatCrisisSlot');
    showToast('این چت عمومیه؛ به‌جاش این پیام رو برات آوردیم 🤍');
    return;
  }
  if(containsAbusiveLanguage(text)){
    showToast('لطفاً محترمانه بنویس 🙏', 'error');
    return;
  }
  const finalText = chatReplyTarget
    ? (REPLY_MARKER + chatReplyTarget.id + '|' + encodeURIComponent(chatReplyTarget.username) + '|' + encodeURIComponent(chatReplyTarget.text) + '|' + text)
    : text;
  input.value = '';
  autoGrowChatBox(input);
  clearChatReply();
  const streakVal = (typeof computeStreak === 'function') ? computeStreak() : 0;
  const isPremiumNow = !!(storeData.premium || isInTrial());

  // --- رندر فوری (optimistic): قبلاً پیام فقط وقتی روی صفحه ظاهر می‌شد که هم
  // insert روی سرور تموم بشه، هم رویداد realtime همون INSERT برگرده — یعنی دو
  // رفت‌وبرگشت شبکه پشت‌سرهم، که چند ثانیه طول می‌کشید. الان بلافاصله با یه id
  // موقت رندر می‌شه؛ insert در پس‌زمینه انجام می‌شه و بعدش فقط id واقعی جایگزین
  // می‌شه. اگه ارسال شکست بخوره، حبابش برداشته می‌شه و متن برمی‌گرده تو اینپوت.
  const tempId = 'local-' + Date.now() + '-' + Math.random().toString(36).slice(2);
  const tempMsg = { id: tempId, user_id: publicChatUser.id, username: publicChatUsername, content: finalText, streak: streakVal, premium: isPremiumNow, created_at: new Date().toISOString(), is_owner: isAppOwner };
  const wrap = document.getElementById('chatMessages');
  if(wrap.querySelector('.chat-empty-msg')) wrap.innerHTML = '';
  const grouped = lastChatMsgUserId === publicChatUser.id;
  wrap.insertAdjacentHTML('beforeend', publicChatMsgHtml(tempMsg, grouped));
  const pendingEl = wrap.querySelector(`.chat-msg[data-msg-id="${tempId}"]`);
  if(pendingEl) pendingEl.classList.add('cm-pending');
  lastChatMsgUserId = publicChatUser.id;
  applyChatUserFilter();
  scrollChatToBottom(false);

  try{
    let { data, error } = await sb.from('messages').insert({ user_id: publicChatUser.id, username: publicChatUsername, content: finalText, streak: streakVal, premium: isPremiumNow }).select().single();
    if(error && /premium/i.test(error.message || '')){
      // The "premium" column hasn't been added to the messages table yet on this
      // Supabase project — fall back so sending still works (just without the badge logic).
      ({ data, error } = await sb.from('messages').insert({ user_id: publicChatUser.id, username: publicChatUsername, content: finalText, streak: streakVal }).select().single());
    }
    if(error && /streak/i.test(error.message || '')){
      // The "streak" column hasn't been added to the messages table yet on this
      // Supabase project — fall back so sending still works (just without the badge).
      ({ data, error } = await sb.from('messages').insert({ user_id: publicChatUser.id, username: publicChatUsername, content: finalText }).select().single());
    }
    if(error){
      showToast('پیام ارسال نشد', 'error');
      if(pendingEl) pendingEl.remove();
      if(!wrap.querySelector('.chat-msg')) wrap.innerHTML = '<div class="chat-empty-msg">هنوز پیامی نیست، اولین نفر باش!</div>';
      input.value = text;
      autoGrowChatBox(input);
    } else {
      // جایگزینی id موقت با id واقعیِ سرور. وقتی رویداد realtime همین INSERT هم برسه،
      // چک دوپلیکیت تو subscribe() جلوی رندر دوباره‌شو می‌گیره (پایین‌تر همین فایل).
      if(pendingEl && data){
        pendingEl.dataset.msgId = data.id;
        pendingEl.classList.remove('cm-pending');
      }
      if(!isPremiumNow) registerFreeChatMsgSent();
      try{ logDailyFeatureUse('chat'); }catch(e){}
      startChatCooldownIfNeeded();
    }
  }catch(err){
    showToast('پیام ارسال نشد', 'error');
    if(pendingEl) pendingEl.remove();
    if(!wrap.querySelector('.chat-msg')) wrap.innerHTML = '<div class="chat-empty-msg">هنوز پیامی نیست، اولین نفر باش!</div>';
    input.value = text;
    autoGrowChatBox(input);
  }
}
document.getElementById('chatSendBtn').addEventListener('click', sendPublicChatMessage);
document.getElementById('chatInput').addEventListener('keydown', e=>{
  if(e.key==='Enter' && !e.shiftKey){ e.preventDefault(); sendPublicChatMessage(); }
});

/* ---------------- Sending a GIF/image ----------------
   Uploads to the 'chat-media' Storage bucket, then inserts a messages row that just
   points at the uploaded path (media_path/media_type) — same optimistic-render pattern
   as sendPublicChatMessage, except the "instant" preview uses a local blob: URL (since
   the real upload itself takes a beat) and gets swapped for the permanent Storage URL
   once the upload + insert both succeed. Same suspension/report-mode/daily-limit rules
   as a normal text message apply, since a media message still counts as a chat message. */
async function sendPublicChatMedia(file, thumbBlob){
  if(!file || !publicChatUser) return;
  if(isCurrentlySuspended()){
    showToast('دسترسیت به چت عمومی موقتاً بسته‌ست', 'error');
    renderSuspensionLocks();
    return;
  }
  if(isCurrentlyMuted()){
    showToast('فعلاً ساکتت کرده‌ن — نمی‌تونی مدیا بفرستی', 'error');
    updateChatModeUI();
    return;
  }
  if(isChatLockedForMe()){
    showToast('چت عمومی فعلاً توسط مالک بسته شده', 'error');
    updateChatModeUI();
    return;
  }
  if(chatCooldownSecondsLeft() > 0){
    showToast(`${toFa(chatCooldownSecondsLeft())} ثانیه دیگه می‌تونی پیام بعدی رو بفرستی`, 'error');
    updateChatCooldownUI();
    return;
  }
  if(!(storeData.premium || isInTrial()) && getFreeChatMsgCountToday() >= FREE_CHAT_DAILY_LIMIT){
    showToast(`تو نسخه‌ی رایگان روزی فقط ${toFa(FREE_CHAT_DAILY_LIMIT)} پیام می‌تونی بفرستی`, 'error');
    openPremiumOverlay();
    return;
  }
  if(isReportModeActive() && !isAppOwner && !isChatReopenedForReport()){
    showToast('الان فقط ارسال گزارش کار امکان‌پذیره 📋', 'error');
    updateChatModeUI();
    return;
  }
  if(!CHAT_MEDIA_ALLOWED_TYPES.includes(file.type)){
    showToast('فقط گیف، عکس (PNG/JPG/WebP) یا ویدیوی MP4/WebM مجازه', 'error');
    return;
  }
  const maxBytes = chatMediaMaxBytesFor(file);
  if(file.size > maxBytes){
    showToast(`حجم فایل باید کمتر از ${toFa(Math.round(maxBytes / (1024*1024)))} مگابایت باشه`, 'error');
    return;
  }

  const streakVal = (typeof computeStreak === 'function') ? computeStreak() : 0;
  const isPremiumNow = !!(storeData.premium || isInTrial());
  // Silent videos ("بدون صدا") get sent as media_type 'gifvideo' instead of 'video' — same mp4
  // file, but rendered muted/looping/without controls like a GIF (see publicChatMsgHtml).
  // Detection needs the file loaded into a real <video> element first, so this awaits it before
  // the optimistic bubble goes up — a short beat, but far shorter than the actual upload.
  const mediaType = isVideoFile(file)
    ? ((await detectVideoHasAudio(file)) ? 'video' : 'gifvideo')
    : (file.type === 'image/gif' ? 'gif' : 'image');
  const localUrl = URL.createObjectURL(file);
  // Only video messages carry a cover thumbnail (see veCaptureCoverBlob() in the video editor
  // module) — its object URL is created up front so the optimistic bubble can show it
  // immediately, same as localUrl above.
  const thumbLocalUrl = thumbBlob ? URL.createObjectURL(thumbBlob) : '';

  const tempId = 'local-' + Date.now() + '-' + Math.random().toString(36).slice(2);
  const tempMsg = { id: tempId, user_id: publicChatUser.id, username: publicChatUsername, content: '', streak: streakVal, premium: isPremiumNow, created_at: new Date().toISOString(), is_owner: isAppOwner, media_localUrl: localUrl, media_type: mediaType, media_thumb_localUrl: thumbLocalUrl };
  const wrap = document.getElementById('chatMessages');
  if(wrap.querySelector('.chat-empty-msg')) wrap.innerHTML = '';
  const grouped = lastChatMsgUserId === publicChatUser.id;
  wrap.insertAdjacentHTML('beforeend', publicChatMsgHtml(tempMsg, grouped));
  const pendingEl = wrap.querySelector(`.chat-msg[data-msg-id="${tempId}"]`);
  if(pendingEl) pendingEl.classList.add('cm-pending');
  lastChatMsgUserId = publicChatUser.id;
  applyChatUserFilter();
  scrollChatToBottom(false);

  try{
    const rawExt = (file.name && file.name.includes('.')) ? file.name.split('.').pop().replace(/[^a-z0-9]/gi,'').slice(0,8) : '';
    const ext = rawExt || (mediaType === 'gif' ? 'gif' : (mediaType === 'video' || mediaType === 'gifvideo') ? 'mp4' : 'jpg');
    const path = `${publicChatUser.id}/${Date.now()}-${Math.random().toString(36).slice(2)}.${ext}`;
    const { error: upErr } = await sb.storage.from(CHAT_MEDIA_BUCKET).upload(path, file, { contentType: file.type, upsert: false });
    if(upErr) throw upErr;

    // The cover thumbnail (video editor stage 3) uploads as its own small JPEG object next to
    // the video. A failed thumbnail upload shouldn't block sending the actual video — worst
    // case the message still goes out, just without a custom poster frame.
    let thumbPath = null;
    if(thumbBlob){
      const thumbPathCandidate = `${publicChatUser.id}/${Date.now()}-${Math.random().toString(36).slice(2)}-thumb.jpg`;
      const { error: thumbUpErr } = await sb.storage.from(CHAT_MEDIA_BUCKET).upload(thumbPathCandidate, thumbBlob, { contentType: 'image/jpeg', upsert: false });
      if(!thumbUpErr) thumbPath = thumbPathCandidate;
      else console.error('Chat media thumbnail upload error', thumbUpErr);
    }

    const insertPayload = { user_id: publicChatUser.id, username: publicChatUsername, content: '', streak: streakVal, premium: isPremiumNow, media_path: path, media_type: mediaType };
    if(thumbPath) insertPayload.media_thumb_path = thumbPath;
    let { data, error } = await sb.from('messages').insert(insertPayload).select().single();
    if(error && thumbPath && /media_thumb_path/i.test(error.message || '')){
      // Schema doesn't have the thumbnail column yet — retry once without it rather than losing
      // the whole message over a nice-to-have poster frame. (Run chat-media-supabase-schema.sql
      // with a media_thumb_path text column added to pick this up going forward.)
      delete insertPayload.media_thumb_path;
      ({ data, error } = await sb.from('messages').insert(insertPayload).select().single());
    }
    if(error && /media_path|media_type/i.test(error.message || '')){
      // The migration hasn't been run on this Supabase project yet — the file uploaded
      // fine but there's no column to record it against. Surface this clearly instead
      // of silently failing, since "upload succeeded, message never appeared" is confusing.
      throw new Error('ستون‌های media_path/media_type هنوز اجرا نشده — chat-media-supabase-schema.sql رو اجرا کن');
    }
    if(error) throw error;

    if(pendingEl && data){
      const mediaEl = pendingEl.querySelector('.cm-media img, .cm-media video');
      if(mediaEl) mediaEl.src = chatMediaPublicUrl(path);
      if(mediaEl && mediaEl.tagName === 'VIDEO' && thumbPath) mediaEl.poster = chatMediaPublicUrl(thumbPath);
      URL.revokeObjectURL(localUrl);
      if(thumbLocalUrl) URL.revokeObjectURL(thumbLocalUrl);
      pendingEl.dataset.msgId = data.id;
      pendingEl.classList.remove('cm-pending');
    }
    if(mediaType === 'gif' || mediaType === 'gifvideo'){
      addGifPickerRecent(chatMediaPublicUrl(path), chatMediaPublicUrl(path), mediaType);
    }
    if(!isPremiumNow) registerFreeChatMsgSent();
    try{ logDailyFeatureUse('chat'); }catch(e){}
    startChatCooldownIfNeeded();
  }catch(err){
    console.error('Chat media send error', err);
    // Previously this always showed the same generic "ارسال مدیا ناموفق بود" no matter
    // what actually went wrong (missing migration, Storage rejecting the mime type/size,
    // RLS, network) — surfacing err.message makes the real cause visible without needing
    // to pull console logs off the device.
    showToast(`ارسال مدیا ناموفق بود: ${translateTechError(err && err.message)}`, 'error');
    if(pendingEl) pendingEl.remove();
    URL.revokeObjectURL(localUrl);
    if(thumbLocalUrl) URL.revokeObjectURL(thumbLocalUrl);
    if(!wrap.querySelector('.chat-msg')) wrap.innerHTML = '<div class="chat-empty-msg">هنوز پیامی نیست، اولین نفر باش!</div>';
  }
}
/* ---- attach menu: tapping ➕ shows a small popup ("عکس یا ویدیو" / "گیف") instead of
   two separate always-visible buttons — keeps the send row to the same icon count as
   before adding the voice button, so nothing gets pushed outside the box on narrow screens. */
function closeChatAttachMenu(){
  const menu = document.getElementById('chatAttachMenu');
  const backdrop = document.getElementById('chatAttachMenuBackdrop');
  if(menu) menu.classList.remove('show');
  if(backdrop) backdrop.classList.remove('show');
}
function openChatAttachMenu(){
  const btn = document.getElementById('chatAttachBtn');
  const menu = document.getElementById('chatAttachMenu');
  const backdrop = document.getElementById('chatAttachMenuBackdrop');
  if(!btn || !menu || !backdrop) return;
  backdrop.classList.add('show');
  menu.classList.add('show');
  menu.style.top = '-9999px';
  menu.style.left = '10px';
  requestAnimationFrame(()=>{
    const rect = btn.getBoundingClientRect();
    const menuRect = menu.getBoundingClientRect();
    let left = rect.left + rect.width/2 - menuRect.width/2;
    left = Math.max(10, Math.min(left, window.innerWidth - menuRect.width - 10));
    let top = rect.top - menuRect.height - 8;
    if(top < 8) top = Math.min(rect.bottom + 8, window.innerHeight - menuRect.height - 8);
    menu.style.left = left + 'px';
    menu.style.top = top + 'px';
  });
}
document.getElementById('chatAttachBtn').addEventListener('click', openChatAttachMenu);
document.getElementById('chatAttachMenuBackdrop').addEventListener('click', closeChatAttachMenu);
document.getElementById('chatAttachMenu').addEventListener('click', (e)=>{
  const btn = e.target.closest('button[data-act]');
  closeChatAttachMenu();
  if(!btn) return;
  if(btn.dataset.act === 'media'){
    const inp = document.getElementById('chatMediaInput');
    if(inp) inp.click();
  } else if(btn.dataset.act === 'gif'){
    openGifPicker();
  }
});
document.getElementById('chatMediaInput').addEventListener('change', (e)=>{
  const file = e.target.files && e.target.files[0];
  e.target.value = ''; // reset so picking the exact same file again still fires 'change'
  if(!file) return;
  if(peShouldEdit(file)) peOpen(file);
  else if(veShouldEdit(file)) veOpen(file);
  else {
    // Stage 5 (edge case: مرورگرهای بدون پشتیبانی) — a real video that veShouldEdit() rejected
    // (captureStream/MediaRecorder missing) still gets sent, same as before, but now says why
    // instead of silently skipping the editor in a way that could look like the tap did nothing.
    // Animated GIFs take this same branch and stay silent — they were never going to open the
    // video editor in the first place, so there's nothing to explain.
    if(isVideoFile(file)) showToast('ویرایشگر ویدیو تو این مرورگر پشتیبانی نمی‌شه؛ ویدیو بدون تغییر ارسال شد', 'error');
    sendPublicChatMedia(file);
  }
});

/* ---------------- Pre-send photo editor (crop + adjust) ----------------
   Opens right after picking a static image (PNG/JPEG/WebP) from the attach menu above, before
   it ever reaches sendPublicChatMedia(). GIFs and videos skip this entirely, since editing an
   animated GIF frame-by-frame or a video is a much heavier problem than editing one static photo
   — they keep going straight through the old path unchanged.
   Three tools: کراپ (crop, with aspect-ratio presets + 90° rotate), تنظیمات (brightness/
   contrast/saturation), and نقاشی (freehand draw: color swatches + custom picker, brush size,
   undo, clear-all).
   Everything renders through <canvas> at a capped "working resolution" (long side ≤1440px)
   regardless of the original photo's size, both so live slider previews stay smooth on a phone
   and so the final upload isn't needlessly huge — chat images never needed camera-native
   resolution anyway. Once the user hits the checkmark, the edited result is exported to a Blob
   and handed to the existing sendPublicChatMedia() — every rule that already applies there
   (mute/lock/report-mode/daily-limit/size-limit) still applies unchanged, since as far as that
   function's concerned it's just a normal image file. */
const PE_MAX_WORK_DIM = 1440;
const PE_ASPECTS = { 'free':null, '1:1':[1,1], '4:5':[4,5], '3:4':[3,4], '16:9':[16,9] };
const PE_MIN_CROP_PX = 44; // smallest allowed crop box, in displayed CSS px
let peState = null;
let peDrag = null; // active pointer-drag info while resizing/moving the crop rect
const PE_DRAW_COLORS_DEFAULT = '#ffffff';
const PE_DRAW_HISTORY_MAX = 15;
let peDrawStroke = null; // {ctx, points, pointerId} while a finger/mouse is actively drawing a stroke
let peDrawHistory = []; // undo stack of ImageData snapshots, canvas-pixel space
let peSending = false; // true while peConfirmSend()'s export/upload is in flight

function peShouldEdit(file){
  // Only static, non-animated raster images go through the editor — an animated image/gif
  // would lose its animation the moment it touches a single <canvas> frame, and video needs a
  // completely different (frame-sequence) pipeline, so both are explicitly excluded here.
  return !!(file && (file.type === 'image/png' || file.type === 'image/jpeg' || file.type === 'image/webp'));
}
function peClamp(v, lo, hi){ return Math.max(lo, Math.min(hi, v)); }
function peFilterString(){
  return `brightness(${peState.brightness}%) contrast(${peState.contrast}%) saturate(${peState.saturate}%)`;
}
function peLoadImage(file){
  return new Promise((resolve, reject)=>{
    const img = new Image();
    img.onload = ()=>resolve(img);
    img.onerror = reject;
    img.src = URL.createObjectURL(file);
  });
}

async function peOpen(file){
  let img;
  try{ img = await peLoadImage(file); }
  catch(e){ sendPublicChatMedia(file); return; } // couldn't decode as an image — just send it as before

  // Pre-scale once onto an offscreen canvas at the capped working resolution, so every later
  // redraw (rotate, slider drag) works off a small canvas instead of a multi-megapixel photo.
  const scale = Math.min(1, PE_MAX_WORK_DIM / Math.max(img.naturalWidth, img.naturalHeight));
  const workW = Math.max(1, Math.round(img.naturalWidth * scale));
  const workH = Math.max(1, Math.round(img.naturalHeight * scale));
  const workCanvas = document.createElement('canvas');
  workCanvas.width = workW; workCanvas.height = workH;
  workCanvas.getContext('2d').drawImage(img, 0, 0, workW, workH);
  URL.revokeObjectURL(img.src);

  peState = {
    file, originalType: file.type,
    workCanvas, workW, workH,
    rotation: 0,
    brightness: 100, contrast: 100, saturate: 100,
    aspect: 'free',
    crop: {x:0, y:0, w:1, h:1},
    activeTab: 'crop',
    drawColor: PE_DRAW_COLORS_DEFAULT,
    brushSize: 8,
  };

  document.getElementById('peBrightness').value = 100;
  document.getElementById('peContrast').value = 100;
  document.getElementById('peSaturate').value = 100;
  document.querySelectorAll('.pe-aspect-btn').forEach(b=>b.classList.toggle('active', b.dataset.aspect==='free'));
  document.getElementById('peBrushSize').value = 8;
  document.getElementById('peDrawColorPicker').value = PE_DRAW_COLORS_DEFAULT;
  document.querySelectorAll('.pe-draw-swatch').forEach(b=>b.classList.toggle('active', b.dataset.color===PE_DRAW_COLORS_DEFAULT));
  peUpdateBrushPreview();
  peSwitchTab('crop');

  document.getElementById('photoEditorOverlay').classList.add('show');
  peRenderBase();
  // peRenderBase() already resized peDrawCanvas to match this image via peSyncDrawCanvas(), but
  // resizing alone only clears it when the pixel dimensions happen to differ from whatever was
  // left over from a previous editing session — force a clean slate every time regardless.
  peResetDrawLayer();
}
function peClose(){
  document.getElementById('photoEditorOverlay').classList.remove('show');
  peState = null;
  peDrag = null;
  peDrawStroke = null;
  if(peRenderBaseRAF){ cancelAnimationFrame(peRenderBaseRAF); peRenderBaseRAF = null; }
}
function peCancel(){
  // Guards against the Android hardware back button, which calls peCancel() directly — bypassing
  // the disabled ✕ button below — and would otherwise let a tap/back-press during an in-flight
  // send null out peState and hide the overlay while peConfirmSend() is still exporting, only for
  // the photo to get sent a moment later anyway once that promise resolves.
  if(peSending) return;
  if(!peState){ peClose(); return; }
  const c = peState.crop;
  const edited = peState.rotation !== 0 || peState.brightness !== 100 || peState.contrast !== 100 ||
    peState.saturate !== 100 || c.x !== 0 || c.y !== 0 || c.w !== 1 || c.h !== 1 || peDrawCanvasHasContent();
  if(edited && !confirm('تغییراتی که دادی ذخیره نمی‌شه. مطمئنی می‌خوای بی‌خیالش شی؟')) return;
  peClose();
}
function peSwitchTab(tab){
  if(!peState) return;
  peState.activeTab = tab;
  document.querySelectorAll('.pe-tab').forEach(b=>b.classList.toggle('active', b.dataset.tab===tab));
  document.getElementById('peCropPanel').style.display = tab==='crop' ? 'flex' : 'none';
  document.getElementById('peAdjustPanel').style.display = tab==='adjust' ? 'flex' : 'none';
  document.getElementById('peDrawPanel').style.display = tab==='draw' ? 'flex' : 'none';
  document.getElementById('peCropLayer').style.visibility = tab==='crop' ? 'visible' : 'hidden';
  // The draw canvas sits on top of the image in every tab (so marks stay visible while cropping
  // or adjusting), but only takes pointer input on its own tab — otherwise it'd swallow the crop
  // handle drags happening right underneath it.
  document.getElementById('peDrawCanvas').style.pointerEvents = tab==='draw' ? 'auto' : 'none';
}

/* ---- render the base (rotated + filtered) canvas, then refit + reposition the crop UI ---- */
function peRenderBase(){
  const canvas = document.getElementById('peBaseCanvas');
  const ctx = canvas.getContext('2d');
  const rot = peState.rotation;
  const swapped = (rot === 90 || rot === 270);
  const outW = swapped ? peState.workH : peState.workW;
  const outH = swapped ? peState.workW : peState.workH;
  canvas.width = outW; canvas.height = outH;
  ctx.save();
  ctx.filter = peFilterString();
  ctx.translate(outW/2, outH/2);
  ctx.rotate(rot * Math.PI/180);
  ctx.drawImage(peState.workCanvas, -peState.workW/2, -peState.workH/2, peState.workW, peState.workH);
  ctx.restore();
  peFitCanvasToStage();
  peRenderCropRect();
  peSyncDrawCanvas(outW, outH);
}
let peRenderBaseRAF = null;
/* Coalesces bursts of peRenderBase() calls into at most one per animation frame. Each full render
   redraws the whole (up to 1440px) canvas with a CSS filter applied — cheap once, but a slider
   drag or a rapid resize (e.g. mid orientation-change animation) can fire many 'input'/'resize'
   events between two frames, and re-running the full redraw for every one of them is wasted work
   a slower phone would visibly lag on. The final value is always still applied — this only drops
   the redundant intermediate frames, never the last one. */
function peRenderBaseThrottled(){
  if(peRenderBaseRAF) return;
  peRenderBaseRAF = requestAnimationFrame(()=>{
    peRenderBaseRAF = null;
    if(peState) peRenderBase();
  });
}
function peFitCanvasToStage(){
  const canvas = document.getElementById('peBaseCanvas');
  const stage = document.getElementById('peStage');
  const padding = 16;
  const availW = Math.max(1, stage.clientWidth - padding*2);
  const availH = Math.max(1, stage.clientHeight - padding*2);
  const ratio = Math.min(availW / canvas.width, availH / canvas.height, 1);
  canvas.style.width = Math.round(canvas.width * ratio) + 'px';
  canvas.style.height = Math.round(canvas.height * ratio) + 'px';
}

/* ---- draw layer: a transparent canvas kept pixel-for-pixel the same size as peBaseCanvas, so
   strokes live in the same coordinate space as the final rotated/filtered image and peExportBlob()
   can just stamp it straight on top before cropping. Resizing (dc.width=/dc.height=) implicitly
   clears a canvas's content, which is exactly what should happen when the underlying image
   dimensions change (new photo, or a rotate) — but NOT on every brightness/contrast/saturate
   tweak, which also calls peRenderBase() while the dimensions stay identical. Hence the size
   check below instead of resizing unconditionally. ---- */
function peSyncDrawCanvas(outW, outH){
  const dc = document.getElementById('peDrawCanvas');
  if(dc.width !== outW || dc.height !== outH){
    dc.width = outW; dc.height = outH;
    peDrawHistory = [];
    peUpdateDrawUndoBtn();
  }
  peFitDrawCanvasToStage();
}
function peFitDrawCanvasToStage(){
  const canvas = document.getElementById('peBaseCanvas');
  const dc = document.getElementById('peDrawCanvas');
  const stage = document.getElementById('peStage');
  const cRect = canvas.getBoundingClientRect(), sRect = stage.getBoundingClientRect();
  dc.style.left = (cRect.left - sRect.left) + 'px';
  dc.style.top = (cRect.top - sRect.top) + 'px';
  dc.style.width = cRect.width + 'px';
  dc.style.height = cRect.height + 'px';
}
function peResetDrawLayer(){
  const dc = document.getElementById('peDrawCanvas');
  dc.getContext('2d').clearRect(0, 0, dc.width, dc.height);
  peDrawHistory = [];
  peUpdateDrawUndoBtn();
}
/* Authoritative "is there anything drawn" check — reads the canvas itself rather than trailing a
   separate boolean flag, so it stays correct through undo/redo edge cases a flag would miss: e.g.
   draw one dot then immediately undo it (flag would still say "edited"), or draw past the
   PE_DRAW_HISTORY_MAX undo-stack cap (flag could go the other way and undercount real content
   still baked onto the canvas). Only called from peCancel(), so the pixel scan cost is paid at
   most once per editing session, not on every stroke. */
function peDrawCanvasHasContent(){
  const dc = document.getElementById('peDrawCanvas');
  if(!dc.width || !dc.height) return false;
  try{
    const data = dc.getContext('2d').getImageData(0, 0, dc.width, dc.height).data;
    for(let i = 3; i < data.length; i += 4){
      if(data[i] !== 0) return true; // any non-transparent alpha byte means a mark is there
    }
  }catch(e){ /* tainted/zero-size canvas — treat as no content rather than block closing */ }
  return false;
}
function peUpdateDrawUndoBtn(){
  const btn = document.getElementById('peDrawUndoBtn');
  if(btn) btn.disabled = peDrawHistory.length === 0;
}
function pePushDrawHistory(){
  const dc = document.getElementById('peDrawCanvas');
  try{
    const snap = dc.getContext('2d').getImageData(0, 0, dc.width, dc.height);
    peDrawHistory.push(snap);
    if(peDrawHistory.length > PE_DRAW_HISTORY_MAX) peDrawHistory.shift();
    peUpdateDrawUndoBtn();
  }catch(e){ /* getImageData can throw on a zero-size canvas mid-transition — safe to skip */ }
}
function peDrawUndo(){
  if(!peDrawHistory.length) return;
  const dc = document.getElementById('peDrawCanvas');
  const snap = peDrawHistory.pop();
  dc.getContext('2d').putImageData(snap, 0, 0);
  peUpdateDrawUndoBtn();
}
function peDrawClear(){
  pePushDrawHistory();
  const dc = document.getElementById('peDrawCanvas');
  dc.getContext('2d').clearRect(0, 0, dc.width, dc.height);
}
function peCanvasPoint(e, canvas){
  const rect = canvas.getBoundingClientRect();
  const scaleX = canvas.width / rect.width, scaleY = canvas.height / rect.height;
  return { x: (e.clientX - rect.left) * scaleX, y: (e.clientY - rect.top) * scaleY };
}
function peDrawPointerDown(e){
  if(!peState || peState.activeTab !== 'draw') return;
  if(peDrawStroke) return; // a stroke from another finger is already in progress — ignore a second touch point
  e.preventDefault();
  const canvas = document.getElementById('peDrawCanvas');
  canvas.setPointerCapture(e.pointerId);
  pePushDrawHistory();
  const ctx = canvas.getContext('2d');
  const p = peCanvasPoint(e, canvas);
  ctx.lineJoin = 'round'; ctx.lineCap = 'round';
  ctx.strokeStyle = peState.drawColor;
  ctx.fillStyle = peState.drawColor;
  ctx.lineWidth = peState.brushSize;
  // A bare tap (no drag at all) wouldn't leave any mark since a stroked path needs at least two
  // points — fill an immediate dot at the brush's own size so a single tap still shows something.
  ctx.beginPath();
  ctx.arc(p.x, p.y, peState.brushSize/2, 0, Math.PI*2);
  ctx.fill();
  peDrawStroke = { ctx, points: [p], pointerId: e.pointerId };
}
function peDrawPointerMove(e){
  if(!peDrawStroke || e.pointerId !== peDrawStroke.pointerId) return; // ignore any other pointer
  e.preventDefault();
  const canvas = document.getElementById('peDrawCanvas');
  const p = peCanvasPoint(e, canvas);
  const pts = peDrawStroke.points;
  pts.push(p);
  const ctx = peDrawStroke.ctx;
  // Curve each new segment through the midpoint of the last two points instead of stroking
  // straight corner-to-corner lines — this is what makes a fast freehand line look like a single
  // smooth stroke instead of a faceted zig-zag, especially noticeable at larger brush sizes.
  const n = pts.length;
  if(n < 3){
    ctx.beginPath();
    ctx.moveTo(pts[0].x, pts[0].y);
    ctx.lineTo(p.x, p.y);
    ctx.stroke();
    return;
  }
  const p0 = pts[n-3], p1 = pts[n-2], p2 = pts[n-1];
  const mid1 = {x:(p0.x+p1.x)/2, y:(p0.y+p1.y)/2};
  const mid2 = {x:(p1.x+p2.x)/2, y:(p1.y+p2.y)/2};
  ctx.beginPath();
  ctx.moveTo(mid1.x, mid1.y);
  ctx.quadraticCurveTo(p1.x, p1.y, mid2.x, mid2.y);
  ctx.stroke();
}
function peDrawPointerUp(e){ if(peDrawStroke && e.pointerId === peDrawStroke.pointerId) peDrawStroke = null; }
function peUpdateBrushPreview(){
  const el = document.getElementById('peBrushPreview');
  if(!el || !peState) return;
  const px = peClamp(peState.brushSize, 6, 34); // keep the swatch legible at both slider extremes
  el.style.width = px + 'px';
  el.style.height = px + 'px';
  el.style.background = peState.drawColor;
}

/* ---- crop rect: stored as fractions (0..1) of the CURRENT base canvas, so rotate/refit don't
   need any unit conversion beyond re-rendering the DOM box at the new pixel size. ---- */
function peRenderCropRect(){
  const canvas = document.getElementById('peBaseCanvas');
  const layer = document.getElementById('peCropLayer');
  const rectEl = document.getElementById('peCropRect');
  const stage = document.getElementById('peStage');
  const cRect = canvas.getBoundingClientRect(), sRect = stage.getBoundingClientRect();
  const cw = cRect.width, ch = cRect.height;
  layer.style.left = (cRect.left - sRect.left) + 'px';
  layer.style.top = (cRect.top - sRect.top) + 'px';
  layer.style.width = cw + 'px';
  layer.style.height = ch + 'px';
  const c = peState.crop;
  rectEl.style.left = (c.x*cw) + 'px';
  rectEl.style.top = (c.y*ch) + 'px';
  rectEl.style.width = (c.w*cw) + 'px';
  rectEl.style.height = (c.h*ch) + 'px';
}
function peApplyAspect(key){
  if(!peState) return;
  peState.aspect = key;
  document.querySelectorAll('.pe-aspect-btn').forEach(b=>b.classList.toggle('active', b.dataset.aspect===key));
  const ratioPair = PE_ASPECTS[key];
  if(!ratioPair){ peRenderCropRect(); return; } // 'free' — leave the current crop selection as-is
  const canvas = document.getElementById('peBaseCanvas');
  const outW = canvas.width, outH = canvas.height;
  const targetRatio = ratioPair[0]/ratioPair[1];
  let w, h;
  if(outW/outH > targetRatio){ h = outH; w = h*targetRatio; } else { w = outW; h = w/targetRatio; }
  const x = (outW - w)/2, y = (outH - h)/2;
  peState.crop = {x:x/outW, y:y/outH, w:w/outW, h:h/outH};
  peRenderCropRect();
}
function peRotate(){
  if(!peState) return;
  peState.rotation = (peState.rotation + 90) % 360;
  // Rotating swaps width/height, which makes the old crop selection meaningless — restart
  // from a full-frame, unlocked-aspect selection rather than trying to remap it.
  peState.crop = {x:0, y:0, w:1, h:1};
  peState.aspect = 'free';
  document.querySelectorAll('.pe-aspect-btn').forEach(b=>b.classList.toggle('active', b.dataset.aspect==='free'));
  // Same reasoning applies to any drawn marks: they're pixel-anchored to the pre-rotation frame,
  // so leaving them in place would float them at the wrong spot/orientation on the rotated image.
  // peSyncDrawCanvas() (called from peRenderBase() below) only clears the canvas when its pixel
  // size actually changes, which a square image wouldn't trigger — so clear explicitly here too.
  peResetDrawLayer();
  peRenderBase();
}

/* ---- crop rect drag/resize (Pointer Events — same code path for touch and mouse) ---- */
function peCropPointerDown(e){
  if(!peState || peDrag) return; // no session, or a drag from another finger is already active
  const handle = e.target.closest('.pe-crop-handle');
  const rectEl = document.getElementById('peCropRect');
  if(!handle && e.target !== rectEl) return;
  e.preventDefault();
  const canvas = document.getElementById('peBaseCanvas');
  const cRect = canvas.getBoundingClientRect();
  peDrag = {
    pointerId: e.pointerId,
    mode: handle ? handle.dataset.h : 'move',
    startX: e.clientX, startY: e.clientY,
    startCrop: {...peState.crop}, cw: cRect.width, ch: cRect.height,
    aspectLocked: !!PE_ASPECTS[peState.aspect],
    ratio: PE_ASPECTS[peState.aspect] ? PE_ASPECTS[peState.aspect][0]/PE_ASPECTS[peState.aspect][1] : null,
  };
  (handle || rectEl).setPointerCapture(e.pointerId);
}
function peCropPointerMove(e){
  if(!peDrag || e.pointerId !== peDrag.pointerId) return; // ignore any other pointer (e.g. a palm touch)
  e.preventDefault();
  const dx = (e.clientX - peDrag.startX) / peDrag.cw;
  const dy = (e.clientY - peDrag.startY) / peDrag.ch;
  let {x,y,w,h} = peDrag.startCrop;
  const minW = PE_MIN_CROP_PX / peDrag.cw, minH = PE_MIN_CROP_PX / peDrag.ch;

  if(peDrag.mode === 'move'){
    x = peClamp(x + dx, 0, 1 - w);
    y = peClamp(y + dy, 0, 1 - h);
  } else {
    // Resize from one corner; the opposite corner stays anchored in place.
    let left = x, top = y, right = x+w, bottom = y+h;
    if(peDrag.mode.includes('l')) left = peClamp(x + dx, 0, right - minW);
    if(peDrag.mode.includes('r')) right = peClamp(x + w + dx, left + minW, 1);
    if(peDrag.mode.includes('t')) top = peClamp(y + dy, 0, bottom - minH);
    if(peDrag.mode.includes('b')) bottom = peClamp(y + h + dy, top + minH, 1);
    if(peDrag.aspectLocked){
      const wPx = (right-left)*peDrag.cw, hFrac = (wPx/peDrag.ratio)/peDrag.ch;
      if(peDrag.mode.includes('t')) top = peClamp(bottom - hFrac, 0, bottom - minH);
      else bottom = peClamp(top + hFrac, top + minH, 1);
    }
    x = left; y = top; w = right-left; h = bottom-top;
  }
  peState.crop = {x,y,w,h};
  peRenderCropRect();
}
function peCropPointerUp(e){ if(peDrag && e.pointerId === peDrag.pointerId) peDrag = null; }

/* ---- export: bake rotation + crop + adjustments into one final canvas → Blob ---- */
function peExportBlob(){
  return new Promise((resolve)=>{
    const base = document.getElementById('peBaseCanvas');
    const draw = document.getElementById('peDrawCanvas');
    // Flatten the rotated/filtered base image and the drawn marks onto one canvas first — they're
    // already the same pixel size (see peSyncDrawCanvas) — then crop out of that merged result.
    const merged = document.createElement('canvas');
    merged.width = base.width; merged.height = base.height;
    const mctx = merged.getContext('2d');
    mctx.drawImage(base, 0, 0);
    if(draw.width === base.width && draw.height === base.height){
      mctx.drawImage(draw, 0, 0);
    }
    const c = peState.crop;
    const sx = Math.round(c.x * merged.width), sy = Math.round(c.y * merged.height);
    const sw = Math.max(1, Math.round(c.w * merged.width)), sh = Math.max(1, Math.round(c.h * merged.height));
    const out = document.createElement('canvas');
    out.width = sw; out.height = sh;
    out.getContext('2d').drawImage(merged, sx, sy, sw, sh, 0, 0, sw, sh);
    const wantsPng = peState.originalType === 'image/png';
    out.toBlob(blob=>resolve(blob), wantsPng ? 'image/png' : 'image/jpeg', wantsPng ? undefined : 0.9);
  });
}
async function peConfirmSend(){
  const btn = document.getElementById('peSendBtn');
  const cancelBtn = document.getElementById('peCancelBtn');
  const tabsEl = document.getElementById('peTabs');
  const originalFile = peState.file;
  // toBlob() below is genuinely async (noticeably so for a big PNG on a slow phone) — without
  // locking these, a tap on ✕ mid-export would call peCancel()/peClose(), null out peState and
  // hide the overlay, yet this function would still finish and send the photo a moment later as
  // if nothing had been canceled. Lock the whole header until the export either lands or fails.
  if(btn) btn.disabled = true;
  if(cancelBtn) cancelBtn.disabled = true;
  if(tabsEl) tabsEl.style.pointerEvents = 'none';
  peSending = true;
  try{
    const blob = await peExportBlob();
    if(!blob) throw new Error('توش کردن عکس ادیت‌شده به فایل ناموفق بود');
    const ext = peState.originalType === 'image/png' ? 'png' : 'jpg';
    const outFile = new File([blob], `edited-${Date.now()}.${ext}`, { type: blob.type });
    peClose();
    sendPublicChatMedia(outFile);
  }catch(err){
    console.error('Photo editor export error', err);
    showToast('ادیت عکس ناموفق بود، عکس اصلی ارسال می‌شه', 'error');
    peClose();
    sendPublicChatMedia(originalFile);
  }finally{
    if(btn) btn.disabled = false;
    if(cancelBtn) cancelBtn.disabled = false;
    if(tabsEl) tabsEl.style.pointerEvents = '';
    peSending = false;
  }
}

document.getElementById('peCancelBtn').addEventListener('click', peCancel);
document.getElementById('peSendBtn').addEventListener('click', peConfirmSend);
document.getElementById('peTabs').addEventListener('click', (e)=>{
  const btn = e.target.closest('.pe-tab'); if(!btn) return;
  peSwitchTab(btn.dataset.tab);
});
document.getElementById('peAspectRow').addEventListener('click', (e)=>{
  const btn = e.target.closest('.pe-aspect-btn'); if(!btn) return;
  peApplyAspect(btn.dataset.aspect);
});
document.getElementById('peRotateBtn').addEventListener('click', peRotate);
['peBrightness','peContrast','peSaturate'].forEach(id=>{
  document.getElementById(id).addEventListener('input', (e)=>{
    if(!peState) return; // guards a stray event firing after the editor's already been closed
    const key = id === 'peBrightness' ? 'brightness' : id === 'peContrast' ? 'contrast' : 'saturate';
    peState[key] = Number(e.target.value);
    peRenderBaseThrottled();
  });
});
document.getElementById('peCropLayer').addEventListener('pointerdown', peCropPointerDown);
window.addEventListener('pointermove', peCropPointerMove);
window.addEventListener('pointerup', peCropPointerUp);
window.addEventListener('resize', ()=>{ if(peState) peRenderBaseThrottled(); });

document.getElementById('peDrawCanvas').addEventListener('pointerdown', peDrawPointerDown);
window.addEventListener('pointermove', peDrawPointerMove);
window.addEventListener('pointerup', peDrawPointerUp);
document.getElementById('peDrawColors').addEventListener('click', (e)=>{
  if(!peState) return;
  const sw = e.target.closest('.pe-draw-swatch'); if(!sw) return;
  peState.drawColor = sw.dataset.color;
  document.querySelectorAll('.pe-draw-swatch').forEach(b=>b.classList.toggle('active', b===sw));
  document.getElementById('peDrawColorPicker').value = sw.dataset.color;
  peUpdateBrushPreview();
});
document.getElementById('peDrawColorPicker').addEventListener('input', (e)=>{
  // The native OS color-picker dialog this opens can outlive the overlay (e.g. user backs out
  // of the editor while it's still open) — peState may already be null by the time it fires.
  if(!peState) return;
  peState.drawColor = e.target.value;
  document.querySelectorAll('.pe-draw-swatch').forEach(b=>b.classList.remove('active'));
  peUpdateBrushPreview();
});
document.getElementById('peBrushSize').addEventListener('input', (e)=>{
  if(!peState) return;
  peState.brushSize = Number(e.target.value);
  peUpdateBrushPreview();
});
document.getElementById('peDrawUndoBtn').addEventListener('click', peDrawUndo);
document.getElementById('peDrawClearBtn').addEventListener('click', peDrawClear);

/* ---------------- Pre-send video trim editor ----------------
   Opens right after picking a real video (not an animated GIF — those keep going straight
   through, same as before) from the attach menu, before it reaches sendPublicChatMedia().

   Planned in six stages, same shape as the photo editor above:
     ۱) برش — trim in/out points on a scrubber, with a sound-on preview of just that range
        (implemented)
     ۲) تنظیمات — brightness/contrast/saturation + mute-audio, baked in at export time
        (implemented — see veFilterString()/veState.muteAudio, and the canvas-based re-record in
        veExportTrimmedBlob() below, which is what actually bakes filters/mute into the exported
        file; a plain video.captureStream() can't apply a CSS filter to its own frames)
     ۳) کاور — pick a frame from inside the trimmed range as the thumbnail/poster
        (implemented — see veCaptureCoverBlob(); the chosen frame is uploaded as a small JPEG
        alongside the video and stored as media_thumb_path, independent of whether the video
        itself needed re-encoding, since grabbing one frame is cheap either way)
     ۴) پولیش/تجربه‌ی کاربری — a real progress indicator for the export wait, nicer scrubber
        (frame filmstrip), can't-dismiss-mid-export guard
     ۵) اج‌کیس‌ها و بهینه‌سازی — very short/long clips, unsupported browsers, memory
     ۶) تست نهایی و یکپارچگی

   THIS STAGE covers ۲ and ۳.

   The one thing worth understanding up front, because it shapes everything below: unlike the
   photo editor's crop (a cheap, instant <canvas> redraw), there's no way to losslessly cut a
   video file in the browser — MP4/WebM containers need real re-encoding to produce a valid
   trimmed file, and the only encoder available without pulling in a heavy library (ffmpeg.wasm,
   tens of MB) is the browser's own MediaRecorder. So exporting here means: play the selected
   range in real time through a hidden <video>, capture its stream, and re-record it — which
   takes wall-clock time roughly equal to the trimmed clip's own length, and comes out the other
   side as WebM regardless of the original's container (already one of CHAT_MEDIA_ALLOWED_TYPES,
   so sendPublicChatMedia() doesn't need to know or care). If nothing was actually trimmed, the
   original file is sent as-is instead — no reason to pay that re-encode cost (and the resulting
   quality/bitrate change) for a no-op edit. */
const VE_MIN_TRIM_SEC = 1; // smallest selectable range, in seconds
// Stage 5 (edge cases / optimization): the real-time re-record in veExportTrimmedBlob() has to
// hold every encoded chunk in memory for as long as the export takes, so an unbounded selection
// on a long source clip (a multi-minute screen recording, say) risks a slow, memory-heavy export
// with no visible cap. VE_MAX_TRIM_SEC bounds the *selected range*, not the source video itself —
// a long clip can still be opened and scrubbed through, just not exported past this length.
const VE_MAX_TRIM_SEC = 90;
// Longest edge (px) the export canvas / cover-frame canvas are allowed to render at — downscales
// large-resolution source video (e.g. a 4K phone recording) so the per-frame canvas draw and the
// MediaRecorder chunk buffer above stay bounded regardless of what the source actually is.
const VE_EXPORT_MAX_DIM = 1280;
// Stage 5: filter presets. Each is just a CSS `filter` fragment that gets prepended to the
// existing brightness/contrast/saturate sliders in veFilterString() below — since the sliders
// default to the 100% identity value, a preset alone (no slider changes) already reproduces
// exactly what its `css` string says, and a user nudging a slider afterward stacks on top of it
// rather than replacing it. This is also why no separate baking step was needed anywhere else:
// every place that already calls veFilterString() (preview, export, cover capture) picks up
// presets for free.
const VE_FILTER_PRESETS = [
  { id:'normal',  name:'عادی',       css:'' },
  { id:'vivid',   name:'واضح',       css:'saturate(160%) contrast(112%)' },
  { id:'warm',    name:'گرم',        css:'sepia(25%) saturate(140%) hue-rotate(-8deg) brightness(105%)' },
  { id:'cool',    name:'سرد',        css:'saturate(120%) hue-rotate(15deg) brightness(102%)' },
  { id:'bw',      name:'سیاه‌وسفید', css:'grayscale(100%) contrast(108%)' },
  { id:'vintage', name:'وینتیج',     css:'sepia(38%) contrast(90%) brightness(103%) saturate(85%)' },
  { id:'drama',   name:'درام',       css:'contrast(128%) saturate(115%) brightness(95%)' },
  { id:'fade',    name:'محو',        css:'contrast(85%) brightness(108%) saturate(78%)' },
];
let veState = null; // { file, duration, trimStart, trimEnd, playing, brightness, contrast, saturate, muteAudio, coverTime }
let veDrag = null; // active pointer-drag info while moving a trim handle
let veCoverDrag = null; // active pointer-drag info while moving the cover-frame handle
let veSending = false;
let veFilmstripToken = null; // bumped on every veOpen()/veClose() so an in-flight filmstrip build (see veBuildFilmstrip) can tell it's been superseded and stop appending frames

function veShouldEdit(file){
  if(!file || !isVideoFile(file)) return false;
  // captureStream()/MediaRecorder are what the export below is built on (see the comment above) —
  // both are Chromium APIs. Fine for this app's Android WebView target, but if either is missing
  // there's no point opening an editor whose only button can't actually do anything — skip
  // straight to sending the file untouched, same fallback the photo editor uses for a decode failure.
  const hasCaptureStream = !!(HTMLVideoElement.prototype.captureStream || HTMLVideoElement.prototype.mozCaptureStream);
  return hasCaptureStream && typeof MediaRecorder !== 'undefined';
}
function veFilterString(){
  const preset = VE_FILTER_PRESETS.find(p=> p.id === (veState.filterPreset || 'normal'));
  const presetCss = preset && preset.css ? preset.css + ' ' : '';
  return `${presetCss}brightness(${veState.brightness}%) contrast(${veState.contrast}%) saturate(${veState.saturate}%)`;
}
function veFmtTime(s){
  s = Math.max(0, Math.round(s));
  const m = Math.floor(s/60), sec = s%60;
  return `${toFaNum2(m)}:${toFaNum2(sec)}`;
}
function veUpdateTimeLabel(){
  const el = document.getElementById('veTimeLabel');
  if(!el || !veState) return;
  const dur = Math.max(0, veState.trimEnd - veState.trimStart);
  el.textContent = `${veFmtTime(veState.trimStart)} – ${veFmtTime(veState.trimEnd)} · ${toFa(Math.round(dur))} ثانیه`;
}
function veRenderScrub(){
  if(!veState) return;
  const d = veState.duration;
  const sPct = peClamp(veState.trimStart / d, 0, 1) * 100;
  const ePct = peClamp(veState.trimEnd / d, 0, 1) * 100;
  document.getElementById('veScrubSelected').style.left = sPct + '%';
  document.getElementById('veScrubSelected').style.width = (ePct - sPct) + '%';
  document.getElementById('veHandleStart').style.left = sPct + '%';
  document.getElementById('veHandleEnd').style.left = ePct + '%';
  const cPct = peClamp(document.getElementById('veVideo').currentTime / d, 0, 1) * 100;
  document.getElementById('veScrubPlayhead').style.left = cPct + '%';
}
/* ---- cover (stage 3) scrub: a dimmed range showing where the trim already narrowed things down
   to, plus one draggable handle for the exact frame to use as the poster. Both are positioned as
   a fraction of the *full* duration (same coordinate space veRenderScrub uses), not the trimmed
   range, so this track and the trim track above always line up visually. ---- */
function veRenderCoverTrack(){
  if(!veState) return;
  const d = veState.duration;
  const sPct = peClamp(veState.trimStart / d, 0, 1) * 100;
  const ePct = peClamp(veState.trimEnd / d, 0, 1) * 100;
  document.getElementById('veCoverRange').style.left = sPct + '%';
  document.getElementById('veCoverRange').style.width = (ePct - sPct) + '%';
  const cPct = peClamp(veState.coverTime / d, 0, 1) * 100;
  document.getElementById('veCoverHandle').style.left = cPct + '%';
  document.getElementById('veCoverTimeLabel').textContent = `کاور: ${veFmtTime(veState.coverTime)}`;
}
/* ---- stage 4 polish: a filmstrip of real frames behind both scrub tracks (trim and cover), so
   dragging a handle has actual video content to aim at instead of a flat colored bar — useful
   for trimming to a specific visual moment, and doubly useful on the cover tab where the whole
   point is picking a good-looking frame. Runs on its own throwaway <video>, independent of the
   on-screen preview, so it can seek around freely without disturbing whatever the user's doing
   with #veVideo. Best-effort only: nothing else in the editor depends on this succeeding, so any
   failure just leaves the plain track from before this stage. ---- */
function veSeekTo(video, t){
  return new Promise(resolve=>{
    if(Math.abs(video.currentTime - t) < 0.05){ resolve(); return; } // see the identical
      // 'seeked'-may-never-fire note elsewhere in this module — same reasoning applies here.
    video.addEventListener('seeked', function onSeeked(){
      video.removeEventListener('seeked', onSeeked);
      resolve();
    }, {once:true});
    video.currentTime = t;
  });
}
async function veBuildFilmstrip(file, duration){
  const trimTrack = document.getElementById('veFilmstrip');
  const coverTrack = document.getElementById('veCoverFilmstrip');
  if(trimTrack) trimTrack.innerHTML = '';
  if(coverTrack) coverTrack.innerHTML = '';
  if(!trimTrack && !coverTrack) return;

  const FRAME_COUNT = 8;
  const myToken = veFilmstripToken = {};
  const video = document.createElement('video');
  video.muted = true;
  video.playsInline = true;
  video.style.cssText = 'position:fixed;left:-9999px;width:1px;height:1px;';
  const cleanup = ()=>{ try{ URL.revokeObjectURL(video.src); }catch(e){} video.remove(); };

  video.addEventListener('error', cleanup, {once:true});
  video.addEventListener('loadedmetadata', async ()=>{
    let canvas, ctx;
    try{
      canvas = document.createElement('canvas');
      const targetH = 120;
      canvas.height = targetH;
      canvas.width = Math.max(1, Math.round((video.videoWidth / video.videoHeight) * targetH)) || targetH;
      ctx = canvas.getContext('2d');
    }catch(e){ cleanup(); return; }

    for(let i=0; i<FRAME_COUNT; i++){
      if(myToken !== veFilmstripToken){ cleanup(); return; } // superseded by a newer open/close — bail quietly
      const t = (duration * (i + 0.5)) / FRAME_COUNT;
      try{ await veSeekTo(video, t); }catch(e){ cleanup(); return; }
      if(myToken !== veFilmstripToken){ cleanup(); return; }
      let dataUrl;
      try{
        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
        dataUrl = canvas.toDataURL('image/jpeg', 0.55);
      }catch(e){ cleanup(); return; } // e.g. a tainted-canvas edge case — just stop, plain track stands
      if(trimTrack){ const img = document.createElement('img'); img.src = dataUrl; img.alt = ''; trimTrack.appendChild(img); }
      if(coverTrack){ const img2 = document.createElement('img'); img2.src = dataUrl; img2.alt = ''; coverTrack.appendChild(img2); }
      // Stage 5 (افکت): the filter-preset row needs one representative frame to preview each
      // preset against — reusing the filmstrip's own first frame instead of decoding a separate
      // one avoids a second seek/draw pass just for this. Guarded on veState still being this
      // same open session, same as the token check above.
      if(i === 0 && veState) { veState.filterThumbUrl = dataUrl; veRenderFilterRow(); }
    }
    cleanup();
  }, {once:true});

  video.src = URL.createObjectURL(file);
  document.body.appendChild(video);
}
/* ---- stage 5 (افکت): renders the filter-preset row from VE_FILTER_PRESETS. Each thumbnail is
   the same base frame (veState.filterThumbUrl) with a different inline `filter` style — the
   browser renders each preset's preview for free, no per-preset bitmap baking needed. Rebuilt
   wholesale on every call (open, or a fresh frame arriving) rather than patched in place, since
   the row is small (8 items) and this keeps active-state bookkeeping in one place. ---- */
function veRenderFilterRow(){
  const row = document.getElementById('veFilterRow');
  if(!row || !veState) return;
  const baseUrl = veState.filterThumbUrl || '';
  row.innerHTML = '';
  VE_FILTER_PRESETS.forEach(p=>{
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 've-filter-item' + (veState.filterPreset === p.id ? ' active' : '');
    btn.dataset.filter = p.id;
    const img = document.createElement('img');
    img.className = 've-filter-thumb';
    img.alt = '';
    img.src = baseUrl;
    img.style.filter = p.css || '';
    const label = document.createElement('span');
    label.className = 've-filter-name';
    label.textContent = p.name;
    btn.appendChild(img);
    btn.appendChild(label);
    row.appendChild(btn);
  });
}
function veSetPlaying(playing){
  if(!veState) return;
  const video = document.getElementById('veVideo');
  veState.playing = playing;
  if(playing){
    // The preview plays with sound (unless the user has chosen to mute the export) so trimming
    // to a specific beat/word is possible.
    video.muted = !!veState.muteAudio;
    if(video.currentTime < veState.trimStart || video.currentTime >= veState.trimEnd){
      video.currentTime = veState.trimStart;
    }
    video.play().catch(()=>{ veSetPlaying(false); });
  } else {
    video.pause();
    video.muted = true; // back to silent while the user is just dragging handles around
  }
  document.getElementById('vePlayIcon').style.display = playing ? 'none' : '';
  document.getElementById('vePauseIcon').style.display = playing ? '' : 'none';
}
function veTogglePlay(){ if(veState) veSetPlaying(!veState.playing); }

async function veOpen(file){
  const overlay = document.getElementById('videoEditorOverlay');
  const video = document.getElementById('veVideo');
  video.pause();
  video.muted = true;
  // Listeners must be attached before .src is assigned, not after — assigning .src can start
  // loading (and fire 'loadedmetadata'/'error') before a later addEventListener call would even
  // be registered, which would leave this awaiting an event that already happened and never came.
  let ok = true;
  const loadPromise = new Promise((resolve, reject)=>{
    video.addEventListener('loadedmetadata', resolve, {once:true});
    video.addEventListener('error', reject, {once:true});
  });
  video.src = URL.createObjectURL(file);
  overlay.classList.add('show');

  try{ await loadPromise; }catch(e){ ok = false; }

  // A handful of files report duration as 0/NaN/Infinity until more of them has actually been
  // buffered — without a real number there's no range to build a trim UI against.
  if(ok && !(video.duration > 0 && isFinite(video.duration))) ok = false;

  if(!ok){
    overlay.classList.remove('show');
    URL.revokeObjectURL(video.src);
    video.removeAttribute('src'); video.load();
    sendPublicChatMedia(file); // couldn't read it as a video — just send it as before
    return;
  }

  // Stage 5 (edge case: کلیپ‌های خیلی طولانی) — a source longer than VE_MAX_TRIM_SEC no longer
  // defaults to a full-length selection; the trim handles still open at the far edges, just
  // clamped to the cap, so the user sees a real (exportable) range from the start instead of one
  // they'd immediately have to shrink.
  const initTrimEnd = peClamp(video.duration, 0, VE_MAX_TRIM_SEC);
  veState = {
    file, duration: video.duration, trimStart: 0, trimEnd: initTrimEnd, playing: false,
    brightness: 100, contrast: 100, saturate: 100, muteAudio: false, filterPreset: 'normal',
    // Default cover frame is the midpoint of the (initially full) selected range rather than 0 —
    // a lot of clips open on a black or half-formed first frame, so the midpoint is a better
    // starting thumbnail than "whatever the video happens to start on".
    coverTime: peClamp(initTrimEnd / 2, 0, initTrimEnd),
  };
  video.currentTime = 0;
  document.getElementById('vePlayIcon').style.display = '';
  document.getElementById('vePauseIcon').style.display = 'none';
  // Reset the adjust tab's controls to defaults — these elements are static and reused across
  // editor sessions, so a previous open() could otherwise leave stale slider/toggle state
  // showing before any 'input'/'click' event fires to correct it.
  document.getElementById('veBrightness').value = 100;
  document.getElementById('veContrast').value = 100;
  document.getElementById('veSaturate').value = 100;
  document.getElementById('veMuteBtn').classList.remove('active');
  document.getElementById('veMuteBtn').setAttribute('aria-pressed', 'false');
  // Clear any filter-preset thumbnails left over from a previous editor session — they'd
  // otherwise keep showing (against the wrong video) until this session's own first frame
  // arrives via veBuildFilmstrip() below.
  const filterRowEl = document.getElementById('veFilterRow');
  if(filterRowEl) filterRowEl.innerHTML = '';
  video.style.filter = veFilterString();
  veSwitchTab('trim');
  veUpdateTimeLabel();
  veRenderScrub();
  veRenderCoverTrack();
  veBuildFilmstrip(file, video.duration);
}
function veClose(){
  const overlay = document.getElementById('videoEditorOverlay');
  const video = document.getElementById('veVideo');
  overlay.classList.remove('show');
  video.pause();
  video.style.filter = '';
  if(video.src){ URL.revokeObjectURL(video.src); video.removeAttribute('src'); video.load(); }
  veState = null;
  veDrag = null;
  veCoverDrag = null;
  veFilmstripToken = null; // tells any in-flight veBuildFilmstrip() run to stop appending frames
}
function veCancel(){
  // Same back-button race guard as the photo editor's peCancel() — see peConfirmSend's comment
  // for why this can't just be a disabled-button check (the Android back button calls this
  // directly, bypassing whatever's disabled in the DOM).
  if(veSending) return;
  if(!veState){ veClose(); return; }
  const edited = veState.trimStart > 0.05 || veState.trimEnd < veState.duration - 0.05 ||
    veState.brightness !== 100 || veState.contrast !== 100 || veState.saturate !== 100 || veState.muteAudio ||
    veState.filterPreset !== 'normal';
  if(edited && !confirm('برشی که دادی ذخیره نمی‌شه. مطمئنی می‌خوای بی‌خیالش شی؟')) return;
  veClose();
}

/* ---- trim handle drag (Pointer Events, same pointerId-filtering pattern as the photo editor's
   crop drag — ignores a second touch point so an incidental palm-touch mid-drag can't hijack it) ---- */
function veHandlePointerDown(e){
  if(!veState || veDrag) return;
  const handle = e.target.closest('.ve-scrub-handle');
  if(!handle) return;
  e.preventDefault();
  veSetPlaying(false); // pause any preview playback while the range itself is being adjusted
  const track = document.getElementById('veScrubTrack');
  const tRect = track.getBoundingClientRect();
  veDrag = { pointerId: e.pointerId, mode: handle.dataset.h, trackLeft: tRect.left, trackWidth: tRect.width };
  handle.setPointerCapture(e.pointerId);
}
function veHandlePointerMove(e){
  if(!veDrag || e.pointerId !== veDrag.pointerId) return;
  e.preventDefault();
  const frac = peClamp((e.clientX - veDrag.trackLeft) / veDrag.trackWidth, 0, 1);
  const t = frac * veState.duration;
  const minGap = Math.min(VE_MIN_TRIM_SEC, veState.duration);
  // Stage 5 (edge case: کلیپ‌های خیلی طولانی) — same lower bound as before (room for
  // VE_MIN_TRIM_SEC), plus an upper bound so neither handle can widen the selected range past
  // VE_MAX_TRIM_SEC. A toast fires once per drag the first time a movement gets clamped by this,
  // so it reads as an intentional limit rather than the handle just silently sticking.
  let hitMax = false;
  if(veDrag.mode === 'start'){
    const lowBound = Math.max(0, veState.trimEnd - VE_MAX_TRIM_SEC);
    if(t < lowBound) hitMax = true;
    veState.trimStart = peClamp(t, lowBound, veState.trimEnd - minGap);
  } else {
    const highBound = Math.min(veState.duration, veState.trimStart + VE_MAX_TRIM_SEC);
    if(t > highBound) hitMax = true;
    veState.trimEnd = peClamp(t, veState.trimStart + minGap, highBound);
  }
  if(hitMax && !veDrag.maxToastShown && veState.duration > VE_MAX_TRIM_SEC){
    veDrag.maxToastShown = true;
    showToast(`بازه‌ی انتخابی حداکثر می‌تونه ${toFa(VE_MAX_TRIM_SEC)} ثانیه باشه`, 'error');
  }
  // Seek the (silent) preview to whichever edge is being dragged, so the user can see exactly
  // which frame they're cutting to instead of just watching an abstract bar move.
  document.getElementById('veVideo').currentTime = veDrag.mode === 'start' ? veState.trimStart : veState.trimEnd;
  // The cover frame has to stay inside the trimmed range — narrowing the trim past a previously
  // chosen cover time would otherwise leave the cover pointing at a moment that got cut away.
  veState.coverTime = peClamp(veState.coverTime, veState.trimStart, veState.trimEnd);
  veRenderScrub();
  veRenderCoverTrack();
  veUpdateTimeLabel();
}
function veHandlePointerUp(e){ if(veDrag && e.pointerId === veDrag.pointerId) veDrag = null; }

/* ---- cover-frame handle drag: same Pointer Events pattern as the trim handles above, but a
   single handle constrained to [trimStart, trimEnd] instead of two handles constrained to each
   other. ---- */
function veCoverPointerDown(e){
  if(!veState || veCoverDrag) return;
  const handle = e.target.closest('.ve-scrub-handle') || (e.target.closest('#veCoverTrack') ? document.getElementById('veCoverHandle') : null);
  if(!handle) return;
  e.preventDefault();
  veSetPlaying(false); // pause any preview playback while the cover frame is being picked
  const track = document.getElementById('veCoverTrack');
  const tRect = track.getBoundingClientRect();
  veCoverDrag = { pointerId: e.pointerId, trackLeft: tRect.left, trackWidth: tRect.width };
  handle.setPointerCapture(e.pointerId);
  veCoverPointerMove(e); // jump straight to the tapped/clicked position, not just future drags
}
function veCoverPointerMove(e){
  if(!veCoverDrag || e.pointerId !== veCoverDrag.pointerId) return;
  e.preventDefault();
  const frac = peClamp((e.clientX - veCoverDrag.trackLeft) / veCoverDrag.trackWidth, 0, 1);
  const t = frac * veState.duration;
  veState.coverTime = peClamp(t, veState.trimStart, veState.trimEnd);
  document.getElementById('veVideo').currentTime = veState.coverTime;
  veRenderCoverTrack();
}
function veCoverPointerUp(e){ if(veCoverDrag && e.pointerId === veCoverDrag.pointerId) veCoverDrag = null; }

/* ---- export: play [trimStart, trimEnd] through a fresh, independent <video> element (not the
   on-screen preview — the user could still be mid-drag on it right up until the tap that calls
   this), capture its stream, and re-record it with MediaRecorder. See the module comment above
   for why a real-time re-record is the only lossless-container-free option available here. ---- */
/* Stage 2 addition: baking brightness/contrast/saturation into the output means the recorded
   stream can't just be video.captureStream() directly — that captures the element's raw decoded
   frames, with no way to apply a CSS-style filter to them. Instead each frame is drawn onto a
   hidden <canvas> with ctx.filter set to the same string the on-screen preview uses, and it's
   *that* canvas's captureStream() that gets recorded. Audio is handled separately: the canvas
   only carries a video track, so if the export shouldn't be muted, the original video's own
   audio track (from its own captureStream()) is added onto the canvas stream before recording;
   if it should be muted, that track is simply never added — no silent audio track riding along,
   just none at all. */
function veExportTrimmedBlob(onProgress){
  // Snapshot the settings up front rather than reading veState mid-export — the export can take
  // real wall-clock time, and while veConfirmSend now locks the whole editor UI during export
  // (stage 4), reading local copies here is cheap and one less thing to reason about if that
  // lock is ever loosened later.
  const filterCss = veFilterString();
  const muteAudio = veState.muteAudio;
  const trimStart = veState.trimStart;
  const trimEnd = veState.trimEnd;
  return new Promise((resolve, reject)=>{
    const video = document.createElement('video');
    video.muted = false;
    video.playsInline = true;
    video.style.cssText = 'position:fixed;left:-9999px;width:1px;height:1px;';

    let settled = false;
    let safetyTimer = null;
    let drawRAF = null;
    const finish = (result, err)=>{
      if(settled) return;
      settled = true;
      if(safetyTimer) clearTimeout(safetyTimer);
      if(drawRAF) cancelAnimationFrame(drawRAF);
      video.pause();
      URL.revokeObjectURL(video.src);
      video.remove();
      if(err) reject(err); else resolve(result);
    };
    // A safety net for any failure mode that doesn't cleanly reach an 'error'/'onerror' callback
    // (e.g. a codec quirk that just stalls playback) — without this, such a case would leave the
    // send button disabled forever with no feedback at all instead of falling back to the
    // original file. Generous headroom: normal completion always resolves well before this fires.
    safetyTimer = setTimeout(()=> finish(null, new Error('برش ویدیو خیلی طول کشید')),
      Math.max(15000, (trimEnd - trimStart) * 3000 + 10000));

    // Listeners go on before .src is assigned — see the identical note in veOpen() above; setting
    // .src first risks the browser firing 'loadedmetadata'/'error' before these are even attached.
    video.addEventListener('error', ()=> finish(null, new Error('بارگذاری ویدیو برای برش ناموفق بود')), {once:true});
    video.addEventListener('loadedmetadata', ()=>{
      const target = trimStart;
      if(Math.abs(video.currentTime - target) < 0.05){
        // Already sitting at (or effectively at) the trim-start — a freshly loaded video already
        // starts at 0, and some browsers won't fire 'seeked' for a currentTime assignment that
        // doesn't actually move the playhead. Waiting for that event in this case would hang
        // forever, so skip straight to capturing instead of setting currentTime again.
        beginCapture();
      } else {
        video.addEventListener('seeked', function onSeeked(){
          video.removeEventListener('seeked', onSeeked);
          beginCapture();
        }, {once:true});
        video.currentTime = target;
      }
    }, {once:true});

    video.src = URL.createObjectURL(veState.file);
    document.body.appendChild(video);

    function beginCapture(){
      const canvas = document.createElement('canvas');
      // Stage 5 (edge case / optimization): downscale a large-resolution source (e.g. a 4K phone
      // recording) instead of recording at native size — see VE_EXPORT_MAX_DIM's own comment for
      // why that matters for a real-time, memory-buffered re-record like this one.
      const vw = video.videoWidth || 1, vh = video.videoHeight || 1;
      const longEdge = Math.max(vw, vh);
      const exportScale = longEdge > VE_EXPORT_MAX_DIM ? VE_EXPORT_MAX_DIM / longEdge : 1;
      canvas.width = Math.max(1, Math.round(vw * exportScale));
      canvas.height = Math.max(1, Math.round(vh * exportScale));
      const ctx = canvas.getContext('2d');
      ctx.filter = filterCss;

      let canvasStream;
      try{ canvasStream = canvas.captureStream(30); }
      catch(err){ finish(null, err); return; }

      if(!muteAudio){
        let srcStream = null;
        try{ srcStream = video.captureStream ? video.captureStream() : video.mozCaptureStream(); }
        catch(err){ /* no captureStream on this element — export goes out silent either way */ }
        if(srcStream){
          srcStream.getAudioTracks().forEach(t=> canvasStream.addTrack(t));
          // The video track from this stream is never used (the canvas above is what's actually
          // being recorded) — stop it so it isn't left decoding in the background for nothing.
          srcStream.getVideoTracks().forEach(t=> t.stop());
        }
      }

      const mimeCandidates = ['video/webm;codecs=vp9,opus', 'video/webm;codecs=vp8,opus', 'video/webm'];
      const mimeType = mimeCandidates.find(m => MediaRecorder.isTypeSupported && MediaRecorder.isTypeSupported(m)) || '';
      let recorder;
      try{ recorder = mimeType ? new MediaRecorder(canvasStream, {mimeType}) : new MediaRecorder(canvasStream); }
      catch(err){ finish(null, err); return; }

      const chunks = [];
      recorder.ondataavailable = (e)=>{ if(e.data && e.data.size) chunks.push(e.data); };
      recorder.onerror = (e)=> finish(null, e.error || new Error('ضبط ویدیوی برش‌خورده ناموفق بود'));
      recorder.onstop = ()=>{
        if(!chunks.length){ finish(null, new Error('هیچ فریمی ضبط نشد')); return; }
        finish(new Blob(chunks, { type: recorder.mimeType || 'video/webm' }));
      };

      const stopAtEnd = ()=>{
        // Stage 4: report how far through the trimmed range playback has gotten, so the export
        // overlay's progress bar tracks something real instead of just spinning indefinitely.
        if(onProgress) onProgress(peClamp((video.currentTime - trimStart) / (trimEnd - trimStart), 0, 1));
        if(video.currentTime >= trimEnd - 0.03 || video.ended){
          video.removeEventListener('timeupdate', stopAtEnd);
          video.removeEventListener('ended', stopAtEnd);
          video.pause();
          if(recorder.state !== 'inactive') recorder.stop();
        }
      };
      video.addEventListener('timeupdate', stopAtEnd);
      video.addEventListener('ended', stopAtEnd);

      // Redraws the current video frame onto the filtered canvas every animation frame for as
      // long as recording is in flight — this loop, not the video element itself, is what the
      // recorder actually sees, which is what makes the filter (and the trim window, since the
      // canvas just shows whatever frame the video is currently on) actually land in the output.
      const drawFrame = ()=>{
        if(settled) return;
        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
        drawRAF = requestAnimationFrame(drawFrame);
      };

      if(onProgress) onProgress(0);
      recorder.start();
      drawFrame();
      video.play().catch(err=>{
        video.removeEventListener('timeupdate', stopAtEnd);
        video.removeEventListener('ended', stopAtEnd);
        finish(null, err);
      });
    }
  });
}
/* ---- cover (stage 3): grab a single frame at veState.coverTime as a JPEG, with the same
   brightness/contrast/saturation baked in so the poster actually matches the video it's a poster
   for. Uses its own throwaway <video> + <canvas>, independent of both the on-screen preview and
   veExportTrimmedBlob()'s own throwaway video — either of those could be mid-seek or mid-record
   when this runs, since veConfirmSend() below calls this before the (much longer) export. ---- */
function veCaptureCoverBlob(){
  const filterCss = veFilterString();
  const coverTime = veState.coverTime;
  return new Promise((resolve, reject)=>{
    const video = document.createElement('video');
    video.muted = true;
    video.playsInline = true;
    video.style.cssText = 'position:fixed;left:-9999px;width:1px;height:1px;';

    let settled = false;
    let safetyTimer = null;
    const finish = (result, err)=>{
      if(settled) return;
      settled = true;
      if(safetyTimer) clearTimeout(safetyTimer);
      URL.revokeObjectURL(video.src);
      video.remove();
      if(err) reject(err); else resolve(result);
    };
    safetyTimer = setTimeout(()=> finish(null, new Error('ساخت کاور خیلی طول کشید')), 10000);

    // Same before-.src listener ordering as veOpen()/veExportTrimmedBlob() above.
    video.addEventListener('error', ()=> finish(null, new Error('بارگذاری ویدیو برای ساخت کاور ناموفق بود')), {once:true});
    video.addEventListener('loadedmetadata', ()=>{
      if(Math.abs(video.currentTime - coverTime) < 0.05){
        grabFrame(); // already sitting at (or effectively at) the target — see the identical
                      // 'seeked' note elsewhere in this module for why waiting here could hang.
      } else {
        video.addEventListener('seeked', function onSeeked(){
          video.removeEventListener('seeked', onSeeked);
          grabFrame();
        }, {once:true});
        video.currentTime = coverTime;
      }
    }, {once:true});

    video.src = URL.createObjectURL(veState.file);
    document.body.appendChild(video);

    function grabFrame(){
      const canvas = document.createElement('canvas');
      // Stage 5: same downscale as the export canvas above — a poster/cover thumbnail never
      // needs native 4K resolution, so this keeps it consistent with the exported video's size.
      const vw = video.videoWidth || 1, vh = video.videoHeight || 1;
      const longEdge = Math.max(vw, vh);
      const coverScale = longEdge > VE_EXPORT_MAX_DIM ? VE_EXPORT_MAX_DIM / longEdge : 1;
      canvas.width = Math.max(1, Math.round(vw * coverScale));
      canvas.height = Math.max(1, Math.round(vh * coverScale));
      const ctx = canvas.getContext('2d');
      ctx.filter = filterCss;
      ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
      canvas.toBlob(blob=>{
        if(!blob){ finish(null, new Error('ساخت کاور ناموفق بود')); return; }
        finish(blob);
      }, 'image/jpeg', 0.85);
    }
  });
}
/* ---- stage 4 polish: export progress overlay. Shown only for the needsReencode path below —
   the no-op (original-file-goes-through-unchanged) path is near-instant and doesn't need it, and
   flashing a spinner for a fraction of a second would be more distracting than reassuring. ---- */
function veSetExportOverlay(shown, label){
  const overlay = document.getElementById('veExportOverlay');
  if(!overlay) return;
  overlay.style.display = shown ? 'flex' : 'none';
  if(shown){
    if(label != null) document.getElementById('veExportLabel').textContent = label;
    const fill = document.getElementById('veExportBarFill');
    if(fill) fill.style.width = '0%';
  }
}
function veSetExportProgress(frac){
  const pct = Math.round(peClamp(frac, 0, 1) * 100);
  const fill = document.getElementById('veExportBarFill');
  const label = document.getElementById('veExportLabel');
  if(fill) fill.style.width = pct + '%';
  if(label) label.textContent = `${toFa(pct)}٪`;
}
async function veConfirmSend(){
  const btn = document.getElementById('veSendBtn');
  const cancelBtn = document.getElementById('veCancelBtn');
  const tabsEl = document.getElementById('veTabs');
  // Stage 4: everything the user could still poke mid-export gets locked too, not just the
  // header buttons — dragging a trim/cover handle or hitting play while veExportTrimmedBlob()
  // is running would otherwise be a real race on veState.trimStart/trimEnd, not just a
  // cosmetic annoyance.
  const lockEls = [tabsEl, document.getElementById('veStage'), document.getElementById('veTrimPanel'),
    document.getElementById('veAdjustPanel'), document.getElementById('veEffectsPanel'), document.getElementById('veCoverPanel')];
  const originalFile = veState.file;
  const trimmed = veState.trimStart > 0.05 || veState.trimEnd < veState.duration - 0.05;
  const filtersChanged = veState.brightness !== 100 || veState.contrast !== 100 || veState.saturate !== 100 ||
    veState.filterPreset !== 'normal';
  // Muting always needs a re-encode even with nothing else touched — stripping an audio track
  // isn't something that can happen to a file in place, unlike trim/filters/mute which all
  // already require the re-record pass below.
  const needsReencode = trimmed || filtersChanged || veState.muteAudio;

  // Lock the whole editor before doing anything async below — same reasoning as the photo
  // editor's peConfirmSend(): without this, a tap on ✕ mid-export/mid-cover-capture would call
  // veCancel()/veClose(), null out veState, and hide the overlay, yet this function would still
  // finish and send a moment later as if nothing had been canceled.
  if(btn) btn.disabled = true;
  if(cancelBtn) cancelBtn.disabled = true;
  lockEls.forEach(el=>{ if(el) el.style.pointerEvents = 'none'; });
  veSending = true;
  if(needsReencode) veSetExportOverlay(true, 'در حال آماده‌سازی…');
  try{
    // The cover frame is cheap (one seek, one canvas draw) regardless of whether the video
    // itself needs a full re-encode, so it's always attempted here — but it's a nice-to-have
    // poster image, not something worth failing the whole send over.
    let thumbBlob = null;
    try{ thumbBlob = await veCaptureCoverBlob(); }
    catch(err){ console.error('Video cover capture error', err); }

    if(!needsReencode){
      // Nothing that actually changes the video itself was touched — skip the re-encode
      // entirely rather than paying its time and quality/bitrate cost for a no-op edit; the
      // original file goes through unchanged (only the cover, if any, rides along with it).
      veClose();
      sendPublicChatMedia(originalFile, thumbBlob);
      return;
    }
    const blob = await veExportTrimmedBlob(veSetExportProgress);
    if(!blob) throw new Error('برش ویدیو ناموفق بود');
    const outFile = new File([blob], `trimmed-${Date.now()}.webm`, { type: blob.type });
    veClose();
    sendPublicChatMedia(outFile, thumbBlob);
  }catch(err){
    console.error('Video trim export error', err);
    showToast('برش ویدیو ناموفق بود، ویدیوی اصلی ارسال می‌شه', 'error');
    veClose();
    sendPublicChatMedia(originalFile);
  }finally{
    if(btn) btn.disabled = false;
    if(cancelBtn) cancelBtn.disabled = false;
    lockEls.forEach(el=>{ if(el) el.style.pointerEvents = ''; });
    veSetExportOverlay(false);
    veSending = false;
  }
}


/* ---- tab switching (stage 2/3 added a second and third tab alongside the original برش tab) —
   same shape as peSwitchTab() above: toggle the .pe-tab.active state and show/hide the matching
   panel. ---- */
function veSwitchTab(tab){
  if(!veState) return;
  document.querySelectorAll('#veTabs .pe-tab').forEach(b=>b.classList.toggle('active', b.dataset.tab===tab));
  document.getElementById('veTrimPanel').style.display = tab==='trim' ? 'flex' : 'none';
  document.getElementById('veAdjustPanel').style.display = tab==='adjust' ? 'flex' : 'none';
  document.getElementById('veEffectsPanel').style.display = tab==='effects' ? 'flex' : 'none';
  document.getElementById('veCoverPanel').style.display = tab==='cover' ? 'flex' : 'none';
  // Land the preview on whichever frame is relevant to the tab being switched to: the trim
  // start when going back to trimming, the chosen cover frame when picking a cover. (The adjust
  // tab doesn't move the playhead — whatever frame was already showing is fine to judge a filter
  // against.)
  veSetPlaying(false);
  const video = document.getElementById('veVideo');
  if(tab === 'trim') video.currentTime = veState.trimStart;
  else if(tab === 'cover') video.currentTime = veState.coverTime;
}
document.getElementById('veTabs').addEventListener('click', (e)=>{
  const btn = e.target.closest('.pe-tab'); if(!btn) return;
  veSwitchTab(btn.dataset.tab);
});
// Stage 5 (افکت): picking a preset just updates state + the live preview filter and re-renders
// the row for the new active state — same lightweight pattern as the mute toggle below, nothing
// export-specific here since veFilterString() already threads filterPreset into every consumer.
document.getElementById('veFilterRow').addEventListener('click', (e)=>{
  const btn = e.target.closest('.ve-filter-item'); if(!btn || !veState) return;
  veState.filterPreset = btn.dataset.filter;
  veRenderFilterRow();
  document.getElementById('veVideo').style.filter = veFilterString();
});
['veBrightness','veContrast','veSaturate'].forEach(id=>{
  document.getElementById(id).addEventListener('input', (e)=>{
    if(!veState) return; // guards a stray event firing after the editor's already been closed
    const key = id === 'veBrightness' ? 'brightness' : id === 'veContrast' ? 'contrast' : 'saturate';
    veState[key] = Number(e.target.value);
    document.getElementById('veVideo').style.filter = veFilterString();
  });
});
document.getElementById('veMuteBtn').addEventListener('click', ()=>{
  if(!veState) return;
  veState.muteAudio = !veState.muteAudio;
  const btn = document.getElementById('veMuteBtn');
  btn.classList.toggle('active', veState.muteAudio);
  btn.setAttribute('aria-pressed', String(veState.muteAudio));
  // Reflect the choice immediately if a preview is already playing, rather than waiting for the
  // next play tap — otherwise toggling this mid-playback would look like it did nothing.
  if(veState.playing) document.getElementById('veVideo').muted = veState.muteAudio;
});
document.getElementById('veCoverTrack').addEventListener('pointerdown', veCoverPointerDown);
window.addEventListener('pointermove', veCoverPointerMove);
window.addEventListener('pointerup', veCoverPointerUp);
// Stage 4: the last piece of "can't-dismiss-mid-export" — the in-app guards above (veCancel's
// veSending check, the hardware-back route through closeDismissableOverlay) cover every way to
// leave the editor from inside the app, but a browser/webview-level refresh or tab close bypasses
// all of that. This at least gives the OS's own native "leave site?" prompt a chance to stop it.
window.addEventListener('beforeunload', (e)=>{
  if(!veSending) return;
  e.preventDefault();
  e.returnValue = '';
});

document.getElementById('veCancelBtn').addEventListener('click', veCancel);
document.getElementById('veSendBtn').addEventListener('click', veConfirmSend);
document.getElementById('vePlayBtn').addEventListener('click', veTogglePlay);
document.getElementById('veScrubTrack').addEventListener('pointerdown', veHandlePointerDown);
window.addEventListener('pointermove', veHandlePointerMove);
window.addEventListener('pointerup', veHandlePointerUp);
document.getElementById('veVideo').addEventListener('timeupdate', ()=>{
  if(!veState) return;
  veRenderScrub();
  if(veState.playing && document.getElementById('veVideo').currentTime >= veState.trimEnd - 0.03){
    // Loop the preview back to the trim-start instead of just stopping, so reviewing the
    // selected range doesn't need a re-tap of play every time.
    document.getElementById('veVideo').currentTime = veState.trimStart;
  }
});
document.getElementById('veVideo').addEventListener('ended', ()=>{
  if(!veState || !veState.playing) return;
  const v = document.getElementById('veVideo');
  v.currentTime = veState.trimStart;
  v.play().catch(()=>{});
});

/* ---------------- Giphy GIF picker ----------------
   The phone's own keyboard GIF tray (Gboard/Samsung Keyboard) can't send content into this
   chat input — that "این برنامه از فایل‌های GIF پشتیبانی نمی‌کند" message comes from Android
   itself, because sending rich content from a keyboard into a WebView's <input> requires the
   native Android side to implement WebViewCompat.setOnReceiveContentListener (or the older
   InputConnection.commitContent API); it can't be turned on from this HTML/JS file alone.
   This in-app Giphy search is the standard workaround (same approach Discord/Slack/Telegram's
   web clients use): search or browse trending GIFs, tap one, and it's sent as a normal chat
   media message.
   نکته‌ی مهم: قبلاً این درخواست مستقیم از گوشیِ کاربر به api.giphy.com می‌رفت — و چون Giphy
   (مثل خیلی از سرویس‌های آمریکایی) IP ایران رو به‌خاطر تحریم‌ها مسدود/محدود می‌کنه، بدون
   فیلترشکن اصلاً گیفی لود نمی‌شد. الان از طریق همون Worker خودمون (که برای AI هم استفاده
   می‌شه و از ایران بدون مشکل در دسترسه) پروکسی می‌شه؛ کلید Giphy هم دیگه اینجا نیست، رو
   خودِ Worker (env.GIPHY_API_KEY) نگه‌داری می‌شه. */
let gifPickerSearchTimer = null;
let gifPickerReqSeq = 0;
let gifPickerActiveTab = 'trending'; // 'trending' | 'recent' — search results override whichever tab is active
const GIF_RECENT_STORAGE_KEY = 'gifPicker:recent';
const GIF_RECENT_MAX = 30;
async function giphyFetch(endpoint, params){
  const headers = Object.assign({ 'Content-Type': 'application/json' }, await authHeaders());
  const res = await fetch(WORKER_BASE + '/giphy', {
    method: 'POST',
    headers,
    body: JSON.stringify({ endpoint, q: (params && params.q) || '' }),
  });
  const data = await res.json();
  if(!res.ok) throw new Error((data && data.error) || ('Giphy request failed (' + res.status + ')'));
  return data;
}
function gifPickerCellHtml(thumb, full, type){
  if(!thumb || !full) return '';
  const proxiedThumb = giphyProxyIfNeeded(thumb);
  const media = type === 'gifvideo'
    ? `<video src="${escapeHtml(proxiedThumb)}" autoplay loop muted playsinline preload="auto"></video>`
    : `<img src="${escapeHtml(proxiedThumb)}" alt="گیف" loading="lazy">`;
  return `<div class="gif-picker-cell" data-full-url="${escapeHtml(full)}" data-thumb-url="${escapeHtml(thumb)}" data-media-type="${escapeHtml(type || 'gif')}">${media}</div>`;
}
function renderGifPickerResults(results){
  const grid = document.getElementById('gifPickerGrid');
  if(!grid) return;
  const cells = (results||[]).map(r=>{
    const thumb = r.images && ((r.images.fixed_width_small && r.images.fixed_width_small.url) || (r.images.fixed_width && r.images.fixed_width.url));
    const full = r.images && ((r.images.original && r.images.original.url) || (r.images.fixed_width && r.images.fixed_width.url));
    return gifPickerCellHtml(thumb, full, 'gif'); // Giphy results are always static/animated images, never silent-video clips
  }).filter(Boolean);
  grid.innerHTML = cells.length ? cells.join('') : '<div class="cm-ov-empty">گیفی پیدا نشد.</div>';
}
/* ---------------- Recently-used GIFs ("مثل تلگرام") ----------------
   Every GIF — or silent video sent/received as a GIF-style clip — gets remembered locally
   (window.storage, per-device/per-user, not shared with other chat members) so it shows up
   under the "اخیرا استفاده‌شده" tab next time, newest first, without another Giphy request. */
async function getGifPickerRecent(){
  try{
    const res = await window.storage.get(GIF_RECENT_STORAGE_KEY, false);
    if(!res || !res.value) return [];
    const list = JSON.parse(res.value);
    return Array.isArray(list) ? list : [];
  }catch(err){
    return [];
  }
}
async function addGifPickerRecent(thumb, full, type){
  if(!full) return;
  try{
    const list = await getGifPickerRecent();
    const deduped = list.filter(g => g.full !== full);
    deduped.unshift({ thumb: thumb || full, full, type: type || 'gif' });
    await window.storage.set(GIF_RECENT_STORAGE_KEY, JSON.stringify(deduped.slice(0, GIF_RECENT_MAX)), false);
  }catch(err){
    console.error('گیف: ذخیره‌ی اخیرا استفاده‌شده‌ها ناموفق بود', err);
  }
}
async function loadGifPickerRecent(){
  const grid = document.getElementById('gifPickerGrid');
  if(grid) grid.innerHTML = '<div class="cm-ov-loading">در حال بارگذاری...</div>';
  const seq = ++gifPickerReqSeq;
  const list = await getGifPickerRecent();
  if(seq !== gifPickerReqSeq) return;
  if(!grid) return;
  if(!list.length){
    grid.innerHTML = '<div class="cm-ov-empty">هنوز گیفی نفرستادی/ذخیره نکردی. گیف‌ها و ویدیوهای بی‌صدایی که می‌فرستی یا ذخیره می‌کنی اینجا میان.</div>';
    return;
  }
  grid.innerHTML = list.map(g => gifPickerCellHtml(g.thumb, g.full, g.type)).filter(Boolean).join('');
}
function loadGifPickerActiveTab(){
  if(gifPickerActiveTab === 'recent') loadGifPickerRecent();
  else loadGifPickerTrending();
}
async function loadGifPickerTrending(){
  const grid = document.getElementById('gifPickerGrid');
  if(grid) grid.innerHTML = '<div class="cm-ov-loading">در حال بارگذاری گیف‌های پرطرفدار...</div>';
  const seq = ++gifPickerReqSeq;
  try{
    const data = await giphyFetch('trending', {});
    if(seq !== gifPickerReqSeq) return; // یه جستجوی جدیدتر از این زودتر رسیده، این نتیجه رو دور بریز
    renderGifPickerResults(data.data);
  }catch(err){
    console.error('Giphy trending load error', err);
    if(seq !== gifPickerReqSeq) return;
    if(grid) grid.innerHTML = '<div class="cm-ov-empty">مشکلی در بارگذاری گیف‌ها پیش اومد، دوباره امتحان کن.</div>';
  }
}
async function searchGifPicker(q){
  if(!q){ loadGifPickerActiveTab(); return; }
  const grid = document.getElementById('gifPickerGrid');
  if(grid) grid.innerHTML = '<div class="cm-ov-loading">در حال جستجو...</div>';
  const seq = ++gifPickerReqSeq;
  try{
    const data = await giphyFetch('search', { q });
    if(seq !== gifPickerReqSeq) return;
    renderGifPickerResults(data.data);
  }catch(err){
    console.error('Giphy search error', err);
    if(seq !== gifPickerReqSeq) return;
    if(grid) grid.innerHTML = '<div class="cm-ov-empty">مشکلی در جستجو پیش اومد.</div>';
  }
}
function openGifPicker(){
  document.getElementById('gifPickerOverlay').classList.add('show');
  const input = document.getElementById('gifPickerSearchInput');
  if(input) input.value = '';
  gifPickerActiveTab = 'trending';
  document.querySelectorAll('#gifPickerTabs .gif-picker-tab').forEach(btn=>{
    btn.classList.toggle('active', btn.dataset.tab === 'trending');
  });
  loadGifPickerActiveTab();
}
function closeGifPicker(){
  document.getElementById('gifPickerOverlay').classList.remove('show');
}
document.getElementById('gifPickerBackBtn').addEventListener('click', closeGifPicker);
document.getElementById('gifPickerSearchInput').addEventListener('input', (e)=>{
  clearTimeout(gifPickerSearchTimer);
  const q = e.target.value.trim();
  gifPickerSearchTimer = setTimeout(()=> searchGifPicker(q), 400);
});
document.getElementById('gifPickerTabs').addEventListener('click', (e)=>{
  const btn = e.target.closest('.gif-picker-tab');
  if(!btn) return;
  gifPickerActiveTab = btn.dataset.tab;
  document.querySelectorAll('#gifPickerTabs .gif-picker-tab').forEach(b=> b.classList.toggle('active', b === btn));
  const input = document.getElementById('gifPickerSearchInput');
  if(input) input.value = '';
  loadGifPickerActiveTab();
});
document.getElementById('gifPickerGrid').addEventListener('click', (e)=>{
  const cell = e.target.closest('.gif-picker-cell');
  if(!cell) return;
  const url = cell.dataset.fullUrl;
  const thumb = cell.dataset.thumbUrl;
  const type = cell.dataset.mediaType || 'gif';
  if(url){ closeGifPicker(); sendPublicChatGif(url, thumb, type); }
});

/* ---------------- Sending a Giphy GIF (or resending a saved GIF/silent-video from Recent) ----------------
   Unlike sendPublicChatMedia() there's no Storage upload step — the URL already points at
   permanent hosting (Giphy's CDN, or our own chat-media bucket for a previously-saved silent
   video), so media_path is just stored as that full URL. Same suspension/report-mode/
   daily-limit rules as any other chat message still apply. */
async function sendPublicChatGif(gifUrl, gifThumbUrl, mediaType){
  if(!gifUrl || !publicChatUser) return;
  const type = mediaType || 'gif';
  addGifPickerRecent(gifThumbUrl, gifUrl, type);
  if(isCurrentlySuspended()){
    showToast('دسترسیت به چت عمومی موقتاً بسته‌ست', 'error');
    renderSuspensionLocks();
    return;
  }
  if(isCurrentlyMuted()){
    showToast('فعلاً ساکتت کرده‌ن — نمی‌تونی گیف بفرستی', 'error');
    updateChatModeUI();
    return;
  }
  if(isChatLockedForMe()){
    showToast('چت عمومی فعلاً توسط مالک بسته شده', 'error');
    updateChatModeUI();
    return;
  }
  if(chatCooldownSecondsLeft() > 0){
    showToast(`${toFa(chatCooldownSecondsLeft())} ثانیه دیگه می‌تونی پیام بعدی رو بفرستی`, 'error');
    updateChatCooldownUI();
    return;
  }
  if(!(storeData.premium || isInTrial()) && getFreeChatMsgCountToday() >= FREE_CHAT_DAILY_LIMIT){
    showToast(`تو نسخه‌ی رایگان روزی فقط ${toFa(FREE_CHAT_DAILY_LIMIT)} پیام می‌تونی بفرستی`, 'error');
    openPremiumOverlay();
    return;
  }
  if(isReportModeActive() && !isAppOwner && !isChatReopenedForReport()){
    showToast('الان فقط ارسال گزارش کار امکان‌پذیره 📋', 'error');
    updateChatModeUI();
    return;
  }

  const streakVal = (typeof computeStreak === 'function') ? computeStreak() : 0;
  const isPremiumNow = !!(storeData.premium || isInTrial());
  const tempId = 'local-' + Date.now() + '-' + Math.random().toString(36).slice(2);
  const tempMsg = { id: tempId, user_id: publicChatUser.id, username: publicChatUsername, content: '', streak: streakVal, premium: isPremiumNow, created_at: new Date().toISOString(), is_owner: isAppOwner, media_localUrl: gifUrl, media_type: type };
  const wrap = document.getElementById('chatMessages');
  if(wrap.querySelector('.chat-empty-msg')) wrap.innerHTML = '';
  const grouped = lastChatMsgUserId === publicChatUser.id;
  wrap.insertAdjacentHTML('beforeend', publicChatMsgHtml(tempMsg, grouped));
  const pendingEl = wrap.querySelector(`.chat-msg[data-msg-id="${tempId}"]`);
  if(pendingEl) pendingEl.classList.add('cm-pending');
  lastChatMsgUserId = publicChatUser.id;
  applyChatUserFilter();
  scrollChatToBottom(false);

  try{
    const { data, error } = await sb.from('messages').insert({ user_id: publicChatUser.id, username: publicChatUsername, content: '', streak: streakVal, premium: isPremiumNow, media_path: gifUrl, media_type: type }).select().single();
    if(error) throw error;
    if(pendingEl && data){
      pendingEl.dataset.msgId = data.id;
      pendingEl.classList.remove('cm-pending');
    }
    if(!isPremiumNow) registerFreeChatMsgSent();
    try{ logDailyFeatureUse('chat'); }catch(e){}
    startChatCooldownIfNeeded();
  }catch(err){
    console.error('Giphy gif send error', err);
    showToast(`ارسال گیف ناموفق بود: ${translateTechError(err && err.message)}`, 'error');
    if(pendingEl) pendingEl.remove();
    if(!wrap.querySelector('.chat-msg')) wrap.innerHTML = '<div class="chat-empty-msg">هنوز پیامی نیست، اولین نفر باش!</div>';
  }
}


/* ---------------- One-click daily task report → public chat ---------------- */
// Invisible-in-normal-typing marker so a report bubble can always be told apart
// from a regular message, even after a page reload / for other users' devices.
const TASK_REPORT_MARKER = '⟦TASKREPORT⟧';
function getTaskReportData(){
  const doItems = getDoItems();
  const avoidItems = getAvoidItems();
  const lines = [];
  let doneCount = 0;
  doItems.forEach((label, idx)=>{
    const done = !!entry.done[idx];
    if(done) doneCount++;
    lines.push((done?'✅ ':'⭕ ') + label);
  });
  avoidItems.forEach((label, idx)=>{
    const done = !!entry.avoidDone[idx];
    if(done) doneCount++;
    lines.push((done?'✅ ':'⭕ ') + label);
  });
  const total = doItems.length + avoidItems.length;
  const pct = total ? Math.round((doneCount/total)*100) : 0;
  let text = '📋 گزارش تسک‌های امروز\n——————————\n' + (lines.join('\n') || 'تسکی ثبت نشده') + '\n——————————\n';
  if(entry.phoneHours!==null && entry.phoneHours!==undefined && entry.phoneHours!==''){
    text += '📱 استفاده از گوشی: ' + toFa(entry.phoneHours) + ' ساعت\n';
  }
  text += '📊 پیشرفت: ' + toFa(pct) + '٪ (' + toFa(doneCount) + ' از ' + toFa(total) + ')';
  return { text, doneCount, total };
}
function canSendTaskReport(){
  const { doneCount, total } = getTaskReportData();
  if(total === 0) return false;
  return doneCount * 3 >= total; // at least a third of today's tasks must be done
}
function updateReportBtnState(){
  const btn = document.getElementById('sendReportBtn');
  const hint = document.getElementById('reportBtnHint');
  if(!btn) return;
  if(isCurrentlyMuted()){
    btn.disabled = true;
    if(hint) hint.textContent = 'فعلاً ساکتی، نمی‌تونی گزارش کار هم بفرستی';
    return;
  }
  if(isChatLockedForMe()){
    btn.disabled = true;
    if(hint) hint.textContent = 'چت عمومی فعلاً توسط مالک بسته شده';
    return;
  }
  if(!isReportModeActive() && !isAppOwner){
    btn.disabled = true;
    if(hint) hint.textContent = 'ارسال گزارش کار فقط از ساعت ۲۰ تا ۲۴ فعاله';
    return;
  }
  if(!(storeData.premium || isInTrial()) && storeData.taskReportSentOnce){
    btn.disabled = true;
    if(hint) hint.textContent = 'ارسال گزارش کار تو نسخه‌ی رایگان فقط یک‌بار امکان‌پذیره — برای ارسال نامحدود، پرمیوم شو';
    return;
  }
  const { doneCount, total } = getTaskReportData();
  const ok = total > 0 && doneCount * 3 >= total;
  btn.disabled = !ok;
  if(hint){
    hint.textContent = ok ? '' : (total === 0 ? 'هنوز تسکی برای امروز نداری' : 'برای ارسال گزارش باید حداقل یک‌سوم کارهای امروزتو انجام داده باشی');
  }
}
async function sendTaskReport(){
  if(!sb || !publicChatUser) return;
  if(isCurrentlyMuted()){ showToast('فعلاً ساکتت کرده‌ن — نمی‌تونی گزارش کار بفرستی', 'error'); return; }
  if(isChatLockedForMe()){ showToast('چت عمومی فعلاً توسط مالک بسته شده', 'error'); return; }
  if(!isReportModeActive() && !isAppOwner){ showToast('ارسال گزارش کار فقط از ساعت ۲۰ تا ۲۴ فعاله', 'error'); return; }
  if(!(storeData.premium || isInTrial()) && storeData.taskReportSentOnce){
    showToast('ارسال گزارش کار تو نسخه‌ی رایگان فقط یک‌بار امکان‌پذیره', 'error');
    openPremiumOverlay();
    return;
  }
  const { text, doneCount, total } = getTaskReportData();
  if(total === 0){ showToast('هنوز تسکی برای امروز نداری', 'error'); return; }
  if(doneCount * 3 < total){ showToast('برای ارسال گزارش باید حداقل یک‌سوم کارهای امروزتو انجام داده باشی', 'error'); return; }
  const btn = document.getElementById('sendReportBtn');
  if(btn) btn.disabled = true;
  const streakVal = (typeof computeStreak === 'function') ? computeStreak() : 0;
  try{
    let { error } = await sb.from('messages').insert({ user_id: publicChatUser.id, username: publicChatUsername, content: TASK_REPORT_MARKER + text, streak: streakVal, premium: !!(storeData.premium || isInTrial()) });
    if(error && /premium/i.test(error.message || '')){
      ({ error } = await sb.from('messages').insert({ user_id: publicChatUser.id, username: publicChatUsername, content: TASK_REPORT_MARKER + text, streak: streakVal }));
    }
    if(error && /streak/i.test(error.message || '')){
      ({ error } = await sb.from('messages').insert({ user_id: publicChatUser.id, username: publicChatUsername, content: TASK_REPORT_MARKER + text }));
    }
    if(error) showToast('گزارش ارسال نشد', 'error');
    else{
      showToast('گزارش ارسال شد ✅', 'success');
      if(!storeData.reportSentDates) storeData.reportSentDates = {};
      storeData.reportSentDates[todayKey()] = true;
      if(!(storeData.premium || isInTrial())){ storeData.taskReportSentOnce = true; }
      saveData();
      try{ renderXP(); }catch(err){}
      // If it's already 22:00+ the report we just sent should unlock normal chat
      // for the rest of the window right away, not after the next 30s poll.
      try{ updateChatModeUI(); }catch(err){}
    }
  }catch(err){ showToast('گزارش ارسال نشد', 'error'); }
  finally{ updateReportBtnState(); }
}
document.getElementById('sendReportBtn').addEventListener('click', sendTaskReport);

initChatAuth();
updateChatModeUI();

/* ================= رفیق هم‌مسیر (Accountability Buddy) =================
   Lives as a 4th tab inside the «عمومی» (public) section, alongside
   چت/لیدربورد/پروفایل — reached via #pubSubnav, not a side-menu subpage.
   Requires these Supabase objects (see buddy-supabase-schema.sql shipped
   alongside this file — run it once in the Supabase SQL editor):
     tables: buddy_requests, buddy_pairs, buddy_messages
     columns added to profiles: today_done boolean, today_date date, current_streak integer
     RPCs: accept_buddy_request(req_id uuid), request_random_buddy()
   Two ways to become buddies:
   1) Pick someone directly — a "🤝 هم‌مسیر شو" button on their card in the
      لیدربورد tab (podium + main list), wired via lbBuddyBtnHtml() above.
   2) Random & anonymous — the "🎲" button below, which calls the
      request_random_buddy() RPC so the client never sees the full user list;
      the server itself picks a random buddy-less profile.
   Once paired, both people only ever see each other's today-completed
   status + streak, plus a private two-person chat — never the other
   person's full checklist. Anonymous pairs additionally mask the name/avatar
   on both sides (in this tab and in the chat), everywhere else stays the
   same as a normal buddy pair. */
let myBuddyPair = null;              // the active buddy_pairs row involving me, or null
let myPendingBuddyRequests = [];     // pending buddy_requests rows where I'm from_user OR to_user
let buddyPartnerProfile = null;
let buddyMessagesChannel = null;
let lastBuddyMsgSenderId = null;

function todayKeyLocal(){
  const d = new Date();
  return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
}
// Same 60%-of-today's-tasks rule computeStreak() uses per day, just for today alone —
// so the buddy status pill always agrees with what actually keeps the streak alive.
function isTodayDoneLocal(){
  const key = todayKeyLocal();
  const e = storeData.entries[key];
  if(!e) return false;
  const done = Object.values(e.done||{}).filter(Boolean).length
    + Object.values(e.avoidDone||{}).filter(Boolean).length
    + Object.values(e.momentDone||{}).filter(Boolean).length;
  const tot = e.total || totalToday();
  const pct = tot ? Math.round((done/tot)*100) : 0;
  return pct >= 60;
}
let lastBuddyStatusSyncKey = null;
async function syncMyBuddyDailyStatus(){
  if(!sb || !publicChatUser) return;
  const todayDone = isTodayDoneLocal();
  const streak = (typeof computeStreak === 'function') ? computeStreak() : 0;
  const key = todayKeyLocal()+'|'+todayDone+'|'+streak;
  if(key === lastBuddyStatusSyncKey) return;
  try{
    await sb.from('profiles').update({ today_done: todayDone, today_date: todayKeyLocal(), current_streak: streak }).eq('id', publicChatUser.id);
    lastBuddyStatusSyncKey = key;
  }catch(err){ console.error('Buddy status sync failed', err); }
}

async function loadMyBuddyRelations(){
  if(!sb || !publicChatUser){ myBuddyPair = null; myPendingBuddyRequests = []; return; }
  try{
    const [{ data: pair }, { data: reqs }] = await Promise.all([
      sb.from('buddy_pairs').select('*').or(`user_a.eq.${publicChatUser.id},user_b.eq.${publicChatUser.id}`).eq('status','active').maybeSingle(),
      sb.from('buddy_requests').select('*').or(`from_user.eq.${publicChatUser.id},to_user.eq.${publicChatUser.id}`).eq('status','pending')
    ]);
    myBuddyPair = pair || null;
    myPendingBuddyRequests = reqs || [];
  }catch(err){
    console.error('Buddy relations load failed', err);
    myBuddyPair = null; myPendingBuddyRequests = [];
  }
}

async function sendDirectBuddyRequest(targetUid){
  if(!sb || !publicChatUser) return;
  if(myBuddyPair){ showToast('همین الان یه هم‌مسیر فعال داری', 'error'); return; }
  try{
    const { error } = await sb.from('buddy_requests').insert({ from_user: publicChatUser.id, to_user: targetUid, anonymous: false });
    if(error){ showToast('درخواست ارسال نشد', 'error'); return; }
    showToast('درخواست هم‌مسیری فرستاده شد 🤝', 'success');
    await loadMyBuddyRelations();
    if(document.getElementById('tab-leaderboard').classList.contains('active')) loadLeaderboard(true);
  }catch(err){ showToast('درخواست ارسال نشد', 'error'); }
}
async function acceptBuddyRequest(reqId){
  if(!sb || !publicChatUser) return;
  try{
    const { error } = await sb.rpc('accept_buddy_request', { req_id: reqId });
    if(error){ showToast('قبول کردن درخواست انجام نشد', 'error'); return; }
    showToast('هم‌مسیر شدید! 🎉', 'success');
    await loadMyBuddyRelations();
    if(document.getElementById('tab-buddy').classList.contains('active')) renderBuddyTab();
    if(document.getElementById('tab-leaderboard').classList.contains('active')) loadLeaderboard(true);
  }catch(err){ showToast('قبول کردن درخواست انجام نشد', 'error'); }
}
async function declineBuddyRequest(reqId){
  if(!sb) return;
  try{
    const { error } = await sb.from('buddy_requests').update({ status:'declined', responded_at: new Date().toISOString() }).eq('id', reqId);
    if(error){ showToast('انجام نشد', 'error'); return; }
    await loadMyBuddyRelations();
    renderBuddyTab();
  }catch(err){ showToast('انجام نشد', 'error'); }
}
async function cancelBuddyRequest(reqId){
  if(!sb) return;
  try{
    const { error } = await sb.from('buddy_requests').update({ status:'cancelled', responded_at: new Date().toISOString() }).eq('id', reqId);
    if(error){ showToast('انجام نشد', 'error'); return; }
    await loadMyBuddyRelations();
    renderBuddyTab();
  }catch(err){ showToast('انجام نشد', 'error'); }
}
async function requestRandomBuddy(){
  if(!sb || !publicChatUser) return;
  const btn = document.getElementById('buddyRandomBtn');
  if(btn){ btn.disabled = true; btn.textContent = 'در حال جست‌وجو...'; }
  try{
    const { error } = await sb.rpc('request_random_buddy');
    if(error){ showToast('الان کسی برای جفت‌شدن تصادفی در دسترس نیست', 'error'); return; }
    showToast('یه درخواست تصادفی و ناشناس فرستاده شد 🎲', 'success');
    await loadMyBuddyRelations();
    renderBuddyTab();
  }catch(err){ showToast('مشکلی پیش اومد', 'error'); }
  finally{ if(btn){ btn.disabled = false; btn.textContent = '🎲 پیدا کردن هم‌مسیر تصادفی (ناشناس)'; } }
}
async function endBuddyPair(){
  if(!sb || !myBuddyPair) return;
  if(!confirm('مطمئنی می‌خوای هم‌مسیریتونو تموم کنی؟')) return;
  try{
    const { error } = await sb.from('buddy_pairs').update({ status:'ended', ended_at: new Date().toISOString() }).eq('id', myBuddyPair.id);
    if(error){ showToast('انجام نشد', 'error'); return; }
    if(buddyMessagesChannel){ sb.removeChannel(buddyMessagesChannel); buddyMessagesChannel = null; }
    showToast('هم‌مسیریتون تموم شد');
    await loadMyBuddyRelations();
    renderBuddyTab();
  }catch(err){ showToast('انجام نشد', 'error'); }
}

/* ---- Buddy tab rendering ---- */
let buddyTabLastLoadedAt = 0;
const BUDDY_FRESH_MS = 12000;
async function loadBuddyTab(force){
  if(!force && buddyTabLastLoadedAt && (Date.now() - buddyTabLastLoadedAt) < BUDDY_FRESH_MS) return;
  const loadingEl = document.getElementById('buddyLoading');
  const pairedBox = document.getElementById('buddyPairedBox');
  const unpairedBox = document.getElementById('buddyUnpairedBox');
  const errEl = document.getElementById('buddyEmptyErr');
  loadingEl.style.display = 'flex';
  pairedBox.style.display = 'none';
  unpairedBox.style.display = 'none';
  errEl.style.display = 'none';
  if(!chatConfigured() || !sb){
    loadingEl.style.display = 'none';
    errEl.style.display = 'block';
    errEl.textContent = 'این بخش هنوز به سرور وصل نشده.';
    return;
  }
  try{
    await loadMyBuddyRelations();
    await renderBuddyTab();
    buddyTabLastLoadedAt = Date.now();
  }catch(err){
    console.error('Buddy tab load failed', err);
    loadingEl.style.display = 'none';
    errEl.style.display = 'block';
    errEl.textContent = 'مشکلی پیش اومد. دوباره امتحان کن.';
  }
}
async function renderBuddyTab(){
  const loadingEl = document.getElementById('buddyLoading');
  const pairedBox = document.getElementById('buddyPairedBox');
  const unpairedBox = document.getElementById('buddyUnpairedBox');
  loadingEl.style.display = 'none';
  if(myBuddyPair){
    unpairedBox.style.display = 'none';
    pairedBox.style.display = 'block';
    await renderBuddyPartner();
    loadBuddyMessages();
  } else {
    pairedBox.style.display = 'none';
    unpairedBox.style.display = 'block';
    await renderBuddyRequestLists();
  }
}
async function renderBuddyPartner(){
  const partnerId = myBuddyPair.user_a === publicChatUser.id ? myBuddyPair.user_b : myBuddyPair.user_a;
  const anon = !!myBuddyPair.anonymous;
  let profile = null;
  try{
    const cols = anon ? 'today_done,today_date,current_streak' : 'id,username,gender,current_streak,today_done,today_date,avatar_url';
    const { data } = await sb.from('profiles').select(cols).eq('id', partnerId).single();
    profile = data;
  }catch(err){}
  buddyPartnerProfile = profile;
  const name = anon ? 'همراه ناشناس' : (profile ? displayName(profile.username) : 'کاربر');
  const avatarEl = document.getElementById('buddyPartnerAvatar');
  // Anonymous pairing never shows the real photo — that would defeat the whole point of "ناشناس".
  avatarEl.innerHTML = anon ? '🎭' : lbAvatarInnerHtml(profile, name);
  avatarEl.style.background = anon ? '' : ((profile && profile.avatar_url) ? 'transparent' : lbColorFor(partnerId));
  avatarEl.classList.toggle('buddy-anon-avatar', anon);
  document.getElementById('buddyPartnerName').textContent = name;
  document.getElementById('buddyPartnerSub').textContent = anon
    ? 'هم‌مسیر ناشناس — فقط وضعیت روزانه و چتتون به هم دیده می‌شه'
    : ('رکورد پشت‌سرهم: '+toFa((profile&&profile.current_streak)||0)+' روز');
  const pillEl = document.getElementById('buddyPartnerTodayPill');
  const isFresh = profile && profile.today_date === todayKeyLocal();
  if(isFresh && profile.today_done){ pillEl.textContent = '✅ امروز کاراشو انجام داده'; pillEl.className = 'buddy-today-pill done'; }
  else if(isFresh && !profile.today_done){ pillEl.textContent = '⏳ هنوز امروزو ثبت نکرده'; pillEl.className = 'buddy-today-pill notyet'; }
  else { pillEl.textContent = '❔ وضعیت امروزش معلوم نیست'; pillEl.className = 'buddy-today-pill'; }
}
async function renderBuddyRequestLists(){
  const incoming = myPendingBuddyRequests.filter(r=> r.to_user === publicChatUser.id);
  const outgoing = myPendingBuddyRequests.filter(r=> r.from_user === publicChatUser.id);
  const namedIds = Array.from(new Set(
    incoming.filter(r=>!r.anonymous).map(r=>r.from_user)
      .concat(outgoing.filter(r=>!r.anonymous).map(r=>r.to_user))
  ));
  let profilesById = {};
  if(namedIds.length){
    try{
      const { data } = await sb.from('profiles').select('id,username,gender,avatar_url').in('id', namedIds);
      (data||[]).forEach(p=> profilesById[p.id] = p);
    }catch(err){}
  }
  const incomingSection = document.getElementById('buddyIncomingSection');
  const incomingList = document.getElementById('buddyIncomingList');
  const outgoingSection = document.getElementById('buddyOutgoingSection');
  const outgoingList = document.getElementById('buddyOutgoingList');

  incomingSection.style.display = incoming.length ? 'block' : 'none';
  incomingList.innerHTML = incoming.map(r=>{
    if(r.anonymous){
      return `<div class="buddy-request-row">
        <div style="flex:1;">
          <div class="buddy-request-name">🎭 یه نفر ناشناس می‌خواد هم‌مسیرت بشه</div>
          <div class="buddy-request-sub">اگه قبول کنی، هویت هر دوتون تو این هم‌مسیری مخفی می‌مونه</div>
        </div>
        <div class="buddy-request-actions">
          <button class="buddy-req-btn accept" data-accept-req="${r.id}">قبول</button>
          <button class="buddy-req-btn decline" data-decline-req="${r.id}">رد</button>
        </div>
      </div>`;
    }
    const p = profilesById[r.from_user];
    const name = p ? displayName(p.username) : 'کاربر';
    return `<div class="buddy-request-row">
      <div class="lb-avatar-wrap"><div class="lb-avatar" style="background:${p&&p.avatar_url?'transparent':lbColorFor(r.from_user)}">${lbAvatarInnerHtml(p, name)}</div>${lbGenderBadge(p&&p.gender)}</div>
      <div style="flex:1;min-width:0;">
        <div class="buddy-request-name">${escapeHtml(name)}</div>
        <div class="buddy-request-sub">می‌خواد هم‌مسیرت بشه</div>
      </div>
      <div class="buddy-request-actions">
        <button class="buddy-req-btn accept" data-accept-req="${r.id}">قبول</button>
        <button class="buddy-req-btn decline" data-decline-req="${r.id}">رد</button>
      </div>
    </div>`;
  }).join('');

  outgoingSection.style.display = outgoing.length ? 'block' : 'none';
  outgoingList.innerHTML = outgoing.map(r=>{
    const label = r.anonymous
      ? '🎲 درخواست تصادفی و ناشناس تو در انتظار پاسخه'
      : ('درخواستت به '+escapeHtml(profilesById[r.to_user] ? displayName(profilesById[r.to_user].username) : 'کاربر')+' در انتظار پاسخه');
    return `<div class="buddy-request-row">
      <div style="flex:1;"><div class="buddy-request-name">${label}</div></div>
      <div class="buddy-request-actions">
        <button class="buddy-req-btn cancel" data-cancel-req="${r.id}">لغو</button>
      </div>
    </div>`;
  }).join('');
}
document.getElementById('tab-buddy').addEventListener('click', (e)=>{
  const accBtn = e.target.closest('[data-accept-req]');
  if(accBtn){ acceptBuddyRequest(accBtn.dataset.acceptReq); return; }
  const decBtn = e.target.closest('[data-decline-req]');
  if(decBtn){ declineBuddyRequest(decBtn.dataset.declineReq); return; }
  const cancelBtn = e.target.closest('[data-cancel-req]');
  if(cancelBtn){ cancelBuddyRequest(cancelBtn.dataset.cancelReq); return; }
});
document.getElementById('buddyRandomBtn').addEventListener('click', requestRandomBuddy);
document.getElementById('buddyEndBtn').addEventListener('click', endBuddyPair);

/* ---- Private buddy chat — same shape as the public chat, scoped to one pair_id ---- */
function buddyMsgHtml(m, grouped){
  const own = publicChatUser && m.sender_id === publicChatUser.id;
  const anon = myBuddyPair && myBuddyPair.anonymous;
  const nm = own ? 'تو' : (anon ? 'همراه ناشناس' : (buddyPartnerProfile ? displayName(buddyPartnerProfile.username) : 'هم‌مسیر'));
  const time = new Date(m.created_at).toLocaleTimeString('fa-IR', {hour:'2-digit', minute:'2-digit'});
  const head = grouped ? '' : `<div class="cm-head"><div class="cm-name">${escapeHtml(nm)}</div></div>`;
  return `<div class="chat-msg${own?' own':''}${grouped?' grouped':''}" data-msg-id="${m.id}">
    ${head}
    <div class="cm-text">${linkifyChatText(m.content)}</div>
    <div class="cm-bottom-row"><span class="cm-time">${time}</span></div>
  </div>`;
}
function renderBuddyMessages(rows){
  const wrap = document.getElementById('buddyMessages');
  if(!rows || !rows.length){ wrap.innerHTML = '<div class="chat-empty-msg">هنوز پیامی نیست — اولین قدم رو تو بردار 👋</div>'; lastBuddyMsgSenderId = null; return; }
  let prev = null;
  wrap.innerHTML = rows.map(m=>{ const grouped = prev===m.sender_id; prev = m.sender_id; return buddyMsgHtml(m, grouped); }).join('');
  lastBuddyMsgSenderId = prev;
  wrap.scrollTop = wrap.scrollHeight;
}
async function loadBuddyMessages(){
  if(!sb || !myBuddyPair) return;
  try{
    const { data, error } = await sb.from('buddy_messages').select('*').eq('pair_id', myBuddyPair.id).order('created_at', {ascending:true}).limit(300);
    if(!error) renderBuddyMessages(data);
    if(buddyMessagesChannel){ sb.removeChannel(buddyMessagesChannel); buddyMessagesChannel = null; }
    buddyMessagesChannel = sb.channel('buddy:'+myBuddyPair.id)
      .on('postgres_changes', {event:'INSERT', schema:'public', table:'buddy_messages', filter:'pair_id=eq.'+myBuddyPair.id}, payload=>{
        const wrap = document.getElementById('buddyMessages');
        if(wrap.querySelector('.chat-empty-msg')) wrap.innerHTML = '';
        const grouped = lastBuddyMsgSenderId === payload.new.sender_id;
        wrap.insertAdjacentHTML('beforeend', buddyMsgHtml(payload.new, grouped));
        lastBuddyMsgSenderId = payload.new.sender_id;
        wrap.scrollTop = wrap.scrollHeight;
      }).subscribe();
  }catch(err){ console.error('Buddy messages load failed', err); }
}
async function sendBuddyMessage(){
  const input = document.getElementById('buddyChatInput');
  const text = input.value.trim();
  if(!text || !publicChatUser || !myBuddyPair) return;
  if(checkCrisisText(text)){
    input.value = '';
    autoGrowChatBox(input);
    renderCrisisBanner('buddyChatCrisisSlot');
    return;
  }
  if(containsAbusiveLanguage(text)){ showToast('لطفاً محترمانه بنویس 🙏', 'error'); return; }
  input.value = '';
  autoGrowChatBox(input);
  try{
    const { error } = await sb.from('buddy_messages').insert({ pair_id: myBuddyPair.id, sender_id: publicChatUser.id, content: text });
    if(error) showToast('پیام ارسال نشد', 'error');
  }catch(err){ showToast('پیام ارسال نشد', 'error'); }
}
document.getElementById('buddyChatSendBtn').addEventListener('click', sendBuddyMessage);
document.getElementById('buddyChatInput').addEventListener('keydown', e=>{
  if(e.key==='Enter' && !e.shiftKey){ e.preventDefault(); sendBuddyMessage(); }
});

