/* ==================== Invite friends (ported) ==================== */
// ثابت: لینک دانلود اپ — صفحه‌ی رسمی برنامه در مایکت (طبق قوانین مایکت، معرفی/ارجاع
// باید فقط به مایکت باشه، نه به مارکت یا دامنه‌ی دیگه).
const APP_DOWNLOAD_URL = 'https://myket.ir/app/com.mahdihd648.dreamlifeapp';
const INVITE_MESSAGE = 'یه اپ پیدا کردم به اسم Dreamlife که واقعا آدمو معتاد به بهتر شدن می‌کنه 🚀 یه مشاور شخصی هوش مصنوعی داره که انگار واقعا حرفاتو می‌فهمه، یه گروه چت با آدمای هم‌مسیر که هوای همو دارن، و مدیتیشن و فن بیان هم توشه. با کد دعوتم عضو شو تا هردومون تخفیف بگیریم 🎁';
document.getElementById('inviteShareBtn').addEventListener('click', async ()=>{
  const codeText = document.getElementById('inviteTabCode').textContent;
  const msg = codeText && codeText !== '—' ? INVITE_MESSAGE + ` کد دعوتم اینه: ${codeText} — ` : INVITE_MESSAGE;
  const text = msg + APP_DOWNLOAD_URL;
  // اول با پلاگین نیتیو Capacitor (اگه توی پروژه اضافه شده باشه) شیت اشتراک‌گذاری واقعی گوشی رو باز می‌کنیم،
  // چون وب‌ویوی اندروید برخلاف مرورگر کروم معمولاً navigator.share رو پیاده‌سازی نمی‌کنه.
  const nativeShare = window.Capacitor && Capacitor.Plugins && Capacitor.Plugins.Share;
  if(nativeShare){
    try{ await nativeShare.share({ title:'چک‌لیست روزانه', text: msg, url: APP_DOWNLOAD_URL, dialogTitle:'اشتراک‌گذاری کد دعوت' }); return; }
    catch(err){ /* کاربر لغو کرد یا شکست خورد؛ می‌ریم سراغ کپی */ }
  } else if(navigator.share){
    try{ await navigator.share({ title:'چک‌لیست روزانه', text: msg, url: APP_DOWNLOAD_URL }); return; }
    catch(err){ if(err && err.name === 'AbortError') return; /* کاربر خودش لغو کرد، کپی نکن */ }
  }
  try{ await navigator.clipboard.writeText(text); showToast('پیام دعوت کپی شد'); }
  catch(err){ showToast('کپی نشد، خودت کپی کن', 'error'); }
});

/* ==================== In-App Billing (Myket) ====================
   جایگزین زرین‌پال. سمت نیتیو یه پلاگین Capacitor به اسم Capacitor.Plugins.MarketBilling
   وجود داره (فایل native-billing/MarketBillingPlugin.java) که به سرویس بیلینگ مایکت وصل می‌شه.
   متدها: purchase({sku}) => {sku,purchaseToken,orderId,store}, getPurchases() => {purchases:[...]},
   consumePurchase({purchaseToken}), getStore() => {store}.
   SKUهای «premium»، «donate_50000»، «donate_100000»، «donate_200000» باید با همین شناسه‌ها
   توی پنل توسعه‌دهنده‌ی مایکت ثبت بشن (با قیمت‌های متناظر). */
function getIabPlugin(){
  if(window.Capacitor && Capacitor.Plugins && Capacitor.Plugins.MarketBilling) return Capacitor.Plugins.MarketBilling;
  // تشخیصی: این لاگ مشخص می‌کنه دقیقاً کدوم لایه گم شده - خودِ Capacitor لود نشده،
  // یا Capacitor هست ولی پلاگین MarketBilling توش رجیستر نشده. با اتصال گوشی به
  // Chrome (chrome://inspect) یا adb logcat موقع تست، این خط دقیقاً می‌گه مشکل کجاست.
  console.error('[IAB] پلاگین MarketBilling پیدا نشد.',
    'Capacitor روی صفحه هست؟', !!window.Capacitor,
    '| Capacitor.Plugins هست؟', !!(window.Capacitor && Capacitor.Plugins),
    '| پلاگین‌های واقعاً رجیسترشده:', (window.Capacitor && Capacitor.Plugins) ? Object.keys(Capacitor.Plugins).join(', ') : 'n/a (Capacitor.Plugins تعریف نشده)');
  iabDebugStep('پلاگین بیلینگ (MarketBilling)', false,
    'Capacitor=' + !!window.Capacitor +
    ' | Capacitor.Plugins=' + !!(window.Capacitor && Capacitor.Plugins) +
    ' | پلاگین‌های رجیسترشده=' + ((window.Capacitor && Capacitor.Plugins) ? Object.keys(Capacitor.Plugins).join(',') : 'هیچی'));
  return null;
}
function withTimeout(promise, ms){
  return new Promise((resolve, reject)=>{
    const t = setTimeout(()=> reject(new Error('iab-timeout')), ms);
    promise.then(v=>{ clearTimeout(t); resolve(v); }, e=>{ clearTimeout(t); reject(e); });
  });
}
// موازی با صبر برای پاسخ نیتیوِ purchase()، هر ۶ ثانیه یه‌بار خودمون از مارکت
// می‌پرسیم که آیا این خرید واقعاً ثبت شده یا نه. چون تو پنل دیباگِ خودِ کاربر دیده
// شد که بعضی وقت‌ها callback نیتیو اصلاً نمی‌رسه (نه رد می‌شه نه قبول)، و کد فقط
// کورکورانه تا سقف ۱۲۰ ثانیه صبر می‌کرد، درحالی‌که خودِ خرید رو مارکت خیلی زودتر
// کامل شده بود. هرکدوم اول جواب بده (نیتیو یا این چک دوره‌ای)، برنده‌ست.
function iabPollForPurchase(plugin, sku, maxWaitMs){
  const premiumSkus = new Set(Object.values(PREMIUM_SKU_BY_DISCOUNT));
  const start = Date.now();
  let stopped = false;
  const promise = new Promise((resolve, reject)=>{
    async function tick(){
      if(stopped) return;
      if(Date.now() - start >= maxWaitMs){ stopped = true; reject(new Error('iab-timeout')); return; }
      try{
        const owned = await plugin.getPurchases();
        const found = owned && owned.purchases && owned.purchases.find(p => p.sku === sku || premiumSkus.has(p.sku));
        if(found && !stopped){ stopped = true; resolve(found); return; }
      }catch(err){ /* خطای گذرا رو نادیده بگیر، دور بعد دوباره امتحان می‌کنیم */ }
      if(!stopped) setTimeout(tick, 6000);
    }
    // اولین چک رو فوری نمی‌زنیم چون تازه داره پنل مایکت باز می‌شه؛ ۶ ثانیه فرصت بده.
    setTimeout(tick, 6000);
  });
  return { promise, stop(){ stopped = true; } };
}
async function iabPurchase(sku){
  console.log('[IAB] درخواست خرید، sku =', sku);
  const plugin = getIabPlugin();
  if(!plugin){ showToast('این نسخه هنوز به پرداخت درون‌برنامه‌ای مایکت وصل نشده', 'error'); return null; }
  iabDebugStep('پلاگین بیلینگ (MarketBilling)', true, 'پیدا شد');
  const poller = iabPollForPurchase(plugin, sku, 120000);
  try{
    console.log('[IAB] پلاگین پیدا شد، در حال صدا زدن purchase() نیتیو...');
    iabDebugStep('purchase() نیتیو', null, 'در حال باز شدن پنل مایکت... (هم‌زمان هر ۶ ثانیه خودکار هم چک می‌کنیم)');
    // اگه کاربر وسط درگاه پرداخت برگرده عقب یا فیلترشکن رو خاموش/روشن کنه، ممکنه
    // callback نیتیو هیچ‌وقت نرسه و promise برای همیشه معلق بمونه؛ برای همین یه
    // سقف زمانی می‌ذاریم تا دکمه هیچ‌وقت قفل نمونه. همزمان، iabPollForPurchase هم
    // داره جدا چک می‌کنه — هرکدوم زودتر جواب بده همون برنده‌ست.
    const result = await Promise.race([ withTimeout(plugin.purchase({ sku }), 120000), poller.promise ]);
    poller.stop();
    console.log('[IAB] purchase() نیتیو resolve شد:', result);
    iabDebugStep('purchase() نیتیو', true, result);
    return result;
  }catch(e){
    poller.stop();
    console.error('[IAB] purchase() نیتیو fail شد:', (e && e.message) || e, e);
    iabDebugStep('purchase() نیتیو', false, (e && e.message) || String(e));
    if(e && typeof e.message === 'string' && e.message.indexOf('مایکت رو این گوشی در دسترس نیست') !== -1){
      // این پیام دقیقاً همون چیزیه که ensureBound() تو MarketBillingPlugin.java برمی‌گردونه
      // وقتی نتونسته به سرویس بیلینگ مایکت وصل بشه (چه چون خودِ اپ مایکت رو گوشی نیست،
      // چه چون <queries> تو Manifest جا افتاده). این با «کاربر منصرف شد» فرق داره و
      // باید جدا و رک نشون داده بشه — هم برای کاربر واقعی، هم برای دیباگ حین ری‌ویو.
      iabDebugStep('نتیجه‌ی نهایی', false, 'سرویس بیلینگ مایکت در دسترس نیست');
      showToast('برنامه‌ی مایکت روی این گوشی پیدا یا وصل نشد؛ لطفاً از نصب و به‌روز بودن مایکت مطمئن شو', 'error');
    } else if(e && e.message === 'iab-timeout'){
      // بعضی مسیرهای مایکت (مثلاً شارژ کیف‌پول وسط خرید) نتیجه رو هیچ‌وقت به
      // onActivityResult برنمی‌گردونن، درحالی‌که خودِ خرید رو مارکت واقعاً ثبت
      // می‌شه. به‌جای اینکه فقط بگیم «از بازیابی خرید قبلی استفاده کن»، همینجا
      // خودمون خودکار همون چک رو انجام می‌دیم؛ اگه پیدا و تایید بشه، کاربر اصلاً
      // خطا نمی‌بینه، مستقیم جشن فعال‌سازی رو می‌بینه.
      iabDebugStep('پاسخی از purchase() نرسید', null, 'در حال چک خودکار خرید واقعی از طریق getPurchases()...');
      const recovered = await activateOwnedPremiumIfAny({ silent:true });
      iabDebugStep('نتیجه‌ی چک خودکار', recovered, recovered ? 'خرید واقعی پیدا و فعال شد 🎉' : 'چیزی پیدا نشد یا هنوز آماده نیست');
      if(!recovered){
        showToast('پاسخی از درگاه پرداخت نرسید؛ اگه خرید انجام شده، از «بازیابی خرید قبلی» استفاده کن', 'error');
      }
    } else {
      showToast('پرداخت انجام نشد یا لغو شد', 'error');
    }
    return null;
  }
}
// ضامن اطمینان: هر بار اپ از پس‌زمینه برمی‌گرده (مثلاً کاربر از صفحه‌ی درگاه یا
// اپ مایکت برگشته)، اگه دکمه‌ی خرید هنوز رو حالت "در حال اتصال..." قفل مونده
// بود (یعنی promise نیتیو گم شده)، دستی آزادش می‌کنیم.
function resetPremiumPayBtnIfStuck(){
  const btn = document.getElementById('premiumPayBtn');
  const wasStuck = !!(btn && btn.disabled);
  if(btn && btn.disabled){ btn.disabled = false; btn.textContent = '💳 خرید نسخه‌ی پرمیوم'; }
  if(wasStuck){
    // دکمه قفل مونده بود یعنی وسط یه تلاش برای خرید بودیم و اپ به مایکت رفته و
    // برگشته (مثلاً برای شارژ کیف‌پول) بدون اینکه نتیجه به onActivityResult برسه —
    // درست همون لحظه‌ی برگشت، خودکار چک می‌کنیم خرید واقعاً انجام شده یا نه. اگه
    // iabPurchase() هنوز داره منتظر می‌مونه (تایم‌اوتش هنوز نرسیده)، این چکِ زودتر
    // همون‌جا نتیجه رو می‌گیره، بدون نیاز به صبر تا ۱۲۰ ثانیه.
    activateOwnedPremiumIfAny({ silent:true });
  }
}
try{
  if(window.Capacitor && Capacitor.Plugins && Capacitor.Plugins.App){
    Capacitor.Plugins.App.addListener('resume', resetPremiumPayBtnIfStuck);
    Capacitor.Plugins.App.addListener('resume', ()=>{ try{ updateLiveCounter(); }catch(e){} });
    Capacitor.Plugins.App.addListener('resume', ()=>{ try{ applyPendingOpenChat(); }catch(e){} });
    Capacitor.Plugins.App.addListener('appStateChange', (state)=>{
      if(state && state.isActive) resetPremiumPayBtnIfStuck();
      if(state && state.isActive){ try{ updateLiveCounter(); }catch(e){} }
      handleAppForegroundChange(!!(state && state.isActive));
      handleAppUsageForegroundChange(!!(state && state.isActive));
    });
  }
}catch(e){}
/* در وب/WebView کپاسیتور، وقتی اپ می‌ره پس‌زمینه، تایمرهای جاوااسکریپت (از جمله
   تایمر داخلیِ supabase-js برای رفرش خودکار توکن، و همینطور setInterval یک‌ثانیه‌ایِ
   updateLiveCounter که تشخیص «روز عوض شده یا نه» رو انجام می‌ده) هَنگ/متوقف می‌شن.
   یعنی اگه اپ یه مدت (حتی فقط از نیمه‌شب گذشته باشه) پس‌زمینه بمونه، ممکنه تا وقتی
   کاربر یه کار دیگه‌ای نکنه، آواتار/روز برنامه هنوز «دیروز» رو نشون بده (مثلاً «امروز
   روز ۸ توئه» با اینکه واقعاً روز ۹ شده). برای همین علاوه بر تایمر، هر رویداد resume/
   appStateChange و visibilitychange هم صریحاً updateLiveCounter (که خودش
   checkDayRollover رو صدا می‌زنه) رو دوباره اجرا می‌کنه تا لحظه‌ی برگشت به اپ، بدون
   نیاز به صبر کردن برای تیک بعدی تایمر، فوراً رفع بشه.
   یه مدت (بیشتر از عمر access token، پیش‌فرض ۱ ساعت) پس‌زمینه بمونه، رفرش زمان‌بندی‌شده
   هیچ‌وقت اجرا نمی‌شه؛ وقتی کاربر برمی‌گرده، سشن رو client عملاً منقضی/نامعتبر می‌بینه
   و بعضی وقتا با یه ایونت SIGNED_OUT گذرا (که handlePublicChatSession رو با
   session=null صدا می‌زنه) کاربر رو دوباره روی باکس ورود/ثبت‌نام می‌ندازه — با اینکه
   واقعاً هنوز لاگین بوده و refresh token هنوز معتبره. این همون باگیه که گزارش شده:
   «بعضی وقتا برمی‌گردیم تو چت عمومی، دوباره باکس ورود میاد».
   طبق راهنمای رسمی Supabase برای اپ‌های هایبرید (React Native/Capacitor)، باید
   خودمون رفرش خودکار رو دستی با چرخه‌ی resume/pause اپ هماهنگ کنیم، و علاوه بر اون
   سشن رو صریح دوباره چک کنیم تا اگه ایونتی گم شده باشه هم جبران بشه. */
// ---- ردیابی «چقدر وقت امروز تو اپ گذشت» (برای پاپ‌آپ تاریخچه‌ی برنامه) ----
// این عمداً از handleAppForegroundChange جداست چون اون تابع به sb (کلاینت Supabase)
// وابسته‌ست و اگه هنوز آماده نباشه هیچ کاری نمی‌کنه؛ ردیابیِ زمان باید همیشه کار کنه.
// هر ۶۰ ثانیه که اپ در پیش‌زمینه‌ست، زمان گذشته رو به دقیقه‌های امروز اضافه می‌کنه، و
// لحظه‌ای که اپ می‌ره پس‌زمینه هم باقی‌مونده رو فوری فلاش می‌کنه تا چیزی گم نشه.
let appUsageSessionStart = Date.now();
let appUsageFlushTimer = setInterval(()=>flushAppUsage(), 60000);
let lastAppUsageState = true;
function flushAppUsage(){
  if(!appUsageSessionStart) return;
  const now = Date.now();
  addAppUsageMinutes(now - appUsageSessionStart);
  appUsageSessionStart = now;
}
function addAppUsageMinutes(ms){
  if(!(ms > 0)) return;
  if(!storeData.dailyUsageMinutes) storeData.dailyUsageMinutes = {};
  const k = todayKey();
  storeData.dailyUsageMinutes[k] = (storeData.dailyUsageMinutes[k]||0) + ms/60000;
  try{ saveData(); }catch(e){}
}
function handleAppUsageForegroundChange(isActive){
  if(isActive === lastAppUsageState) return;
  lastAppUsageState = isActive;
  if(isActive){
    appUsageSessionStart = Date.now();
    if(!appUsageFlushTimer) appUsageFlushTimer = setInterval(()=>flushAppUsage(), 60000);
  } else {
    flushAppUsage();
    appUsageSessionStart = null;
    if(appUsageFlushTimer){ clearInterval(appUsageFlushTimer); appUsageFlushTimer = null; }
  }
}
let lastAppForegroundState = true;
// ================= فلاش اضطراریِ سیوِ ابری، لحظه‌ی رفتن به پس‌زمینه =================
// saveData() یه سیو رو تا ۳۵۰ میلی‌ثانیه debounce می‌کنه قبل از پوش‌کردنش به ابر
// (user_data روی Supabase). تا اینجای کار، اگه درست وسط اون ۳۵۰ میلی‌ثانیه کاربر
// اپ رو ببنده و بلافاصله آنینستال کنه یا از تنظیماتِ اندروید «پاک کردن دیتا» بزنه،
// اون آخرین تغییر می‌تونست هیچ‌وقت به ابر نرسه. نکته‌ی مهم: برای رسیدن به هر دوی این
// کارها (آنینستال / پاک کردنِ دیتا)، کاربر اول باید از اپ خارج بشه (بره صفحه‌ی اصلی/
// تنظیمات) — یعنی همیشه یه appStateChange/visibilitychange=hidden قبلش اتفاق می‌افته.
// برای همین، دقیقاً همون لحظه که اپ می‌ره پس‌زمینه، به‌جای صبر کردن برای تایمر، فوراً
// و بدون تاخیر یه پوش می‌زنیم — این‌جوری تا وقتی کاربر واقعاً از اپ خارج نشده، هیچ
// تغییری بیشتر از چند میلی‌ثانیه رو دستگاه تنها نمی‌مونه.
function flushPendingCloudSave(){
  if(!sb || !publicChatUser) return;
  clearTimeout(saveTimeout);
  pushCloudData();
}
function handleAppForegroundChange(isActive){
  if(!sb) return;
  if(isActive === lastAppForegroundState) return;
  lastAppForegroundState = isActive;
  if(isActive){
    try{ sb.auth.startAutoRefresh(); }catch(e){}
    // اگه اینجا هم سشن null برگرده (و خودمون عمداً signOut نزده باشیم)، همون مسیر
    // «چندبار دوباره چک کن قبل از باور کردن» رو طی می‌کنیم، نه خروج فوری —
    // دقیقاً همون دلیلی که initChatAuth's onAuthStateChange این کار رو می‌کنه.
    sb.auth.getSession().then(({data})=>{
      if(!data.session && !intentionalSignOut) confirmRealSignOut();
      else handlePublicChatSession(data.session);
    }).catch(()=>{
      // fetch اصلاً انجام نشد (مثلاً درست همون لحظه که گوشی از خواب بیدار شده و شبکه
      // هنوز وصل نیست) — به‌جای سکوت کامل، همون مسیر retry+network-aware رو صدا می‌زنیم
      // تا وقتی شبکه برگشت، خودش وضعیت واقعی رو تایید کنه.
      if(!intentionalSignOut) confirmRealSignOut();
    });
  } else {
    try{ sb.auth.stopAutoRefresh(); }catch(e){}
    flushPendingCloudSave();
  }
}
// Extra safety net (همون منطقِ pauseMusicForBackground بالاتر): بعضی WebViewهای
// اندروید موقع دکمه‌ی خانه/اپ‌های اخیر، visibilitychange رو قابل‌اعتماد نمی‌زنن، ولی
// pagehide رو تقریباً همیشه می‌زنن.
window.addEventListener('pagehide', flushPendingCloudSave);
document.addEventListener('visibilitychange', ()=>{
  if(document.visibilityState === 'visible'){
    resetPremiumPayBtnIfStuck();
    try{ updateLiveCounter(); }catch(e){}
  }
  handleAppForegroundChange(document.visibilityState === 'visible');
  handleAppUsageForegroundChange(document.visibilityState === 'visible');
});
async function iabVerifyOnServer(purchase){
  try{
    const __auth = await authHeaders();
    iabDebugStep('ارسال تایید به سرور (iab/verify)', null, 'auth header ارسال شد؟ ' + !!__auth.Authorization);
    // مهم: ورکر یه چک دقیق و حساس به حروف بزرگ/کوچک می‌کنه (store === "bazaar" یا
    // === "myket")؛ اگه پلاگین نیتیو یه‌روزی «Myket»/«MYKET» یا فاصله‌ی اضافه برگردونه،
    // بدون این normalize، ورکر بی‌سروصدا verified=false می‌مونه و فقط «خرید تایید نشد»
    // برمی‌گرده — بدون هیچ سرنخی که مشکل دقیقاً از عدم تطابق حروف بوده.
    const normalizedStore = String(purchase.store || '').trim().toLowerCase();
    const res = await fetch(WORKER_BASE + '/iab/verify', {
      method:'POST', headers: Object.assign({'Content-Type':'application/json'}, __auth),
      body: JSON.stringify({ store: normalizedStore, sku: purchase.sku, purchaseToken: purchase.purchaseToken })
    });
    const data = await res.json().catch(()=>null);
    // قبلاً اینجا هیچ لاگی نبود؛ اگه ورکر خطا می‌داد یا جواب JSON نبود، کاملاً بی‌صدا
    // فقط ok:false برمی‌گشت و از کنسول هیچ سرنخی برای دیباگ نبود.
    if(!res.ok || !data || data.ok !== true){
      console.error('[IAB] iab/verify ناموفق. HTTP status:', res.status, '| auth header ارسال شد؟', !!__auth.Authorization, '| بدنه‌ی پاسخ:', data);
      iabDebugStep('پاسخ iab/verify', false, 'HTTP ' + res.status + ' | ' + JSON.stringify(data));
    } else {
      iabDebugStep('پاسخ iab/verify', true, JSON.stringify(data));
    }
    return data || { ok:false };
  }catch(e){
    console.error('[IAB] iab/verify درخواست fetch fail شد:', (e && e.message) || e);
    iabDebugStep('iab/verify (fetch)', false, (e && e.message) || String(e));
    return { ok:false };
  }
}
/* بعد از اینکه ورکر ok:true برگردوند، به جای اینکه کورکورانه بهش اعتماد کنیم، خودمون
   مستقیم از Supabase چک می‌کنیم profiles.premium_until واقعاً آپدیت شده یا نه. اگه
   ورکر باگ داشته باشه (مثلاً برای مایکت verify رو درست انجام نداده یا ذخیره نکرده)،
   این جلوی اون حالت رو می‌گیره که کاربر تست "فعال شد 🎉" ببینه ولی چند لحظه بعد
   (با اولین رفرش سشن) دوباره غیرپرمیوم بشه — منبع حقیقت همیشه همینجاست، نه پاسخ ورکر. */
async function confirmPremiumOnServer(trustedPremiumUntilHint){
  // اگه ورکر خودش premiumUntil رو تو پاسخ iab/verify برگردونده باشه (فقط بعد از چک
  // grantRes.ok، پس مطمئنیم واقعاً نوشته شده)، به‌جاش یه رفت‌وبرگشت شبکه‌ی جداگونه و کند
  // نمی‌زنیم؛ این مقدار رو مستقیم معتبر می‌دونیم و فوراً ادامه می‌دیم. برای اطمینان بیشتر
  // (بدون بلاک کردن UI)، یه چک واقعی از Supabase رو پس‌زمینه هم می‌زنیم که فقط تو پنل
  // دیباگ لاگ بشه.
  if(trustedPremiumUntilHint && new Date(trustedPremiumUntilHint) > new Date()){
    iabDebugStep('تایید نهایی از Supabase (profiles.premium_until)', true, 'از پاسخ iab/verify گرفته شد (بدون رفت‌وبرگشت اضافه): ' + trustedPremiumUntilHint);
    if(sb && publicChatUser){
      sb.from('profiles').select('premium_until').eq('id', publicChatUser.id).single()
        .then(({data})=>{
          const ok = !!(data && data.premium_until && new Date(data.premium_until) > new Date());
          if(!ok) console.warn('[IAB] چک پس‌زمینه‌ی Supabase با پاسخ ورکر همخونی نداشت:', data);
        }).catch(()=>{});
    }
    return true;
  }
  if(!sb || !publicChatUser){
    iabDebugStep('تایید نهایی از Supabase', false, 'sb یا publicChatUser موجود نیست (یعنی لاگین نبودی)');
    return isAppOwner === true;
  }
  try{
    const { data } = await sb.from('profiles').select('premium_until').eq('id', publicChatUser.id).single();
    const ok = !!(data && data.premium_until && new Date(data.premium_until) > new Date());
    iabDebugStep('تایید نهایی از Supabase (profiles.premium_until)', ok, data);
    return ok;
  }catch(e){ iabDebugStep('تایید نهایی از Supabase', false, (e && e.message) || String(e)); return false; }
}

/* ==================== Lifetime-capacity (500 slots) — REAL counter ====================
   قیمت فعلیِ لایف‌تایم فقط برای ۵۰۰ نفر اوله. عدد باقیمانده هیچ‌وقت تو کلاینت ساخته
   نمی‌شه — همیشه از جدول premium_capacity رو Supabase خونده می‌شه، و فقط زمانی کم
   می‌شه که یه خرید واقعاً رو سرور تایید بشه (بعد از confirmPremiumOnServer===true)،
   از طریق تابع claim_lifetime_slot که سمت دیتابیسه (idempotent per user — دوبار
   شمرده نمی‌شه، حتی اگه کاربر چندبار «بازیابی خرید» بزنه).
   نیازمند SQL همراه این فایل: premium-capacity-supabase-schema.sql (یک‌بار تو
   Supabase SQL editor اجرا بشه). تا وقتی اون فایل اجرا نشده، این ویجت فقط مخفی
   می‌مونه و بقیه‌ی فلوی خرید دست‌نخورده کار می‌کنه. */
let lifetimeSlotsRemaining = null;
let lifetimeSlotsTotal = 500;

function renderLifetimeScarcity(){
  const box = document.getElementById('premScarcityBox');
  const soldOutBox = document.getElementById('premScarcitySoldOut');
  const countEl = document.getElementById('premScarcityCount');
  const fillEl = document.getElementById('premScarcityFill');
  if(!box || !soldOutBox) return;
  if(lifetimeSlotsRemaining === null){ box.style.display = 'none'; soldOutBox.style.display = 'none'; return; }
  const owned = !!storeData.premium;
  if(owned){ box.style.display = 'none'; soldOutBox.style.display = 'none'; return; }
  if(lifetimeSlotsRemaining <= 0){
    box.style.display = 'none';
    soldOutBox.style.display = '';
    return;
  }
  soldOutBox.style.display = 'none';
  box.style.display = '';
  countEl.textContent = lifetimeSlotsRemaining.toLocaleString('fa-IR');
  const pct = Math.max(0, Math.min(100, (lifetimeSlotsRemaining / lifetimeSlotsTotal) * 100));
  fillEl.style.width = pct + '%';
  box.classList.toggle('low', lifetimeSlotsRemaining <= 50);
  // Buy button reflects real capacity too — no more purchases start once the 500 slots are gone.
  const payBtn = document.getElementById('premiumPayBtn');
  if(payBtn) payBtn.disabled = false;
}

async function loadLifetimeRemaining(){
  if(!sb) return;
  try{
    const { data, error } = await sb.rpc('get_lifetime_remaining');
    if(error) throw error;
    if(data && typeof data.remaining === 'number'){
      lifetimeSlotsRemaining = data.remaining;
      lifetimeSlotsTotal = data.total || 500;
    } else if(typeof data === 'number'){
      lifetimeSlotsRemaining = data;
    }
  }catch(e){
    // اگه SQL همراه هنوز اجرا نشده یا شبکه قطعه، ویجت فقط مخفی می‌مونه (fail silent) —
    // نباید جلوی خرید عادی رو بگیره.
    console.error('get_lifetime_remaining error', e);
  }
  renderLifetimeScarcity();
}

/* هر بار یه خرید رو سرور واقعاً تایید بشه (reallyActivated === true) صدا زده می‌شه.
   claim_lifetime_slot سمت دیتابیس چک می‌کنه این کاربر قبلاً شمرده شده یا نه (ستون
   profiles.lifetime_slot_claimed)، پس اگه چندبار صدا زده بشه (مثلاً هم از فلوی خرید
   مستقیم هم از «بازیابی خرید») باز درست فقط یک‌بار کم می‌شه. */
async function claimLifetimeSlotIfNeeded(){
  if(!sb || !publicChatUser) return;
  try{
    const { data, error } = await sb.rpc('claim_lifetime_slot', { p_uid: publicChatUser.id });
    if(error) throw error;
    if(data && typeof data.remaining === 'number'){
      lifetimeSlotsRemaining = data.remaining;
      lifetimeSlotsTotal = data.total || lifetimeSlotsTotal;
    }
  }catch(e){ console.error('claim_lifetime_slot error', e); }
  renderLifetimeScarcity();
}

/* لایو: اگه یه نفر دیگه (رو یه دستگاه دیگه) همون لحظه بخره، عدد بدون رفرش صفحه
   خودش کم می‌شه — چون منبعش واقعاً ردیف زنده‌ی premium_capacity تو Supabase‌ه. */
function watchLifetimeCapacity(){
  if(!sb) return;
  try{
    sb.channel('premium_capacity_watch')
      .on('postgres_changes', { event:'UPDATE', schema:'public', table:'premium_capacity' }, (payload)=>{
        if(payload && payload.new && typeof payload.new.remaining === 'number'){
          lifetimeSlotsRemaining = payload.new.remaining;
          lifetimeSlotsTotal = payload.new.total || lifetimeSlotsTotal;
          renderLifetimeScarcity();
        }
      })
      .subscribe();
  }catch(e){ console.error('watchLifetimeCapacity error', e); }
}


/* ==================== Exit confirmation (with Dream Coach) ==================== */
const EXIT_MESSAGES = [
  "مطمئنی می‌خوای بری؟ هنوز کلی مسیر تا قله مونده 🏔️",
  "وایسا! امروز رو هنوز کامل تیک نزدی‌ها 👀",
  "رفتن اشکالی نداره، فقط مطمئن شو که واقعاً همینو می‌خوای",
  "همین الان؟ باشه، ولی من همیشه همین‌جام برات",
  "یه لحظه صبر کن... مطمئنی می‌خوای از این صفحه بری بیرون؟",
  "قبل رفتن یادت باشه، فردا دوباره منتظرتم 😊",
  "بدون خداحافظی نریا! واقعاً می‌خوای خارج بشی؟",
  "باشه، ولی یادت نمونه این مسیر رو خودت انتخاب کردی 💪"
];
function pickExitMessage(){ return EXIT_MESSAGES[Math.floor(Math.random()*EXIT_MESSAGES.length)]; }

/* ---- Exit-cloud: a second, personalized speech-cloud above the mascot's head on the
   exit-confirm screen — separate from the generic exitBubble line below it (pickExitMessage
   above, untouched). Instead of a random line, this one reacts to what the user actually did
   *today* (and this week for the workout check): checks a short list of conditions in
   priority order and returns the first match, each with its own coach mood so the mascot's
   face matches the tone. Falls back to a warm generic line when nothing specific stands out.
   Every condition is seeded off todayKey() (same pattern as getCoachData/seededPick elsewhere)
   so the line stays stable across re-opens the same day instead of reshuffling every tap.

   Beyond the original day-level signals (chat time, discipline, workout, unfinished plan,
   streak), this also reacts to the SPECIFIC habit the person is fighting — not just "how'd
   today go" in general but "how'd today go with the exact thing you told us about" — using
   storeData.urgeLog (the SOS screen's per-moment log of resisted:true/false + category) for
   what actually happened TODAY with a real urge, and storeData.profile.addictions (picked at
   onboarding, via ADDICTION_EXIT_PERSONA above) as a fallback voice for the unfinished-plan
   nudge when nothing urge-specific happened today — e.g. someone working on پرخوری hears
   something like "نترس، کمکت می‌کنم شکمو بودنو کم‌کم بذاری کنار" instead of a one-size-
   fits-all line. ---- */
function pickExitCloudMessage(){
  const name = (storeData.profile && storeData.profile.firstName) ? storeData.profile.firstName.trim() : '';
  const namePart = name ? (name+'، ') : '';
  const tk = todayKey();
  const seed = tk+'-exitcloud';

  // ۱) امروز خیلی تو چت عمومی وقت گذاشته
  const chatToday = (storeData.dailyFeatureLog && storeData.dailyFeatureLog[tk] && storeData.dailyFeatureLog[tk].chat) || 0;
  if(chatToday >= 15){
    return { mood:'concerned', text: seededPick([
      namePart+'خیلی داری وقتتو با چت‌کردن هدر می‌دی، حس می‌کنم.',
      namePart+'امروز بیشتر وقتت رفت رو چت؛ یه‌کم هم برای بقیه‌ی برنامه‌ت بذار.',
      namePart+'چت جای خوبیه برای هم‌مسیر شدن، ولی زیادیش وقتتو می‌گیره‌ها.'
    ], seed+'-chat') };
  }

  // ۲) لغزش امروز: اگه امروز از دکمه‌ی SOS استفاده کرده و مقاومت نکرده، نه سرزنش که دلگرمی —
  //    دقیقاً روی همون عادتی که باهاش درگیره، نه یه پیام یکسان برای همه.
  const todaysUrges = (storeData.urgeLog||[]).filter(u=> u && u.ts && woDayKeyOf(u.ts) === tk);
  const todaysSlip = todaysUrges.find(u=> !u.resisted);
  if(todaysSlip){
    const addId = SOS_CAT_TO_ADDICTION[todaysSlip.category] || 'other';
    const persona = ADDICTION_EXIT_PERSONA[addId];
    if(persona){
      return { mood:'gentle', text: namePart+fillX(seededPick(persona.comfort, seed+'-slip-'+addId)) };
    }
  }

  // ۳) مقاومت امروز: اگه امروز جلوی یه وسوسه‌ی مشخص ایستاده، دقیقاً همونو تشویقش کن.
  const todaysWin = todaysUrges.find(u=> u.resisted);
  if(todaysWin){
    const addId = SOS_CAT_TO_ADDICTION[todaysWin.category] || 'other';
    const persona = ADDICTION_EXIT_PERSONA[addId];
    if(persona){
      return { mood:'cheer', text: namePart+fillX(seededPick(persona.praise, seed+'-win-'+addId)) };
    }
  }

  // ۴) نظم امروز: هم مدیتیشن کرده هم کل برنامه‌ی امروز رو تیک زده
  const doItems = getDoItems(), avoidItems = getAvoidItems();
  const doneCount = doItems.filter((_,i)=> entry.done[i]).length + avoidItems.filter((_,i)=> entry.avoidDone[i]).length;
  const totalToday_ = doItems.length + avoidItems.length;
  const meditatedToday = !!(storeData.meditationLog && storeData.meditationLog[tk]);
  if(meditatedToday && totalToday_>0 && doneCount>=totalToday_){
    return { mood:'proud', text: seededPick([
      namePart+'تو یه آدم منظمی، بهت افتخار می‌کنم.',
      namePart+'هم مدیتیشن، هم برنامه‌ی امروز کامل — دقیقاً همینه که فرق می‌کنه.',
      namePart+'امروزتو کامل بردی. همینطوری ادامه بده.'
    ], seed+'-disciplined') };
  }

  // ۵) ورزشکاری: امروز تمرین کرده یا این هفته منظم رفته
  const woHist = (storeData.woHistory && storeData.woHistory.history) || [];
  const didWorkoutToday = woHist.some(h=> woDayKeyOf(h.ts) === tk);
  const recentWorkoutDays = new Set();
  woHist.forEach(h=>{
    const k = woDayKeyOf(h.ts);
    const diff = Math.round((new Date(tk+'T00:00:00') - new Date(k+'T00:00:00'))/86400000);
    if(diff>=0 && diff<7) recentWorkoutDays.add(k);
  });
  if(didWorkoutToday || recentWorkoutDays.size>=4){
    return { mood:'cheer', text: seededPick([
      namePart+'ایول بابا ورزشکار! بهت افتخار می‌کنم.',
      namePart+'بدنسازی رو جدی گرفتی‌ها، همینطوری ادامه بده.',
      namePart+'داری واقعاً رو بدنت کار می‌کنی. آفرین.'
    ], seed+'-athlete') };
  }

  // ۶) عنوان هویتی جدید امروز: اگه امروز یه عنوان مثل «نقاش» یا «نویسنده» تازه باز شده،
  //    دقیقاً همونو تبریک بگه، نه یه پیام کلی.
  const newIdentityToday = FOCUS_IDENTITIES.find(fi=>{
    const at = storeData.badges && storeData.badges[fi.id];
    return typeof at === 'string' && woDayKeyOf(at) === tk;
  });
  if(newIdentityToday){
    return { mood:'proud', text: seededPick([
      namePart+'امروز رسماً «'+newIdentityToday.title+'» شدی '+newIdentityToday.emoji+' بهت افتخار می‌کنم.',
      namePart+'از امروز یه «'+newIdentityToday.title+'» هستی '+newIdentityToday.emoji+' همینطوری ادامه بده.'
    ], seed+'-newidentity') };
  }

  // ۷) برنامه‌ی امروز هنوز کامل نشده — اگه یه عادت مشخص داره روش کار می‌کنه، گاهی دقیقاً
  //    روی همون تمرکز کن، نه فقط یه یادآوری یکسان برای همه.
  if(totalToday_>0 && doneCount<totalToday_){
    const pool = [
      namePart+'حواست هست برنامه‌ی امروزو کامل کنی دیگه؟',
      namePart+'هنوز چندتا کار از امروز مونده؛ قبل رفتن یه نگاه بنداز.',
      namePart+'برنامه‌ی امروزت هنوز تموم نشده‌ها.'
    ];
    const dailyAddId = primaryAddictionOfDay();
    const dailyPersona = dailyAddId && ADDICTION_EXIT_PERSONA[dailyAddId];
    if(dailyPersona) dailyPersona.comfort.forEach(t=> pool.push(namePart+fillX(t)));
    return { mood:'concerned', text: seededPick(pool, seed+'-unfinished') };
  }

  // ۸) استریک بلند و پیوسته
  const streak = computeStreak();
  if(streak>=7){
    return { mood:'excited', text: seededPick([
      namePart+toFa(streak)+' روزه داری ادامه می‌دی، واقعاً بهت افتخار می‌کنم.',
      namePart+'این استریک '+toFa(streak)+' روزه یعنی داره عادت می‌شه. عالیه.'
    ], seed+'-streak') };
  }

  // ۹) پیش‌فرض، وقتی هیچ‌کدوم از موارد بالا صدق نمی‌کنه
  return { mood:'gentle', text: seededPick([
    namePart+'همین امروز رو از دست نده، هنوز وقت داری.',
    namePart+'هر روز که کنارتم، یه قدم جلوتری.',
    namePart+'قبل رفتن، یه نگاه به برنامه‌ت بنداز.'
  ], seed+'-default') };
}

function showExitConfirm(){
  const cloud = pickExitCloudMessage();
  const coachEl = document.getElementById('exitCoachAvatar');
  if(coachEl) coachEl.innerHTML = buildCoachSVG(cloud.mood, 'exitconfirm');
  const cloudBox = document.getElementById('exitCloudBubble');
  const cloudText = document.getElementById('exitCloudText');
  if(cloudBox && cloudText){
    cloudText.textContent = cloud.text;
    cloudBox.style.display = '';
    // re-trigger the pop-in animation every time the screen opens, not just the first time
    cloudBox.classList.remove('exit-cloud-pop');
    void cloudBox.offsetWidth;
    cloudBox.classList.add('exit-cloud-pop');
  }
  document.getElementById('exitMsgText').textContent = pickExitMessage();
  const ov = document.getElementById('exitOverlay');
  ov.classList.remove('leaving');
  ov.classList.add('show');
  sfxAppExit(); // distinct descending chime — mirrors sfxAppEnter played on the splash/entry screen
}
function hideExitConfirm(){
  const ov = document.getElementById('exitOverlay');
  ov.classList.remove('leaving');
  ov.classList.remove('show');
}
function doRealExit(){
  try{
    if(window.Capacitor && Capacitor.Plugins && Capacitor.Plugins.App && Capacitor.Plugins.App.exitApp){
      Capacitor.Plugins.App.exitApp(); return;
    }
  }catch(e){}
  try{ window.close(); }catch(e){}
}
document.getElementById('exitStayBtn').addEventListener('click', hideExitConfirm);
document.getElementById('exitLeaveBtn').addEventListener('click', ()=>{
  // فقط برای همین خروج، فید بستن رو خیلی سریع‌تر از حالت پیش‌فرض overlay/card
  // می‌کنیم (استایل inline، فقط رو همین overlay) تا کاربر معطل نمونه — روی
  // بقیه‌ی اورلی‌های هم‌کلاس (aiGate/inviteNudge/authGate) اثری نداره.
  const ov = document.getElementById('exitOverlay');
  const card = ov.querySelector('.exit-card');
  ov.style.transition = 'opacity .1s ease';
  if(card) card.style.transition = 'opacity .1s ease, transform .1s ease';
  ov.classList.remove('leaving');
  ov.classList.remove('show');
  setTimeout(()=>{
    doRealExit();
    ov.style.transition = '';
    if(card) card.style.transition = '';
  }, 110);
});

function isOverlayShown(id){
  const el = document.getElementById(id);
  if(!el) return false;
  if(el.classList.contains('show')) return true;
  return !!(el.style.display && el.style.display !== 'none');
}
function closeDismissableOverlay(){
  if(isOverlayShown('photoEditorOverlay')){ peCancel(); return true; }
  if(isOverlayShown('videoEditorOverlay')){ veCancel(); return true; }
  if(isOverlayShown('gifPickerOverlay')){ closeGifPicker(); return true; }
  if(isOverlayShown('notifPanelOverlay')){ closeNotifPanel(); return true; }
  if(isOverlayShown('chatMembersOverlay')){ closeChatMembers(); return true; }
  if(isOverlayShown('sideMenuOverlay')){ document.getElementById('sideMenuOverlay').classList.remove('show'); return true; }
  if(isOverlayShown('sosOverlay')){ document.getElementById('sosOverlay').classList.remove('show'); return true; }
  if(isOverlayShown('celebrateOverlay')){ document.getElementById('celebrateOverlay').classList.remove('show'); return true; }
  if(isOverlayShown('aiGateOverlay')){ hideAIGate(); return true; }
  if(isOverlayShown('inviteNudgeOverlay')){ hideInviteNudge(); return true; }
  if(isOverlayShown('authGateOverlay')){ pendingAuthTab = null; hideAuthGate(); return true; }
  return false;
}
function handleHardwareBack(){
  if(isOverlayShown('exitOverlay')){ hideExitConfirm(); return; }
  if(closeDismissableOverlay()) return;
  if(isOverlayShown('onboardOverlay')) return; // mid-onboarding: ignore back, avoid losing entered data
  if(document.body.classList.contains('subpage-open')){ exitSubPage(); return; }
  showExitConfirm();
}
(function setupBackButton(){
  try{
    if(window.Capacitor && Capacitor.Plugins && Capacitor.Plugins.App){
      Capacitor.Plugins.App.addListener('backButton', handleHardwareBack);
    }
  }catch(e){}
  try{
    history.pushState({dreamlifeGuard:true}, '');
    window.addEventListener('popstate', ()=>{
      history.pushState({dreamlifeGuard:true}, '');
      handleHardwareBack();
    });
  }catch(e){}
})();

/* ==================== Premium overlay: open/close + IAB flow ====================
   چون تخفیف فقط از گردونه‌ی دعوت میاد و همیشه یکی از همین ۴ درصده (نه هر عددی)،
   به‌جای «کد تخفیف» که تو IAB اصلاً معنی نداره، برای هر پله یه SKU جدا با قیمت
   تخفیف‌خورده تو پنل مایکت ثبت می‌کنیم و اپ خودش SKU درست رو صدا می‌زنه.
   قیمت پایه (SKU: premium) همونیه که رو کارت قیمت نشون داده می‌شه: ۱,۳۵۰,۰۰۰ تومان.
   بقیه‌ی SKUها باید دقیقاً روی همین مبنا، با همین درصدها، تو پنل مایکت ساخته بشن:
     premium        (۰٪)  → ۱,۳۵۰,۰۰۰ تومان
     premium_20off  (۲۰٪) → ۱,۰۸۰,۰۰۰ تومان
     premium_30off  (۳۰٪) →   ۹۴۵,۰۰۰ تومان
     premium_40off  (۴۰٪) →   ۸۱۰,۰۰۰ تومان
     premium_50off  (۵۰٪) →   ۶۷۵,۰۰۰ تومان
   اگه قیمت پایه‌ی رو کارت (بالا، prem-price-value) عوض شد، این ۴ SKU هم باید با همون
   درصدها دوباره محاسبه و تو پنل مایکت آپدیت بشن — وگرنه تخفیف واقعی با درصدی که
   به کاربر نشون داده می‌شه یکی نیست. */
const PREMIUM_SKU_BY_DISCOUNT = { 0: 'premium', 20: 'premium_20off', 30: 'premium_30off', 40: 'premium_40off', 50: 'premium_50off' };
function currentPremiumSku(){
  return PREMIUM_SKU_BY_DISCOUNT[myDiscount.percent] || 'premium';
}
async function openPremiumPage(){
  // ابتدا profile رو از سرور refresh کنیم تا مطمئن شویم premium status صحیح است
  // این جلوگیری می‌کند از اینکه کاربر پرمیوم دکمهٔ خرید ببیند
  try{
    if(publicChatUser && publicChatUser.id){
      const res = await sb.from('profiles').select('premium_until, referral_code, discount_percent, discount_code, wheel_spun').eq('id', publicChatUser.id).single();
      if(res.data){
        myProfileCache = res.data;
        // premium status رو دقیق بر اساس سرور update کنیم
        storeData.premium = isAppOwner || !!(res.data.premium_until && new Date(res.data.premium_until) > new Date());
        saveData();
      }
    }
  }catch(err){
    console.warn('Failed to refresh premium status before opening premium page:', err);
    // اگه fetch fail شد، حداقل UI رو بر اساس آخرین storeData refresh کنیم
  }
  
  let discBadge = document.getElementById('premiumDiscountBadge');
  if(!discBadge){
    discBadge = document.createElement('div');
    discBadge.id = 'premiumDiscountBadge';
    discBadge.style.cssText = 'margin:0 0 12px;padding:10px;border-radius:12px;background:var(--accent-soft);border:1px solid var(--accent);color:var(--accent);font-size:12.5px;font-weight:700;text-align:center;';
    document.getElementById('premiumPayBtn').insertAdjacentElement('beforebegin', discBadge);
  }
  if(myDiscount.percent > 0){
    discBadge.style.display = 'block';
    discBadge.style.cursor = 'default';
    discBadge.onclick = null;
    discBadge.innerHTML = `🎁 ${myDiscount.percent}٪ تخفیف فعاله — دکمه‌ی پرداخت خودکار با قیمت تخفیف‌خورده باز می‌شه`;
  } else {
    discBadge.style.display = 'block';
    discBadge.style.cursor = 'pointer';
    discBadge.innerHTML = `🎁 با دعوت از دوستات تا ۵۰٪ تخفیف بگیر`;
    discBadge.onclick = ()=>{ enterSubPage('invite'); };
  }
  renderPremiumPurchaseUI();
  applyPremiumLocksUI(); // اطمینان دهیم که قفل‌ها به‌روز شوند
  loadLifetimeRemaining();
  enterSubPage('premium');

  // چک سبک و کاملاً fire-and-forget: آیا اصلاً سرویس بیلینگ مایکت رو این گوشی در
  // دسترسه؟ هدف اینه که به‌جای اینکه کاربر دکمه رو بزنه و بعد با یه خطای گنگ مواجه بشه،
  // همین‌جا (قبل از کلیک) یه هشدار واضح ببینه. اگه این چک خودش fail بشه یا کند باشه،
  // هیچ تاثیری رو باز شدن صفحه یا کارکرد دکمه‌ی خرید نداره — کاملاً مستقله.
  (async function checkStoreAvailability(){
    try{
      let banner = document.getElementById('premStoreMissingBanner');
      const payBtn = document.getElementById('premiumPayBtn');
      function showBanner(msg){
        if(!banner && payBtn){
          banner = document.createElement('div');
          banner.id = 'premStoreMissingBanner';
          banner.style.cssText = 'margin:0 0 12px;padding:10px;border-radius:12px;background:#fee2e2;border:1px solid #ef4444;color:#b91c1c;font-size:12.5px;font-weight:700;text-align:center;';
          payBtn.insertAdjacentElement('beforebegin', banner);
        }
        if(banner){ banner.style.display = 'block'; banner.textContent = msg; }
      }
      const plugin = getIabPlugin();
      if(!plugin){ showBanner('⚠️ این نسخه هنوز به پرداخت درون‌برنامه‌ای وصل نشده'); return; }
      const res = await withTimeout(plugin.getStore(), 4000);
      const store = res && res.store;
      if(!store || store === 'none'){
        showBanner('⚠️ برنامه‌ی مایکت روی این گوشی پیدا نشد — برای خرید باید نصب و به‌روز باشه');
      } else if(banner){
        banner.style.display = 'none';
      }
    }catch(err){
      console.warn('[IAB] checkStoreAvailability fail شد (بی‌ضرره، تاثیری رو خرید نداره):', err);
    }
  })();
}
// Backward-compatible alias (kept in case anything else in the app still calls the old name)
function openPremiumOverlay(){ openPremiumPage(); }

/* ==================== فینالایز کردن فعال‌سازی پرمیوم — نقطه‌ی مشترک واحد ====================
   قبلاً این منطق (claim slot، consume، رفرش UI، خروج از ساب‌پیج، جشن) دوبار جدا
   تو هندلر «خرید» و هندلر «بازیابی» نوشته شده بود — با یه فرق ظریف: مسیر خرید
   celebration کامل نشون می‌داد، مسیر بازیابی فقط یه toast ساده. حالا هر دو (و هر
   مسیر خودکار جدیدی که بعداً اضافه بشه) از همینجا رد می‌شن، پس همیشه دقیقاً یکی‌ان.
   exitSubPage فقط وقتی صدا زده می‌شه که واقعاً تو همون ساب‌پیج پرمیوم باشیم — وگرنه
   (مثلاً وقتی فعال‌سازی خودکار پشت‌صحنه، حین بودن تو یه تب دیگه اتفاق افتاده) کاربر
   رو از جایی که داشت باهاش کار می‌کرد بیرون نمی‌ندازه. ولی خودِ جشن/ویژوالایزر
   (premSuccessOverlay) یه overlay سراسریه، مستقل از تب فعلی — همیشه نشون داده می‌شه.
   purchaseForConsume اختیاریه (بازیابیِ بدون purchaseToken مشخص هم باید کار کنه). */
async function finalizePremiumActivationUI(purchaseForConsume){
  storeData.premium = true; saveData();
  await claimLifetimeSlotIfNeeded();
  try{
    const plugin = getIabPlugin();
    if(plugin && plugin.consumePurchase && purchaseForConsume && purchaseForConsume.purchaseToken){
      await plugin.consumePurchase({ purchaseToken: purchaseForConsume.purchaseToken });
    }
  }catch(e){ /* عدم موفقیت consume نباید فعال‌سازی که سرور تاییدش کرده رو خراب کنه */ }
  renderPremiumPurchaseUI();
  if(typeof applyPremiumLocksUI === 'function') applyPremiumLocksUI();
  const premiumTabEl = document.getElementById('tab-premium');
  if(premiumTabEl && premiumTabEl.classList.contains('active')) exitSubPage();
  showPremiumSuccessCelebration();
}

/* ==================== بازیابی/فعال‌سازی خودکار خرید مالکیت‌شده ====================
   همون کاری که قبلاً فقط با کلیک دستی رو «بازیابی خرید قبلی» انجام می‌شد، حالا از
   سه‌جا صدا زده می‌شه:
     ۱) خودِ دکمه‌ی «بازیابی خرید قبلی» (کلیک دستی، silent:false — خطاها toast می‌شن).
     ۲) وقتی purchase() نیتیو timeout بشه (مثلاً بعد از شارژ کیف‌پول مایکت وسط خرید،
        که نتیجه‌ی خرید هیچ‌وقت به onActivityResult برنمی‌گرده — درحالی‌که خودِ خرید
        رو مارکت واقعاً ثبت شده). silent:true — نبودنِ خرید یعنی «واقعاً هنوز نخریده»،
        نه یه خطا که باید نشونش بدیم.
     ۳) هر بار اپ از پس‌زمینه/مایکت برمی‌گرده، **اگه** درست همون لحظه دکمه‌ی خرید رو
        حالت قفل بود (یعنی یه خرید نیمه‌کاره‌ی واقعی وجود داشته). silent:true.
   پرچم _activatingOwnedPremium از اجرای هم‌زمان چندتایی (مثلاً چند رویداد resume
   پشت‌سرهم) جلوگیری می‌کنه. */
let _activatingOwnedPremium = false;
async function activateOwnedPremiumIfAny(opts){
  opts = opts || {};
  const silent = !!opts.silent;
  if(_activatingOwnedPremium) return false;
  if(storeData.premium) return true;
  if(!isLoggedIn()) return false;
  const plugin = getIabPlugin();
  if(!plugin) return false;
  _activatingOwnedPremium = true;
  try{
    const owned = await plugin.getPurchases();
    const premiumSkus = new Set(Object.values(PREMIUM_SKU_BY_DISCOUNT));
    const ownedPremium = owned && owned.purchases && owned.purchases.find(p=>premiumSkus.has(p.sku));
    if(!ownedPremium){
      if(!silent) showToast('خریدی برای این حساب پیدا نشد', 'error');
      return false;
    }
    // همون دلیل مسیر خرید مستقیم: فقط "owned" بودن رو مارکت کافی نیست، باید مطمئن
    // شیم سرور (profiles.premium_until) هم همینو می‌دونه.
    const ownedVerify = await iabVerifyOnServer(ownedPremium);
    const reallyActivated = await confirmPremiumOnServer(ownedVerify && ownedVerify.premiumUntil);
    if(!reallyActivated){
      if(!silent) showToast('خرید رو مارکت پیدا شد ولی سرور تاییدش نکرد؛ لطفاً با پشتیبانی تماس بگیر', 'error');
      return false;
    }
    await finalizePremiumActivationUI(ownedPremium);
    return true;
  }catch(e){
    if(!silent) showToast('مشکلی تو بررسی خرید پیش اومد', 'error');
    return false;
  }finally{
    _activatingOwnedPremium = false;
  }
}

document.getElementById('premiumPayBtn').addEventListener('click', async ()=>{
  // مهم: قبل از باز کردن درگاه پرداخت، حتماً باید کاربر لاگین باشه. اگه بدون حساب
  // خرید کنه، iabVerifyOnServer() هیچ Authorization header ای نداره (authHeaders()
  // خالی برمی‌گرده) و confirmPremiumOnServer() هم چون publicChatUser=null هست
  // همیشه false برمی‌گردونه — یعنی پول از کاربر کم می‌شه ولی پرمیوم برای همیشه
  // فعال نمی‌شه («خرید ثبت شد ولی تاییدش رو سرور کامل نشد»). این همون باگیه که
  // پشتیبانی مایکت گزارش داده: «بعد از پرداخت فیچرها باز نمی‌شن». قبلاً این تب هیچ
  // auth gate ای نداشت (برخلاف تب‌های عمومی مثل چت/لیدربورد که PUBLIC_AUTH_TABS
  // دارن). با لاگین اجباری قبل از پرداخت، هر خریدی همیشه به یه حساب واقعی وصله و
  // بعد از لاگین کاربر خودش با pendingAuthTab دوباره به همین صفحه‌ی پرمیوم برمی‌گرده.
  if(!isLoggedIn()){
    showToast('برای خرید پرمیوم اول باید یه حساب رایگان بسازی یا وارد شی', 'error');
    goToAuthPage('premium');
    return;
  }
  const btn = document.getElementById('premiumPayBtn');
  btn.disabled = true; btn.textContent = 'در حال اتصال...';
  // موقع بررسی توسط مایکت، دقیقاً همین لحظه (بین کلیک و نتیجه) بود که کارشناس هیچ
  // فیدبکی ندید و فکر کرد «هیچ اتفاقی نیفتاد» — درحالی‌که پشت‌صحنه داشت رو شبکه‌ی
  // کند تایید می‌شد. یه پیام دائمی و واضح می‌ذاریم تا معلوم باشه داره کار می‌کنه،
  // و کاربر/کارشناس چند بار پشت‌سرهم دکمه رو نزنه (که دکمه دیزیبله، ولی این پیام
  // دلیلشو هم توضیح می‌ده).
  let loadingBanner = document.getElementById('premPurchaseLoadingBanner');
  if(!loadingBanner){
    loadingBanner = document.createElement('div');
    loadingBanner.id = 'premPurchaseLoadingBanner';
    loadingBanner.style.cssText = 'margin:10px 0 0;padding:10px;border-radius:12px;background:var(--accent-soft, #eef2ff);border:1px solid var(--accent, #4338ca);color:var(--accent, #4338ca);font-size:12.5px;font-weight:700;text-align:center;';
    btn.insertAdjacentElement('afterend', loadingBanner);
  }
  loadingBanner.style.display = 'block';
  loadingBanner.textContent = '⏳ در حال تایید خرید... رو شبکه‌ی کند ممکنه تا حدود ۱-۲ دقیقه طول بکشه. لطفاً اپ رو نبند و چندبار کلیک نکن.';
  console.log('[IAB] دکمه‌ی خرید کلیک شد. sku انتخاب‌شده:', currentPremiumSku(), '| myDiscount:', myDiscount);
  iabDebugReset();
  iabDebugStep('کلیک روی دکمه‌ی خرید', true, 'sku=' + currentPremiumSku());
  try{
    const purchase = await iabPurchase(currentPremiumSku());
    if(purchase){
      console.log('[IAB] purchase از نیتیو برگشت:', purchase);
      const verify = await iabVerifyOnServer(purchase);
      console.log('[IAB] نتیجه‌ی iab/verify از ورکر:', verify);
      const reallyActivated = (verify && verify.ok) ? await confirmPremiumOnServer(verify.premiumUntil) : false;
      console.log('[IAB] reallyActivated (تایید نهایی رو Supabase):', reallyActivated);
      iabDebugStep('نتیجه‌ی کلی', reallyActivated, reallyActivated ? 'پرمیوم فعال شد 🎉' : 'فعال نشد — اولین ❌ بالا رو نگاه کن');
      if(reallyActivated){
        await finalizePremiumActivationUI(purchase);
      } else {
        // مهم: اینجا دیگه storeData.premium=true ست نمی‌کنیم، چون اگه سرور واقعاً
        // ثبتش نکرده باشه، این فلگ محلی با اولین رفرش سشن (handlePublicChatSession)
        // به false برمی‌گشت و به کاربر یه فعال‌سازی دروغین نشون داده بودیم.
        showToast('خرید ثبت شد ولی تاییدش رو سرور کامل نشد؛ چند لحظه دیگه از «بازیابی خرید قبلی» دوباره امتحان کن', 'error');
      }
    } else {
      console.log('[IAB] iabPurchase چیزی برنگردوند (null) — یعنی یا پلاگین پیدا نشد، یا خرید نیتیو fail/cancel/timeout شد؛ جزئیاتش تو لاگ‌های بالاتره.');
      iabDebugStep('نتیجه‌ی کلی', false, 'iabPurchase چیزی برنگردوند — یکی از مراحل بالا ❌ خورده');
    }
  }catch(e){
    // باگ قبلی: این بلوک اصلاً وجود نداشت (فقط try/finally بود، بدون catch). یعنی اگه
    // یه خطای پیش‌بینی‌نشده — نه از iabPurchase/iabVerifyOnServer/confirmPremiumOnServer
    // (که هرکدوم خودشون داخلی try/catch دارن و null/false برمی‌گردونن)، بلکه مثلاً از
    // finalizePremiumActivationUI یا هر کد دیگه‌ای که این‌جا صدا زده می‌شه — پرتاب می‌شد،
    // finally دکمه رو آزاد می‌کرد ولی خودِ خطا به‌صورت یه unhandled promise rejection
    // بی‌صدا گم می‌شد: از دید کاربر دکمه یه لحظه «در حال اتصال...» می‌شد و بدون هیچ toast
    // یا پیامی به حالت اول برمی‌گشت — دقیقاً همون «هیچ عملکردی نداشت» که مایکت گزارش داد.
    console.error('[IAB] خطای پیش‌بینی‌نشده تو فلوی خرید:', (e && e.message) || e, e);
    iabDebugStep('خطای پیش‌بینی‌نشده', false, (e && e.message) || String(e));
    showToast('مشکلی پیش اومد؛ دوباره امتحان کن', 'error');
  }finally{
    btn.disabled = false; btn.textContent = '💳 خرید نسخه‌ی پرمیوم';
    const loadingBannerEl = document.getElementById('premPurchaseLoadingBanner');
    if(loadingBannerEl) loadingBannerEl.style.display = 'none';
  }
});

document.getElementById('premiumCheckBtn').addEventListener('click', async ()=>{
  // همون دلیل premiumPayBtn: بدون لاگین، confirmPremiumOnServer() همیشه false
  // برمی‌گرده حتی اگه رو مارکت واقعاً owned باشه، پس بازیابی هم بدون حساب معنی نداره.
  if(!isLoggedIn()){
    showToast('برای بازیابی خرید اول باید وارد حسابت بشی', 'error');
    goToAuthPage('premium');
    return;
  }
  const btn = document.getElementById('premiumCheckBtn');
  btn.disabled = true; btn.textContent = 'در حال بررسی...';
  const plugin = getIabPlugin();
  if(!plugin){ showToast('این نسخه هنوز به پرداخت درون‌برنامه‌ای مایکت وصل نشده', 'error'); btn.disabled = false; btn.textContent = 'بازیابی خرید قبلی'; return; }
  try{
    await activateOwnedPremiumIfAny({ silent:false });
  }finally{
    btn.disabled = false; btn.textContent = 'بازیابی خرید قبلی';
  }
});

